INSERT INTO `posts` VALUES (3,'Trump Klaim Selat Hormuz Segera Dibuka Kembali, Iran Tegas Bantah Adanya Negosiasi','trump-klaim-selat-hormuz-segera-dibuka-kembali-iran-tegas-bantah-adanya-negosiasi','<p data-path-to-node=\"17\" style=\"text-align: justify; \"><b data-path-to-node=\"17\" data-index-in-node=\"0\"><b data-path-to-node=\"16\" data-index-in-node=\"68\">Keterangan Foto:</b> </b><span data-path-to-node=\"17\" data-index-in-node=\"0\">Presiden Amerika Serikat Donald Trump saat memberikan pernyataan dari meja kerjanya. (Foto: Dok. Istimewa)</span></p><p data-path-to-node=\"17\" style=\"text-align: justify; \"><span data-path-to-node=\"17\" data-index-in-node=\"0\"><b>KOLAKA, XNN</b></span> â€“ Presiden Amerika Serikat Donald Trump mengklaim bahwa jalur pelayaran strategis Selat Hormuz akan segera dibuka kembali di tengah ketegangan militer yang masih membara antara Washington dan Teheran.</p><p data-path-to-node=\"18\" style=\"text-align: justify;\">Klaim mengejutkan ini disampaikan Trump secara eksklusif dalam wawancaranya bersama jurnalis <i data-path-to-node=\"18\" data-index-in-node=\"93\">CNN</i>, Kaitlan Collins. Dalam pernyataannya, Trump menyebutkan bahwa proses pembukaan kembali urat nadi perdagangan minyak dunia itu sangat bergantung pada perkembangan negosiasi yang ia klaim sedang berlangsung.</p><p data-path-to-node=\"19\" style=\"text-align: justify;\">Lebih jauh, Trump bahkan menyinggung sebuah gagasan radikal mengenai kemungkinan pengelolaan bersama (<i data-path-to-node=\"19\" data-index-in-node=\"102\">joint management</i>) Selat Hormuz antara otoritas Amerika Serikat dan Iran. Kendati demikian, pemimpin AS tersebut tidak merinci lebih lanjut bagaimana mekanisme operasional kerja sama itu akan dijalankan di tengah putusnya hubungan diplomatik kedua negara.</p><p data-path-to-node=\"20\" style=\"text-align: justify;\">Pernyataan sepihak dari Gedung Putih ini langsung mendapat respons keras dari Teheran. Otoritas Iran dengan tegas membantah adanya jalur komunikasi resmi maupun negosiasi rahasia dengan pihak Amerika Serikat. Seorang sumber dari petinggi militer Iran menegaskan bahwa klaim Washington tersebut sama sekali tidak mencerminkan realitas yang terjadi di lapangan.</p><p data-path-to-node=\"21\" style=\"text-align: justify;\">Situasi geopolitik di kawasan tersebut kini semakin kompleks menyusul transisi kekuasaan di pucuk pimpinan Iran. Saat ini, Mojtaba Khamenei telah secara resmi memegang kendali penuh sebagai Pemimpin Tertinggi Iran. Ia menggantikan mendiang ayahnya, Ali Khamenei, yang dilaporkan meninggal dunia pada fase awal eskalasi konflik ini pecah. Kepemimpinan baru ini diyakini membawa pendekatan yang lebih keras dalam menghadapi berbagai tekanan dari AS.</p><p data-path-to-node=\"22\" style=\"text-align: justify;\">Selat Hormuz sendiri merupakan salah satu perairan paling krusial dalam distribusi energi global. Setiap gangguan, apalagi blokade di kawasan ini, dipastikan akan memicu kepanikan pasar yang berpotensi melambungkan harga minyak mentah dunia dan mengancam stabilitas ekonomi internasional.</p><p data-path-to-node=\"23\" style=\"text-align: justify; \">Hingga berita ini diturunkan, belum ada tanda-tanda konkret terkait kesepakatan pembukaan selat tersebut, dan situasi keamanan di kawasan Teluk masih terus berkembang secara dinamis.</p>','KOLAKA, XNN â€“ Presiden Amerika Serikat Donald Trump mengklaim bahwa jalur pelayaran strategis Selat Hormuz akan segera dibuka kembali di tengah kete',9,'Donald Trump, Iran, Selat Hormuz, Geopolitik, Minyak Dunia, Amerika Serikat, Timur Tengah, Konflik AS-Iran, Mojtaba Khamenei, Ekonomi Global',1,1,'published','https://www.xyronnews.com/uploads/posts/post_69c272ee3595c.jpeg',156,'2026-03-24 04:19:34'),(7,'Prabowo Tancap Gas Diplomasi Idulfitri, Hubungi Presiden Palestina hingga MBZ','w','<p style=\"text-align: justify; \"><span style=\"outline: 0px; color: rgb(33, 37, 41); font-family: Heebo, sans-serif; text-align: start;\"><b>Keterangan Foto :&nbsp;</b></span><em style=\"outline: 0px; color: rgb(33, 37, 41); font-family: Heebo, sans-serif; text-align: start;\">Momen Idul Fitri, Prabowo Hubungi Presiden Palestina.</em></p><p style=\"text-align: justify; \"><span style=\"background-color: var(--bs-card-bg); font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><br><b>JAKARTA</b></span><span style=\"background-color: var(--bs-card-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"> â€“ Presiden Prabowo Subianto langsung tancap gas memanfaatkan momentum Idulfitri 1447 Hijriah untuk memperkuat jalur diplomasi Indonesia di tengah dinamika global.</span></p><p style=\"text-align: justify; \">Melalui sambungan telepon, Prabowo menjalin komunikasi dengan sejumlah pemimpin dunia, termasuk Presiden Palestina Mahmoud Abbas dan Presiden Uni Emirat Arab Mohammed bin Zayed (MBZ).</p><p style=\"text-align: justify; \">Tak hanya itu, Presiden Mesir Abdel Fattah el-Sisi serta Perdana Menteri Malaysia Anwar Ibrahim juga turut dihubungi dalam momen hari raya tersebut.</p><p style=\"text-align: justify; \">Langkah ini dinilai bukan sekadar silaturahmi, melainkan bagian dari strategi mempererat hubungan bilateral sekaligus membuka peluang kerja sama baru di berbagai sektor.</p><p style=\"text-align: justify; \">Sebelumnya, Prabowo juga telah melakukan komunikasi dengan Presiden Turki Recep Tayyip ErdoÄŸan, Perdana Menteri Pakistan Shehbaz Sharif, Raja Yordania Abdullah II, serta Putra Mahkota Arab Saudi Mohammed bin Salman.</p><p style=\"text-align: justify; \">Rangkaian komunikasi ini mencerminkan arah diplomasi Indonesia yang semakin aktif dan adaptif, khususnya dalam memperkuat posisi di kawasan Timur Tengah dan dunia Islam.</p><p style=\"text-align: justify; \">Di tengah situasi geopolitik global yang masih dinamis, momentum Idulfitri dimanfaatkan sebagai sarana mempererat hubungan sekaligus menegaskan posisi Indonesia sebagai mitra strategis di kancah internasional.</p><p style=\"text-align: justify; \">---</p><p style=\"text-align: justify; \">Sumber: Istana Kepresidenan</p>','HOME &gt; PolitikJUDUL:Prabowo Tancap Gas Diplomasi Idulfitri, Hubungi Presiden Palestina hingga MBZXNN â€“ Xyron News NetworkSelasa, 24 Maret 2026 | ',1,'politik, prabowo, diplomasi, internasional, idulfitri',7,7,'published','https://file.fin.co.id/uploads/fin-news/images/2026/03/23/momen-idul-fitri-prabowo-hubungi-presiden-palestina-apa-yang-dibahas-232732.webp',97,'2026-03-26 06:40:37'),(8,'Rupiah Ditutup Melemah Tipis, Bertahan di Level Rp16.900-an','rupiah-ditutup-melemah-tipis-bertahan-di-level-rp16-900-an','<h6><b>Keterangan poto :&nbsp;</b><i><span style=\"font-size: var(--bs-body-font-size); text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">rupiah tercatat ditutup di kisaran&nbsp;</span><span data-start=\"526\" data-end=\"567\" style=\"font-size: var(--bs-body-font-size); text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Rp16.900 hingga Rp16.915 per dolar AS</span></i></h6><p data-start=\"210\" data-end=\"260\" style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><div style=\"text-align: justify;\"><strong data-start=\"210\" data-end=\"238\" style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\">XNN â€“ Xyron News Network</strong></div><div style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\">Jakarta, Maret 2026</span></div></p><p data-start=\"262\" data-end=\"445\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Nilai tukar rupiah terhadap dolar Amerika Serikat (AS) ditutup melemah tipis pada perdagangan akhir pekan ini, di tengah tekanan eksternal yang masih membayangi pasar keuangan global.</p><p data-start=\"447\" data-end=\"624\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><strong data-start=\"447\" data-end=\"489\">Berdasarkan sejumlah sumber data pasar</strong>, rupiah tercatat ditutup di kisaran&nbsp;<strong data-start=\"526\" data-end=\"567\">Rp16.900 hingga Rp16.915 per dolar AS</strong>, setelah bergerak fluktuatif sepanjang sesi perdagangan.</p><p data-start=\"626\" data-end=\"822\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Pergerakan rupiah tersebut dipengaruhi oleh sentimen global yang cenderung negatif, seiring meningkatnya ketidakpastian ekonomi dunia dan memanasnya tensi geopolitik di sejumlah kawasan strategis.</p><p data-start=\"824\" data-end=\"968\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Selain itu, penguatan dolar AS serta kenaikan harga energi dunia turut memberikan tekanan terhadap mata uang negara berkembang, termasuk rupiah.</p><p data-start=\"970\" data-end=\"1176\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Sejumlah analis menilai, kondisi ini mendorong investor global untuk lebih berhati-hati dan cenderung mengalihkan aset ke instrumen yang dianggap lebih aman, sehingga memicu tekanan pada nilai tukar rupiah.</p><p data-start=\"1178\" data-end=\"1424\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Meski demikian, rupiah dinilai masih berada dalam kondisi relatif stabil. Hal ini didukung oleh langkah&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">Bank Indonesia</span>yang terus melakukan intervensi di pasar valuta asing guna menjaga keseimbangan dan meredam volatilitas.</p><p data-start=\"1426\" data-end=\"1595\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Ke depan, pergerakan rupiah diperkirakan masih akan berada dalam rentang&nbsp;<strong data-start=\"1499\" data-end=\"1540\">Rp16.900 hingga Rp17.000 per dolar AS</strong>, seiring dinamika global yang belum sepenuhnya mereda.</p>','Keterangan poto :&nbsp;rupiah tercatat ditutup di kisaran&nbsp;Rp16.900 hingga Rp16.915 per dolar ASXNN â€“ Xyron News NetworkJakarta, Maret 2026Nilai',1,'Geopolitik, rupiah, Indonesia ',7,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69c588540d665.jpeg',131,'2026-03-26 12:26:12'),(9,'Pemerintah Setujui Hampir 400 Juta Ton Produksi Batu Bara dalam RKAB 2026','pemerintah-setujui-hampir-400-juta-ton-produksi-batu-bara-dalam-rkab-2026','<h6><font color=\"#636363\">Foto : Kapal tongkang Batu Bara&nbsp;</font></h6><p style=\"text-align: justify;\">XNNâ€”<font color=\"#ce0000\">Xyron News Network</font></p><p style=\"text-align: justify;\"><b>Jakarta, XNN -</b> Kementerian Energi dan Sumber Daya Mineral (ESDM) telah memberikan persetujuan terhadap rencana produksi batu bara dalam Rencana Kerja dan Anggaran Biaya (RKAB) tahun 2026 dengan jumlah yang mendekati 400 juta ton.</p><p style=\"text-align: justify;\">Direktur Jenderal Mineral dan Batu Bara (Dirjen Minerba) Kementerian ESDM, Tri Winarno, menyampaikan bahwa hingga saat ini pemerintah masih terus menuntaskan proses persetujuan seluruh pengajuan RKAB dari para pelaku usaha. Secara keseluruhan, target produksi batu bara dalam RKAB 2026 diperkirakan berada di kisaran 600 juta ton.</p><p style=\"text-align: justify;\">â€œYang sudah disetujui sekitar 390 juta ton, dan masih bergerak menuju 400 juta ton,â€ ujar Tri saat ditemui di Kantor Kementerian ESDM, Jakarta, Selasa (25/3/2026).</p><p style=\"text-align: justify;\">Tri juga menjelaskan bahwa proses persetujuan tidak hanya terjadi pada sektor batu bara, tetapi juga pada komoditas nikel. Hingga kini, pemerintah telah memberikan persetujuan untuk produksi nikel yang jumlahnya telah melampaui 100 juta ton.</p><p style=\"text-align: justify;\">â€œUntuk nikel, kurang lebih sudah di angka seratusan juta ton,â€ tambahnya di kesempatan yang sama.</p><p style=\"text-align: justify;\">Terkait keluhan sejumlah pelaku usaha mengenai lamanya proses penerbitan RKAB, Tri mengakui adanya tantangan dalam penerapan sistem baru. Menurutnya, penggunaan aplikasi digital yang baru masih memerlukan penyesuaian, terutama dalam menyelaraskan data antara perusahaan dan sistem verifikasi pemerintah.</p><p style=\"text-align: justify;\">â€œAplikasi baru ini memang masih dalam tahap penyesuaian. Baik dari sisi perusahaan maupun pemerintah harus sama-sama aktif, kalau tidak berjalan beriringan tentu prosesnya terhambat,â€ jelasnya.</p><p style=\"text-align: justify;\"><b>Rencana Penyesuaian Produksi</b></p><p style=\"text-align: justify;\">Sebelumnya, Kementerian ESDM sempat mengambil langkah untuk menurunkan target produksi batu bara dan nikel dalam RKAB 2026. Kebijakan tersebut bertujuan menjaga keseimbangan antara pasokan dan permintaan di pasar global, sehingga harga komoditas dapat tetap stabil.</p><p style=\"text-align: justify;\">Namun, perkembangan terbaru menunjukkan adanya perubahan arah kebijakan. Berdasarkan hasil rapat terbatas yang dipimpin Presiden Prabowo Subianto bersama sejumlah menteri, pemerintah memutuskan untuk melakukan penyesuaian kembali terhadap produksi batu bara.</p><p style=\"text-align: justify;\">Hal ini disampaikan oleh Menteri Koordinator Bidang Perekonomian Airlangga Hartarto usai mengikuti rapat terbatas di Jakarta, Kamis (19/3/2026). Ia menegaskan bahwa kebijakan ini juga berkaitan dengan upaya menjaga kondisi Anggaran Pendapatan dan Belanja Negara (APBN).</p><p style=\"text-align: justify;\">â€œPemerintah berupaya menjaga defisit tetap di bawah 3%, sesuai arahan dalam Sidang Kabinet Paripurna. Efisiensi dilakukan di berbagai kementerian dan lembaga agar target tersebut tercapai,â€ ujarnya.</p><p style=\"text-align: justify;\">Kebijakan Batu Bara</p><p style=\"text-align: justify;\">Untuk sektor batu bara, pemerintah berencana memangkas produksi tahun 2026 sekitar 600 juta ton. Angka ini lebih rendah dibandingkan realisasi produksi tahun 2025 yang mencapai sekitar 790 juta ton.</p><p style=\"text-align: justify;\">Menteri ESDM Bahlil Lahadalia menyatakan bahwa penurunan target produksi dilakukan sebagai strategi untuk memperbaiki harga batu bara di pasar global sekaligus menjaga ketersediaan cadangan di masa depan.</p><p style=\"text-align: justify;\">Menurutnya, Indonesia saat ini menyumbang sekitar 514 juta ton atau sekitar 43% dari total perdagangan batu bara dunia yang mencapai 1,3 miliar ton per tahun. Kondisi kelebihan pasokan inilah yang menyebabkan tekanan terhadap harga.</p><p style=\"text-align: justify;\">â€œKalau pasokan terlalu besar, keseimbangan supply dan demand terganggu dan harga bisa turun. Karena itu, produksi akan kita sesuaikan agar harga tetap terjaga dan cadangan bisa dimanfaatkan jangka panjang,â€ ujar Bahlil dalam keterangannya, Senin (19/1/2026).</p><p style=\"text-align: justify;\"><b>Penyesuaian Produksi Nikel</b></p><p style=\"text-align: justify;\">Selain batu bara, pemerintah juga melakukan penyesuaian terhadap produksi nikel. Target produksi nikel untuk tahun 2026 diperkirakan berada di kisaran 250 hingga 260 juta ton, lebih rendah dibandingkan RKAB 2025 yang mencapai 379 juta ton.</p><p style=\"text-align: justify;\">Tri Winarno menjelaskan bahwa penyesuaian ini dilakukan dengan mempertimbangkan kapasitas industri pengolahan (smelter) di dalam negeri.</p><p style=\"text-align: justify;\">â€œProduksi nikel akan disesuaikan dengan kebutuhan smelter, kemungkinan berada di kisaran 250â€“260 juta ton,â€ ujarnya saat ditemui di Kementerian ESDM, Jakarta, Rabu (14/1/2026).</p><p style=\"text-align: justify;\">Ia juga menambahkan bahwa kebijakan pengendalian produksi ini merupakan bagian dari strategi untuk mendukung kenaikan harga nikel di pasar global. Bahkan, setelah wacana ini muncul, harga nikel sempat menyentuh angka US$18.000 per ton.</p><p style=\"text-align: justify;\">Meski proses evaluasi RKAB masih berlangsung, pemerintah memastikan bahwa kegiatan operasional tetap berjalan normal. RKAB yang ada saat ini masih dapat digunakan hingga Maret, sehingga tidak mengganggu aktivitas produksi.</p><p style=\"text-align: justify;\">â€œJadi tidak perlu dikhawatirkan, semuanya tetap berjalan dengan baik,â€ tutupnya.</p><p style=\"text-align: justify;\"><br></p><p style=\"text-align: justify;\"></p>','XNN â€“ Xyron News NetworkJakarta â€” Kementerian Energi dan Sumber Daya Mineral (ESDM) telah memberikan persetujuan terhadap rencana produksi batu ba',1,'Batu bara, tambang, minerba, Esdm, rkap 2026',7,7,'published','https://www.xyronnews.com/uploads/posts/post_69c5baffb53a1.jpeg',125,'2026-03-26 16:21:45'),(10,'Krisis BBM Dampak Konflik Timur Tengah, Bahlil Ajak Masyarakat Hemat Energi.','krisis-bbm-dampak-konflik-timur-tengah-bahlil-ajak-masyarakat-hemat-energi','<p><font color=\"#636363\">Foto : bahlil lahadalia</font></p><p><strong data-start=\"11\" data-end=\"117\" style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"> XNN â€“ Xyron News Network</strong></p><p data-start=\"119\" data-end=\"665\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Jakarta - Menteri ESDM <font color=\"#ff0000\">Bahlil Lahadalia </font>mengajak seluruh masyarakat melakukan langkah penghematan dalam menghadapi krisis BBM buntut konflik di Timur Tengah. Bahlil mencontohkan pentingnya masyarakat menghemat gas saat memasak.<br data-start=\"358\" data-end=\"361\">\"Saya memohon, menyarankan agar ayok, kita harus memakai energi dengan bijak. Yang tidak perlu, saya sarankan jangan. Contoh, katakanlah, kalau masak pakai LPG, kalau masakannya udah masak, jangan kompornya boros,\" kata Bahlil di Colomadu dalam siaran YouTube Kementerian ESDM, dikutip Jumat (27/3/2026).</p><p><br></p>','Foto : bahlil lahadalia XNN â€“ Xyron News NetworkJakarta - Menteri ESDM Bahlil Lahadalia mengajak seluruh masyarakat melakukan langkah penghematan da',1,'BBM, krisis, bahlil',7,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69c61186ac136.jpeg',96,'2026-03-26 22:11:34'),(12,'Iran perbolehkan kapal Malaysia, Thailand, dan lima negara lain melintasi Selat Hormuz, bagaimana dengan kapal Indonesia?','iran-perbolehkan-kapal-malaysia-thailand-dan-lima-negara-lain-melintasi-selat-hormuz-bagaimana-dengan-kapal-indonesia','<p><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#636363\">Keterangan gambar, Para personel militer Iran melalui Selat Hormuz.</font></span><br></p><p>XXN - Xyron News Network | 27 Maret 2026</p><p>Sebuah kapal tanker Malaysia telah diberi izin oleh pemerintah Iran untuk melintasi Selat Hormuz, demikian diucapkan Perdana Menteri Anwar Ibrahim.</p><p>\"Kini kami sedang dalam proses melepaskan kapal tanker minyak Malaysia beserta para pekerjanya agar mereka dapat meneruskan perjalanan pulang,\" ujar Anwar dalam pidato khusus yang disiarkan secara langsung di stasiun televisi nasional, Kamis (26/03), sebagaimana dilansir kantor berita Bernama.</p><p>Dalam pidato itu, Anwar menyampaikan ucapan terima kasih kepada Presiden Iran, Masoud Pezeshkian, atas izin yang diberikan kepada kapal tanker minyak Malaysia untuk melintasi Selat Hormuz.</p><p>Anwar menambahkan, blokade di Selat Hormuz serta gangguan terhadap pasokan minyak dan gas global berpotensi memengaruhi Malaysia.</p><p>Namun, menurutnya, Malaysia berada dalam posisi yang relatif lebih baik berkat kemampuan perusahaan energi nasional Petronas dalam mengelola pasokan dan memastikan stabilitas energi.</p><p>Selain kapal tanker Malaysia, kapal tanker minyak Thailand berhasil melintasi Selat Hormuz dengan aman.</p><p>Hal itu tercapai setelah pemerintah Thailand dan Iran melakukan koordinasi diplomatik, menurut Menteri Luar Negeri Thailand, Sihasak Phuangketkeow.</p><p>Sihasak mengatakan kapal tanker milik Bangchak Corporation itu melintasi Selat Hormuz pada Senin (23/03) menyusul pembicaraan antara dirinya dengan Duta Besar Iran untuk Thailand, Nasereddin Heydari.</p>','Keterangan gambar, Para personel militer Iran melalui Selat Hormuz.XXN - Xyron News Network | 27 Maret 2026Sebuah kapal tanker Malaysia telah diberi i',9,'Kapal tangker, Malaysia, Indonesia ',7,7,'published','https://xyronnews.com/uploads/posts/post_69c61eb5ceb27.webp',100,'2026-03-26 23:07:50'),(13,'Purbaya Ungkap Efisiensi Anggaran Bakal Dilakukan 3 Tahap','purbaya-ungkap-efisiensi-anggaran-bakal-dilakukan-3-tahap','<p>Foto : Purbaya Yudhi Sadewa (CNN Indonesia)</p><p style=\"text-align: justify;\">Zahwa Madjid, XNN â€“ Xyron News Network</p><p style=\"text-align: justify;\">26 March 2026 13:25</p><p style=\"text-align: justify;\">Jakarta, XNN â€“ Xyron News Network - Pemerintah akan menjalankan skema efisiensi anggaran pada tahun ini dalam tiga tahap. Efisiensi ini dilakukan sebagai strategi antisipasi dampak rambatan tekanan ekonomi akibat perang di Timur Tengah antara Iran dengan Amerika Serikat dan Israel.</p><p style=\"text-align: justify;\">Skema efisiensi ini diungkapkan langsung oleh Menteri Keuangan Purbaya Yudhi Sadewa saat halal bihalal dengan pewarta di Kantor Pusat Kementerian Keuangan, Jakarta.</p><p style=\"text-align: justify;\">\"Kan tahap satu, tahap dua, tahap tiga kita jalankan nanti,\" kata Purbaya.</p><p style=\"text-align: justify;\">Purbaya mengatakan, nilai efisiensi anggaran yang telah dirancang sesuai dengan pernyataan Menteri Sekretaris Negara Prasetyo Hadi saat mendampingi Presiden Prabowo Subianto dalam program Presiden Prabowo Menjawab di Hambalang. Efisiensi itu senilai Rp 81 triliun.</p><p style=\"text-align: justify;\">Dengan strategi efisiensi ini, Purbaya memastikan pemerintah dapat menjaga stabilitas fiskal dengan defisit di kisaran bawah batas aman Undang-Undang Keuangan Negara sebesar 3% dari produk domestik bruto (PDB). Adapun target defisit APBN 2026 sebesar 2,68% PDB.</p><p style=\"text-align: justify;\">\"Yang jelas anggarannya sudah clear. Jadi APBN saya bisa dikendalikan, enggak tembus 3%,\" tegas Purbaya.</p><p style=\"text-align: justify;\">Sebagai informasi, Menteri Sekretaris Negara Prasetyo Hadi mengungkapkan, total efisiensi atau penghematan anggaran yang telah dirancang untuk APBN 2026 senilai Rp 81 triliun. Ditambah dengan nilai relokasi anggaran yang sudah disisir sebesar Rp 800 triliun.</p><p style=\"text-align: justify;\">\"Sudah dapat Rp 80 triliun. Di luar yang sudah kita realokasi. Total kurang lebih US$ 70 miliar. Yang sudah direalokasi kurang lebih mencapai Rp 800 triliun, di luar itu bapak perintahkan efisiensi kembali sudah dapat sekitar Rp 81 triliun,\" ungkap Prasetyo.</p>','Foto : Purbaya Yudhi Sadewa (CNN Indonesia)Zahwa Madjid, XNN â€“ Xyron News Network26 March 2026 13:25Jakarta, XNN â€“ Xyron News Network - Pemerintah',1,'',7,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69c81e086bfa6.jpeg',106,'2026-03-28 11:29:28'),(14,'Demo Anti Trump â€˜No Kingsâ€™ di Los Angeles Memanas, Polisi Gunakan Gas Air Mata','demo-anti-trump-no-kings-di-los-angeles-memanas-polisi-gunakan-gas-air-mata','<h6><i>Foto : polisi lepaskan gas air mata ke pendemo di Los Angeles.</i></h6><p style=\"text-align: justify;\"><b>XNN â€“ Xyron News Network</b></p><p style=\"text-align: justify;\">Minggu, 29 Maret 2026</p><p style=\"text-align: justify;\"><b>Los Angeles</b> â€“ Aksi demonstrasi bertajuk â€œNo Kingsâ€ yang digelar ribuan massa di pusat kota Los Angeles, Amerika Serikat, berujung ricuh setelah aparat kepolisian mengeluarkan perintah pembubaran. Polisi bahkan dilaporkan menggunakan gas air mata untuk mengendalikan situasi yang memanas.</p><p style=\"text-align: justify;\">Mengutip laporan NBC News dan Associated Press pada Minggu (29/3/2026), Departemen Kepolisian Los Angeles menetapkan status Siaga Taktis sejak Sabtu malam (28/3) waktu setempat. Aparat menutup sejumlah ruas jalan utama serta melakukan penangkapan terhadap demonstran yang menolak membubarkan diri.</p><p style=\"text-align: justify;\">Aksi ini awalnya berlangsung damai melalui pawai besar di pusat kota. Namun, ketegangan meningkat setelah massa bergerak menuju area sekitar Pusat Penahanan Federal, yang sebelumnya memang menjadi titik rawan bentrokan sejak kebijakan penindakan imigrasi di era pemerintahan Donald Trump kembali diperketat tahun lalu.</p>','Foto : polisi lepaskan gas air mata ke pendemo di Los Angeles.XNN â€“ Xyron News NetworkMinggu, 29 Maret 2026Los Angeles â€“ Aksi demonstrasi bertajuk',9,'Pendemo, Los Angeles, gas air mata',7,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69c93d98290c2.jpeg',63,'2026-03-29 07:56:23'),(15,'Kecelakaan Maut di Poros Trans Sulawesi Kolaka-Bombana, Pengendara Motor Tewas di Tempat','kejadian-kecelakaan-lalu-lintas-korban-meninggal-dunia-md','<p style=\"text-align: justify;\"><span style=\"text-align: start;\"><i>Kondisi kendaraan pascakecelakaan lalu lintas di Jalan Poros Trans Sulawesi Kolaka-Bombana, Desa Tambea, Kecamatan Pomalaa, Jumat (27/3/2026). (Foto: Dok. Istimewa)</i></span></p><p data-path-to-node=\"19\" style=\"text-align: justify;\"><b data-path-to-node=\"19\" data-index-in-node=\"0\">KOLAKA, XNN</b> â€“ Kecelakaan lalu lintas tragis terjadi di Jalan Poros Trans Sulawesi rute Kolaka-Bombana, tepatnya di wilayah Desa Tambea, Kecamatan Pomalaa, Kabupaten Kolaka, pada Jumat (27/3/2026) petang. Insiden nahas ini merenggut nyawa seorang pengendara sepeda motor.</p><p data-path-to-node=\"20\" style=\"text-align: justify;\">Peristiwa yang terjadi sekitar pukul 17.30 WITA tersebut melibatkan sebuah mobil Honda WR-V berwarna hitam dengan nomor polisi DT 1325 PB dan sebuah sepeda motor Yamaha Fino berwarna hitam bernomor polisi DD 2033 DP.</p><p data-path-to-node=\"21\" style=\"text-align: justify;\">Berdasarkan keterangan pihak kepolisian, kecelakaan bermula saat mobil Honda WR-V yang dikemudikan oleh pria berinisial YEF (35) melaju dari arah utara menuju selatan (Pomalaa-Tanggetada). Saat memasuki kawasan Desa Tambea yang memiliki kontur jalan menurun dan berbelok, dari arah berlawanan (selatan ke utara) melaju sepeda motor Yamaha Fino yang dikendarai oleh pemuda berinisial MA (24).</p><p data-path-to-node=\"22\" style=\"text-align: justify;\">\"Pengendara motor (MA) diduga kehilangan keseimbangan atau oleng ketika mencoba melambung (menyalip) mobil di depannya. Korban kemudian terjatuh dan terseret ke arah kanan, hingga akhirnya berbenturan keras dengan ban kanan depan mobil Honda WR-V,\" jelas laporan resmi hasil olah Tempat Kejadian Perkara (TKP).</p><p data-path-to-node=\"23\" style=\"text-align: justify;\">Akibat benturan keras tersebut, MA yang merupakan warga Kelurahan Lamokato, Kecamatan Kolaka itu mengalami luka parah. Korban menderita luka terbuka di bagian kepala, patah tulang hidung, patah tangan kiri, hingga patah rahang. Korban dinyatakan meninggal dunia di lokasi kejadian.</p><p data-path-to-node=\"24\" style=\"text-align: justify;\">Fakta menyedihkan terungkap dari hasil olah TKP kepolisian. Meskipun korban menggunakan helm saat berkendara, sayangnya tali pengaman helm tersebut tidak dikancing, sehingga diduga helm terlepas saat benturan terjadi.</p><p data-path-to-node=\"25\" style=\"text-align: justify;\">Sementara itu, pengemudi mobil Honda WR-V beserta seorang penumpang perempuan berinisial EL (49), yang keduanya merupakan warga Desa Sopura, dilaporkan tidak mengalami luka berarti.</p><p data-path-to-node=\"26\" style=\"text-align: justify; \">Saat ini, pihak Satlantas telah mengevakuasi korban, melakukan olah TKP, dan mengamankan kedua kendaraan yang terlibat kecelakaan ke Mako Satlantas sebagai barang bukti. Adapun total kerugian material akibat kerusakan kendaraan dalam insiden ini ditaksir mencapai Rp10 juta.</p>','Foto : kecelakaan lalu lintas&nbsp;XXN - Xyron New Network&nbsp;â€Žâ€ŽKecelakaan Lalu Lintas yang terjadi pada hari Jum\'at tanggal 27 Maret 2026 puku',8,'Kecelakaan Maut, Kecelakaan Kolaka, Trans Sulawesi Kolaka Bombana, Polsek Pomalaa, Satlantas Polres Kolaka, Berita Duka Kolaka, XNN, Info Lalulintas',7,7,'published','https://www.xyronnews.com/uploads/posts/post_69c9c154582f6.jpeg',173,'2026-03-31 07:51:35'),(16,'Mahasiswa Bombana Desak Pemda Segera Renovasi Asrama di Makassar','mahasiswa-bombana-desak-pemda-segera-renovasi-asrama-di-makassar','<h6><span style=\"-webkit-text-size-adjust: 100%;\"><i>Foto : ikatan mahasiswa pelajar Indonesia Bombana ketemu pemerintah Bombana</i></span></h6><p style=\"text-align: justify;\"><b style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Makassar, XXN </b><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">â€” Mahasiswa asal Kabupaten Bombana mendesak Pemerintah Daerah agar segera merealisasikan renovasi Asrama Mahasiswa Bombana di Makassar yang dinilai sudah sangat memprihatinkan dan membutuhkan perhatian serius.</span><br></p><p style=\"text-align: justify;\">Desakan tersebut disampaikan oleh Badan Pengurus Harian Ikatan Mahasiswa Pelajar Indonesia Bombana (IMPIB) Makassar melalui permohonan Rapat Dengar Pendapat (RDP). Namun, hingga hampir sepekan sejak diajukan, belum ada kepastian jadwal dari pihak terkait.</p><p style=\"text-align: justify;\">Sebagai langkah lanjutan, perwakilan mahasiswa mendatangi pemerintah daerah dan bertemu langsung dengan Sekretaris Daerah serta Bupati Bombana untuk meminta kejelasan terkait realisasi perbaikan asrama tersebut.</p><p style=\"text-align: justify;\">Dalam pertemuan itu, pemerintah daerah menyampaikan bahwa saat ini tengah mencari alternatif anggaran untuk dua kebutuhan prioritas, yakni perbaikan akses jalan dan renovasi asrama mahasiswa.</p><p style=\"text-align: justify;\">Wakil Ketua IMPIB Makassar, Tajering, secara tegas mempertanyakan kepastian tersebut.</p><p style=\"text-align: justify;\">â€œPak, kapan asrama mahasiswa Bombana di Makassar bisa dijadikan prioritas perbaikan?â€ ujarnya.</p><p style=\"text-align: justify;\">Menanggapi hal itu, Bupati Bombana, Burhanuddin, memastikan bahwa perbaikan akan diupayakan pada tahun anggaran berjalan.</p><p style=\"text-align: justify;\">â€œInsyaallah tahun ini kami pastikan ada perbaikan jalan untuk asrama di Makassar. Kami juga akan menurunkan tim konsultan untuk meninjau kondisi bangunan,â€ ungkapnya di Rumah Jabatan Bupati, Selasa (31/3/2026).</p><p style=\"text-align: justify;\">Pemerintah daerah menilai bahwa penyediaan fasilitas asrama merupakan bagian penting dalam mendukung akses pendidikan bagi mahasiswa Bombana yang sedang menempuh pendidikan di perantauan.</p>','Foto : ikatan mahasiswa pelajar Indonesia Bombana ketemu pemerintah BombanaMakassar, XXN â€” Mahasiswa asal Kabupaten Bombana mendesak Pemerintah Daer',1,'Mahasiswa Makassar, Bombana, asrama, ',7,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69cc04bfa554e.jpeg',141,'2026-03-31 10:30:39'),(17,'Ratusan Sopir Truk Demo di Kantor Bupati Kolaka, Tuntut Hak Tenaga Kerja Lokal','ratusan-sopir-truk-demo-di-kantor-bupati-kolaka-tuntut-hak-tenaga-kerja-lokal','<p style=\"text-align: justify;\"><font color=\"#636363\">Foto : aksi unjuk rasa ratusan sopir dump truck&nbsp;</font></p><p><b>XYRON NEWS NETWORK â€“</b> Ratusan sopir dump truck yang tergabung dalam Forum Pemerhati Investasi dan Pemberdayaan Tenaga Kerja Lokal menggelar aksi unjuk rasa di depan Kantor Bupati Kolaka, Kamis (2/4/2026).</p><p>Aksi ini menjadi bentuk kekecewaan terhadap minimnya keterlibatan tenaga kerja lokal dalam proyek-proyek strategis nasional (PSN) yang tengah berlangsung di daerah tersebut.</p><p>Koordinator aksi, Hendra, menegaskan bahwa kehadiran investasi besar di Kolaka belum sepenuhnya memberikan dampak nyata bagi masyarakat lokal, khususnya para sopir dump truck.</p><p>â€œKami hanya ingin diberdayakan di daerah sendiri. Jangan sampai kami hanya jadi penonton,â€ tegasnya di hadapan massa aksi.</p><p>Menurutnya, sebagai daerah dengan potensi sumber daya alam melimpah, Kolaka seharusnya mampu menjamin distribusi manfaat ekonomi yang adil, termasuk dalam pembukaan lapangan kerja bagi masyarakat setempat.</p><p>Namun realitas di lapangan menunjukkan bahwa banyak sopir lokal belum dilibatkan dalam distribusi material proyek, yang justru didominasi oleh tenaga dari luar daerah.</p><p>Situasi ini memicu pertanyaan publik terhadap peran pemerintah daerah dalam mengawasi dan memastikan perusahaan yang beroperasi di Kolaka memprioritaskan tenaga kerja lokal.</p><p>Massa aksi juga mendesak perusahaan-perusahaan, khususnya yang terlibat dalam sektor pertambangan dan proyek strategis nasional, agar memberikan ruang yang lebih besar bagi sopir lokal.</p><p>Menanggapi hal tersebut, Staf Ahli Bupati Kolaka, LM Hasimin, turun langsung menemui massa dan berjanji akan menindaklanjuti aspirasi tersebut.</p><p>â€œPemerintah daerah akan mengakomodasi tuntutan ini dan segera mengundang pihak perusahaan untuk mencari solusi bersama,â€ ujarnya.</p><p>Pemerintah berharap dialog antara masyarakat dan perusahaan dapat menghasilkan kesepakatan yang adil tanpa menghambat jalannya pembangunan.</p><p>Aksi ini menjadi pengingat bahwa investasi tidak hanya soal pembangunan fisik, tetapi juga tentang keadilan ekonomi dan keberpihakan terhadap masyarakat lokal.</p>','Foto : aksi unjuk rasa ratusan sopir dump truck&nbsp;XYRON NEWS NETWORK â€“ Ratusan sopir dump truck yang tergabung dalam Forum Pemerhati Investasi da',8,'Kolaka, sopir Dt, aksi ujukrasa',7,7,'published','https://www.xyronnews.com/uploads/posts/post_69cfe476e6ad1.jpeg',326,'2026-04-03 09:03:47'),(18,'Presiden Prabowo Subianto Pimpin Pelepasan 3 Prajurit TNI Gugur dalam Misi PBB di Lebanon','presiden-prabowo-subianto-pimpin-pelepasan-3-prajurit-tni-gugur-dalam-misi-pbb-di-lebanon','<p style=\"text-align: left;\"><span style=\"caret-color: rgb(85, 85, 85); color: rgb(85, 85, 85); font-family: Heebo; font-size: 11px; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; text-align: var(--bs-body-text-align);\">UPACARA PENGHORMATAN- Presiden Republik Indonesia Prabowo Subianto, memimpin langsung prosesi penjemputan dan pelepasan jenazah tiga prajurit TNI yang gugur saat menjalankan misi perdamaian PBB (UNIFIL) di Lebanon. Upacara penghormatan terakhir yang berlangsung penuh haru ini digelar di Bandara Soekarno-Hatta (Soetta), Tangerang, pada Sabtu (4/4/2026) malam.&nbsp;</span></p><p style=\"text-align: left;\"><span style=\"caret-color: rgb(85, 85, 85); color: rgb(85, 85, 85); font-family: Heebo; font-size: 11px; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; text-align: var(--bs-body-text-align);\"><b>Xyron News Network</b></span></p><p style=\"text-align: left;\"><span style=\"text-align: var(--bs-body-text-align); font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><b style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3);\">TANGERANG, 4 April </b><b><span style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3);\">2026</span><span style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3);\">&nbsp;</span></b></span><b style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><span style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\">&nbsp;</span><span style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\">–</span></b><span style=\"text-align: var(--bs-body-text-align); font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: 100%;\">&nbsp;&nbsp;</span><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Presiden Republik Indonesia,&nbsp;</span><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\" style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Prabowo Subianto</span><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">, memimpin langsung prosesi penjemputan dan pelepasan jenazah tiga prajurit Tentara Nasional Indonesia (TNI) yang gugur saat menjalankan misi perdamaian dunia di Lebanon.</span></p><p data-start=\"528\" data-end=\"780\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Upacara penghormatan terakhir tersebut berlangsung secara khidmat di Bandara Internasional&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">Soekarno-Hatta International Airport</span>, Sabtu malam (4/4/2026), dan dihadiri oleh sejumlah pejabat tinggi negara serta pimpinan institusi pertahanan dan keamanan.</p><p data-start=\"782\" data-end=\"997\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Ketiga prajurit tersebut gugur saat menjalankan tugas dalam misi&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">United Nations Interim Force in Lebanon</span>&nbsp;(UNIFIL), yang merupakan bagian dari kontribusi Indonesia dalam menjaga stabilitas dan perdamaian internasional.</p><h3 data-start=\"999\" data-end=\"1026\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; color: rgb(0, 0, 0);\"><span role=\"text\"><strong data-start=\"1003\" data-end=\"1026\">Penghormatan Negara</strong></span></h3><p data-start=\"1028\" data-end=\"1316\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Setibanya di lokasi, Presiden disambut oleh Panglima TNI Jenderal&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">Agus Subiyanto</span>, Kapolri Jenderal&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">Listyo Sigit Prabowo</span>, serta Presiden ke-6 Republik Indonesia&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">Susilo Bambang Yudhoyono</span>&nbsp;yang turut hadir memberikan penghormatan terakhir.</p><p data-start=\"1318\" data-end=\"1572\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Prosesi berlangsung dengan penuh khidmat saat peti jenazah yang diselimuti bendera Merah Putih diturunkan dari pesawat. Suasana duka menyelimuti area bandara, terlebih ketika keluarga almarhum hadir dan menyaksikan langsung prosesi penghormatan tersebut.</p><p data-start=\"1574\" data-end=\"1846\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Presiden Prabowo Subianto juga menyempatkan diri untuk menyampaikan belasungkawa secara langsung kepada keluarga yang ditinggalkan. Dalam kesempatan tersebut, Presiden menegaskan bahwa pengorbanan para prajurit merupakan bentuk dedikasi tertinggi kepada bangsa dan negara.</p><h3 data-start=\"1848\" data-end=\"1881\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; color: rgb(0, 0, 0);\"><span role=\"text\"><strong data-start=\"1852\" data-end=\"1881\">Kenaikan Pangkat Anumerta</strong></span></h3><p data-start=\"1883\" data-end=\"2021\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Sebagai bentuk penghargaan atas jasa dan pengabdian, ketiga prajurit yang gugur dianugerahi kenaikan pangkat luar biasa (anumerta), yaitu:</p><ul data-start=\"2023\" data-end=\"2149\" style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><li data-start=\"2023\" data-end=\"2069\" style=\"text-align: left;\">Mayor Inf (Anumerta) Zulmi Aditya Iskandar</li><li data-start=\"2070\" data-end=\"2110\" style=\"text-align: left;\">Serka (Anumerta) Muhammad Nur Ichwan</li><li data-start=\"2111\" data-end=\"2149\" style=\"text-align: left;\">Kopda (Anumerta) Farizal Rhomadhon</li></ul><p data-start=\"2151\" data-end=\"2313\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Ketiganya selanjutnya diberangkatkan ke kampung halaman masing-masing untuk disemayamkan dan dimakamkan secara militer, sebagai penghormatan terakhir dari negara.</p><h3 data-start=\"2315\" data-end=\"2354\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; color: rgb(0, 0, 0);\"><span role=\"text\"><strong data-start=\"2319\" data-end=\"2354\">Dedikasi untuk Perdamaian Dunia</strong></span></h3><p data-start=\"2356\" data-end=\"2568\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Kepergian ketiga prajurit tersebut menjadi duka mendalam bagi bangsa Indonesia. Namun, pengabdian mereka dalam misi perdamaian internasional menjadi bukti nyata komitmen Indonesia dalam menjaga stabilitas global.</p><p data-start=\"2570\" data-end=\"2728\" style=\"text-align: left; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Semangat dan dedikasi yang ditunjukkan diharapkan dapat menjadi teladan bagi seluruh prajurit TNI serta generasi muda dalam mengabdi kepada bangsa dan negara.</p>','UPACARA PENGHORMATAN- Presiden Republik Indonesia Prabowo Subianto, memimpin langsung prosesi penjemputan dan pelepasan jenazah tiga prajurit TNI yang',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69d14dd3e04e2.jpeg',272,'2026-04-05 00:43:47'),(19,'Geger Benda Bercahaya Mirip Meteor Melesat di Langit Lampung, Warga Sempat Panik dan Teriakkan Takbir','geger-benda-bercahaya-mirip-meteor-melesat-di-langit-lampung-warga-sempat-panik-dan-teriakkan-takbir','<p style=\"text-align: justify; \"><i>Tangkapan layar dari rekaman video amatir warga yang memperlihatkan benda langit bercahaya diduga meteor melintas di langit malam. (Foto: Dok. Warga/XNN)</i></p><p style=\"text-align: justify; \"><b>LAMPUNG, XNN</b> – Warga di sejumlah kawasan di Provinsi Lampung digemparkan oleh fenomena astronomi yang tak terduga. Sebuah objek bercahaya misterius terpantau membelah langit malam pada Sabtu (4/4/2026), memicu kehebohan sekaligus tanda tanya besar di tengah masyarakat.</p><p style=\"text-align: justify; \">Berdasarkan rekaman video amatir yang beredar luas dan diterima redaksi, benda tersebut melesat dengan kecepatan tinggi, memancarkan cahaya terang kemerahan yang disertai jejak ekor api yang panjang sebelum akhirnya memudar. Penampakan yang hanya berlangsung dalam hitungan detik tersebut tak ayal membuat warga yang sedang berada di luar ruangan terkejut.</p><p style=\"text-align: justify; \">Kepanikan dan ketakjuban terekam jelas dalam video amatir tersebut. Terdengar sejumlah warga meneriakkan takbir saat cahaya itu melintas, sementara yang lain terdengar berspekulasi dengan panik menyebutnya sebagai \"rudal\" hingga \"meteor\".</p><p style=\"text-align: justify; \">Rudi (34), salah seorang saksi mata yang berdomisili di Bandar Lampung, mengungkapkan pengalamannya saat melihat langsung peristiwa itu. “Pendaran cahayanya sangat mencolok dan pergerakannya luar biasa cepat. Pikiran pertama saya sempat mengira itu pesawat yang jatuh, tapi bentuk fisiknya sangat identik dengan meteor karena ada ekornya,” paparnya.</p><p style=\"text-align: justify; \">Sensasi kepanikan serupa turut dirasakan oleh warga Lampung Selatan, Siti Aminah (29). Kehadiran kilatan misterius yang datang secara mendadak itu sontak membuat keluarganya terkejut. “Waktu kejadian saya sedang bersantai di halaman. Tiba-tiba langit jadi terang sesaat karena kilatan itu. Anak-anak saya bahkan sampai menjerit kaget karena ini pengalaman pertama kami melihat yang seperti ini,” ceritanya.</p><p style=\"text-align: justify; \">Sementara itu di wilayah Pesawaran, fenomena langit ini berhasil memancing keingintahuan massa. Dedi Kurniawan (41) menyebutkan bahwa meskipun durasinya sangat singkat, wujud cahaya tersebut terlihat amat jelas. “Terang sekali dan langsung lenyap. Gara-gara itu, banyak tetangga yang langsung keluar rumah untuk mencari tahu,” ujarnya.</p><p style=\"text-align: justify; \">Hingga berita ini diturunkan, belum ada pernyataan resmi dari instansi terkait seperti Badan Meteorologi, Klimatologi, dan Geofisika (BMKG) atau Observatorium antariksa mengenai identitas pasti objek tersebut. Namun, kuat dugaan bahwa benda langit itu merupakan pecahan meteor atau puing sampah antariksa yang terbakar habis saat bergesekan dengan lapisan atmosfer Bumi.</p>','Tangkapan layar dari rekaman video amatir warga yang memperlihatkan benda langit bercahaya diduga meteor melintas di langit malam. (Foto: Dok. Warga/X',10,'Meteor Lampung, Fenomena Langit, Benda Bercahaya, Berita Viral, Astronomi, Bandar Lampung, Lampung Selatan, BMKG, XNN',9,9,'published','https://www.xyronnews.com/uploads/posts/post_69d15ab06e02b.jpg',78,'2026-04-05 01:44:38'),(21,'Pencabutan IUP dan IUPK oleh Menteri Dipersoalkan di Mahkamah Konstitusi','pencabutan-iup-dan-iupk-oleh-menteri-dipersoalkan-di-mahkamah-konstitusi','<p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent;\"><font color=\"#636363\">Poto : Mahkama konstitusi&nbsp;</font></span></p><p style=\"text-align: justify;\"><b style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">JAKARTA, XYRON NEWS NETWORK –</b><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"> Permohonan pengujian materiil terhadap Pasal 119 huruf c Undang-Undang Nomor 3 Tahun 2020 tentang Pertambangan Mineral dan Batubara (UU Minerba) kembali diajukan ke Mahkamah Konstitusi (MK). Permohonan tersebut teregistrasi dengan Nomor 121/PUU-XXIV/2026.</span><br></p><p style=\"text-align: justify;\">Permohonan ini diajukan oleh Octolin H. Hutagalung dan Arif Suherman yang mempersoalkan ketentuan pencabutan Izin Usaha Pertambangan (IUP) dan Izin Usaha Pertambangan Khusus (IUPK) oleh Menteri.</p><p style=\"text-align: justify;\">Dalam sidang yang digelar pada Kamis (9/4/2026), kuasa hukum Pemohon, Janses Sihaloho, menyampaikan bahwa Pasal 119 huruf c UU Minerba dinilai bertentangan dengan Pasal 28D ayat (1) UUD 1945. Menurutnya, ketentuan tersebut tidak memberikan kepastian, jaminan, dan perlindungan hukum, khususnya bagi debitur pemegang IUP atau IUPK yang dinyatakan pailit namun masih berstatus going concern.</p><p style=\"text-align: justify;\">Pemohon menilai adanya ketidaksinkronan antara UU Minerba dengan Undang-Undang Nomor 37 Tahun 2004 tentang Kepailitan dan PKPU, khususnya Pasal 179 hingga Pasal 182 yang mengatur keberlanjutan usaha debitur pailit.</p><p style=\"text-align: justify;\">Janses menjelaskan, dalam hukum kepailitan, debitur yang telah dinyatakan pailit memang kehilangan hak untuk menguasai dan mengurus harta kekayaannya sejak putusan diucapkan. Kewenangan tersebut beralih kepada kurator sebagaimana diatur dalam Pasal 24 ayat (1) UU Kepailitan dan PKPU.</p><p style=\"text-align: justify;\">Lebih lanjut, ia menambahkan bahwa kurator memiliki opsi untuk mengajukan izin kepada hakim pengawas guna melanjutkan kegiatan usaha debitur pailit. Skema ini dikenal sebagai going concern, yang dinilai mampu memberikan kepastian hukum sekaligus meningkatkan peluang pelunasan utang kepada para kreditur.</p><p style=\"text-align: justify;\">Pemohon berpendapat, keberlanjutan usaha debitur pailit justru dapat memberikan manfaat ekonomi, termasuk bagi negara melalui penerimaan sektor pertambangan serta pemenuhan kewajiban pajak dan utang. Sebaliknya, pencabutan IUP atau IUPK dalam kondisi tersebut dinilai berpotensi merugikan banyak pihak, termasuk negara.</p><p style=\"text-align: justify;\">“Upaya kurator untuk melanjutkan usaha debitur pailit merupakan langkah penting dalam menjamin pelunasan utang kepada kreditur,” ujar Janses dalam persidangan.</p><p style=\"text-align: justify;\">Dalam petitumnya, Pemohon meminta Mahkamah Konstitusi menyatakan Pasal 119 huruf c UU Minerba bertentangan dengan UUD 1945 dan tidak memiliki kekuatan hukum mengikat, sepanjang tidak dimaknai bahwa pencabutan izin dikecualikan bagi debitur pailit yang oleh Pengadilan Niaga dinyatakan dapat melanjutkan usaha (going concern).</p><p style=\"text-align: justify;\">Selain itu, Pemohon juga meminta agar norma tersebut dimaknai ulang sehingga Menteri tidak dapat mencabut IUP atau IUPK selama terdapat penetapan pengadilan terkait keberlanjutan usaha debitur pailit. Pemohon menekankan pentingnya asas res judicata pro veritate habetur, yakni putusan pengadilan harus dianggap benar dan wajib dilaksanakan, demi menjamin kepastian hukum.</p><p style=\"text-align: justify;\">Menanggapi permohonan tersebut, Hakim Konstitusi Ridwan Mansyur menilai bahwa Pemohon belum secara jelas menguraikan hubungan kausal antara norma yang diuji dengan kerugian hak konstitusional yang dialami.</p><p style=\"text-align: justify;\">“Kerugian hak konstitusional yang didalilkan belum dijelaskan secara konkret dengan berlakunya pasal yang diuji,” tegas Ridwan.</p><p style=\"text-align: justify;\">Majelis Hakim Konstitusi memberikan waktu selama 14 hari kepada Pemohon untuk memperbaiki permohonan. Perbaikan tersebut harus disampaikan paling lambat pada Rabu, 22 April 2026.</p>','Poto : Mahkama konstitusi&nbsp;JAKARTA, XYRON NEWS NETWORK – Permohonan pengujian materiil terhadap Pasal 119 huruf c Undang-Undang Nomor 3 Tahun 20',1,'XyronNewsNetwork, BeritaHariIni, BreakingNews, NewsUpdate, ',7,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69d8674a74f66.jpeg',148,'2026-04-10 09:58:18'),(22,'Komisi VIII DPR Soroti Wacana “War Tiket” Haji, Dinilai Berpotensi Picu Kecemburuan Sosial','komisi-viii-dpr-soroti-wacana-war-tiket-haji-dinilai-berpotensi-picu-kecemburuan-sosial','<p><font color=\"#636363\"><span data-start=\"194\" data-end=\"216\" style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\">Foto :&nbsp;</span><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Ka’bah + jamaah tawaf&nbsp;</span></font></p><p style=\"text-align: justify;\"><strong data-start=\"194\" data-end=\"216\" style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Xyron News Network</strong><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">&nbsp;– Wacana penerapan sistem “war tiket” dalam pemberangkatan ibadah haji menuai sorotan dari DPR RI. Ketua Komisi VIII,&nbsp;</span><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\" style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Marwan Dasopang</span><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">, menilai skema tersebut berpotensi menimbulkan kecemburuan sosial di tengah masyarakat.</span></p><p data-start=\"462\" data-end=\"701\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Menurut Marwan, mekanisme penyelenggaraan haji saat ini telah diatur secara jelas dalam&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">Undang-Undang Nomor 14 Tahun 2025 tentang Penyelenggaraan Haji</span>, yang menegaskan bahwa sistem yang digunakan adalah pendaftaran dengan antrean, bukan berburu tiket secara bebas.</p><p data-start=\"703\" data-end=\"985\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Ia mengingatkan bahwa sistem daftar tunggu telah diberlakukan sejak 2008 sebagai respons atas tingginya minat masyarakat Indonesia untuk menunaikan ibadah haji. Dengan sistem tersebut, pemerintah berupaya menjaga prinsip keadilan dan pemerataan kesempatan bagi seluruh calon jemaah.</p><p data-start=\"987\" data-end=\"1187\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">“Kalau diterapkan war tiket, yang berpeluang besar justru kalangan mampu. Ini berisiko menciptakan ketimpangan dan kecemburuan di masyarakat,” ujarnya di Kompleks Parlemen, Senayan, Jumat (10/4/2026).</p><p data-start=\"1189\" data-end=\"1499\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Marwan juga menyoroti bahwa kebijakan tersebut bisa bertentangan dengan aturan yang telah ada, termasuk pembatasan bagi jemaah yang sudah berhaji agar menunggu selama 10 tahun sebelum dapat mendaftar kembali. Kebijakan itu, kata dia, dibuat untuk memberi kesempatan kepada masyarakat yang belum pernah berhaji.</p><p data-start=\"1501\" data-end=\"1765\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Selain aspek keadilan, ia menekankan pentingnya landasan hukum dalam setiap kebijakan pemerintah. Menurutnya, penerapan sistem “war tiket” tidak dapat dilakukan tanpa revisi regulasi yang berlaku, karena berpotensi bertabrakan dengan ketentuan dalam undang-undang.</p><p data-start=\"1767\" data-end=\"2131\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Saat ini, kuota haji Indonesia berkisar sekitar 221 ribu jemaah per tahun, dengan komposisi sekitar 92 persen untuk haji reguler dan 8 persen untuk haji khusus. Dengan jumlah antrean yang mencapai jutaan orang, Marwan menilai solusi utama bukan pada perubahan sistem menjadi “war tiket”, melainkan pada upaya menambah kuota dan memperkuat kerja sama internasional.</p><p data-start=\"2133\" data-end=\"2332\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">“Fokus pemerintah seharusnya mengurai antrean yang sudah mencapai jutaan jemaah. Caranya dengan negosiasi penambahan kuota serta kerja sama dengan negara lain yang kuotanya tidak terpakai,” jelasnya.</p><p data-start=\"2334\" data-end=\"2659\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Sementara itu, wacana “war tiket” sendiri tengah dikaji oleh Kementerian Haji dan Umrah RI sebagai terobosan untuk mengatasi panjangnya antrean haji. Menteri Haji dan Umrah,&nbsp;<span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\">Mochamad Irfan Yusuf</span>, menyebut ide tersebut muncul sebagai upaya mencari solusi agar calon jemaah tidak perlu menunggu bertahun-tahun.</p><p data-start=\"2661\" data-end=\"2911\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Dalam skema tersebut, pemerintah akan membuka pendaftaran pada waktu tertentu setelah biaya haji diumumkan. Calon jemaah yang siap secara finansial dan administratif dapat langsung berangkat di tahun yang sama tanpa harus masuk daftar tunggu panjang.</p><p data-start=\"2913\" data-end=\"3223\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Meski demikian, DPR mengingatkan agar setiap kebijakan yang diambil tetap mempertimbangkan aspek keadilan, sosial, dan legalitas. Kebijakan yang tidak matang dikhawatirkan justru menimbulkan ketimpangan akses ibadah, bahkan berpotensi membuat sebagian masyarakat merasa tidak memiliki kesempatan untuk berhaji.</p>','Foto :&nbsp;Ka’bah + jamaah tawaf&nbsp;Xyron News Network&nbsp;– Wacana penerapan sistem “war tiket” dalam pemberangkatan ibadah haji menuai s',1,'Biaya haji, DPR, war tiket',7,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69d8abffe77bf.jpeg',101,'2026-04-10 14:51:27'),(23,'Rektor USN Kolaka Lantik Ormawa 2026, Mahasiswa Didorong Jadi Pemimpin Masa Depan','rektor-usn-kolaka-lantik-ormawa-2026-mahasiswa-didorong-jadi-pemimpin-masa-depan','<p style=\"text-align: justify; \">Foto: ormawa usn kolaka</p><p style=\"text-align: justify; \">Kamis, 9 April 2026 16:46 PM</p><p style=\"text-align: justify; \">Kolaka – Universitas Sembilanbelas November Kolaka kembali menunjukkan komitmennya dalam membangun generasi unggul melalui pelantikan Pengurus Organisasi Mahasiswa (Ormawa) periode 2026. Kegiatan yang berlangsung khidmat dan penuh semangat ini digelar di Auditorium USN Kolaka, Kamis (9/4/2026).</p><p style=\"text-align: justify;\">Pelantikan tersebut menjadi momentum penting dalam dinamika kemahasiswaan, sekaligus menandai dimulainya kepengurusan baru dari Majelis Permusyawaratan Mahasiswa (MPM), Badan Eksekutif Mahasiswa (BEM), serta Unit Kegiatan Mahasiswa (UKM). Para pengurus yang dilantik diharapkan mampu membawa semangat perubahan dan inovasi di lingkungan kampus.</p><p style=\"text-align: justify;\">Prosesi pelantikan berlangsung tertib dan penuh makna, ditandai dengan penandatanganan berita acara oleh para ketua Ormawa sebagai simbol komitmen dan tanggung jawab. Kegiatan ini turut disaksikan oleh Wakil Rektor Bidang Kemahasiswaan dan Alumni, Qammaddin, serta Kepala Biro Akademik dan Kemahasiswaan, Lete.</p><p style=\"text-align: justify;\">Rektor USN Kolaka, Prof. Dr. Nur Ihsan, secara simbolis menyerahkan Surat Keputusan (SK) sebagai tanda resmi dimulainya kepengurusan baru.</p><p style=\"text-align: justify;\">Dalam sambutannya, Rektor menegaskan bahwa mahasiswa memiliki peran yang sangat strategis dalam menentukan arah masa depan bangsa. Ia juga memberikan apresiasi kepada para mahasiswa yang bersedia mengemban amanah dalam organisasi.</p><p style=\"text-align: justify;\">Menurutnya, organisasi mahasiswa bukan sekadar wadah aktivitas, tetapi merupakan ruang pembelajaran yang membentuk karakter kepemimpinan, meningkatkan kepedulian sosial, serta mengasah kemampuan akademik dan profesional.</p><p style=\"text-align: justify;\">“Organisasi mahasiswa adalah ruang belajar yang sangat penting. Di sinilah mahasiswa ditempa menjadi pemimpin masa depan yang berintegritas, tangguh, dan mampu bersaing,” tegas Prof. Dr. Nur Ihsan.</p><p style=\"text-align: justify;\">Ia juga mendorong para pengurus Ormawa untuk menghadirkan program-program inovatif yang tidak hanya berdampak di lingkungan kampus, tetapi juga memberikan manfaat nyata bagi masyarakat.</p><p style=\"text-align: justify;\">Pelantikan ini diharapkan menjadi awal dari langkah besar mahasiswa dalam berkontribusi, memperkuat kolaborasi, serta menjaga nama baik kampus di berbagai bidang.</p><p style=\"text-align: justify; \">Dengan semangat baru yang telah dikukuhkan, pengurus Ormawa USN Kolaka periode 2026 diharapkan mampu menjadi agen perubahan dan motor penggerak kemajuan kampus.</p>','Foto: ormawa usn kolakaKamis, 9 April 2026 16:46 PMKolaka – Universitas Sembilanbelas November Kolaka kembali menunjukkan komitmennya dalam membangu',8,'Usn, kolaka, ormawa, mahasiswa, sultra, indonesia,',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69d8b69af3490.jpg',128,'2026-04-10 15:36:42'),(24,'Pemerintah Provinsi Sulawesi Tenggara mulai menunjukkan keseriusan dalam membangun birokrasi profesional dengan menerapkan sistem merit secara lebih tegas dalam pengisian jabatan.','pemerintah-provinsi-sulawesi-tenggara-mulai-menunjukkan-keseriusan-dalam-membangun-birokrasi-profesional-dengan-menerapkan-sistem-merit-secara-lebih-tegas-dalam-pengisian-jabatan','<h6><font color=\"#6badde\">Gubernur Sulawesi Tenggara Andi Sumangerukka saat mengumumkan hasil seleksi pejabat eselon III Dan IV dalam penerapan sistem merit di lingkup Pemprov Sultra.&nbsp;</font></h6><h6><font color=\"#6badde\"><br></font></h6><p style=\"text-align: justify;\"><font style=\"background-color: rgb(255, 255, 255);\"><b>Xyron News Network (Rahwam)</b></font></p><p style=\"text-align: justify;\"><b>KENDARI, Rabu, 8 April 2026 —</b><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Gubernur Sultra, Andi Sumangerukka, secara langsung mengumumkan hasil seleksi pejabat administrator (eselon III) dan pengawas (eselon IV) di Kantor Gubernur Sultra, Rabu (8 April 2026). Langkah ini menjadi bagian dari reformasi birokrasi berbasis kompetensi, integritas, dan kinerja.</span></p><p style=\"text-align: justify;\">Dalam pengumuman tersebut, peserta dibagi ke dalam dua kategori, yakni “lolos” dan “lulus”. Kategori “lolos” merupakan peserta yang terpilih dan akan segera dilantik dalam waktu dekat, sementara “lulus” adalah mereka yang memenuhi syarat namun belum mendapatkan posisi jabatan.</p><p style=\"text-align: justify;\">Nama-nama yang masuk kategori “lulus” akan dimasukkan dalam bank talenta ASN, yang nantinya menjadi rujukan dalam pengisian jabatan di masa mendatang, termasuk peluang promosi ke jenjang yang lebih tinggi.</p><p style=\"text-align: justify;\">Secara keseluruhan, seleksi jabatan eselon III diikuti oleh 83 peserta untuk mengisi 27 posisi. Sementara itu, seleksi eselon IV diikuti oleh 68 peserta dengan total 24 jabatan yang tersedia.</p><p style=\"text-align: justify;\">Proses seleksi berlangsung ketat, terutama pada formasi tertentu seperti jabatan tenaga medis yang memiliki tingkat persaingan tinggi. Namun, terdapat dua jabatan yang tidak dilanjutkan proses pengisiannya karena hanya diusulkan satu kandidat, sehingga tidak memenuhi prinsip kompetisi terbuka dalam sistem merit.</p><p style=\"text-align: justify;\">“Kita ingin merubah sistem. Jika sistem berjalan baik, maka organisasi juga akan berjalan efektif dan anggaran tepat sasaran,” ujar Andi Sumangerukka.</p><p style=\"text-align: justify;\">Ia menegaskan bahwa setiap peserta yang dinyatakan lolos merupakan hasil dari penilaian objektif, bukan faktor kebetulan. Penempatan jabatan dilakukan berdasarkan kemampuan, kompetensi, dan integritas yang dimiliki.</p><p style=\"text-align: justify;\">Lebih lanjut, evaluasi berkala juga akan diterapkan kepada pejabat terpilih. Jika dalam pelaksanaannya tidak memenuhi standar, maka posisi tersebut dapat digantikan oleh kandidat lain yang telah masuk dalam bank talenta.</p><p style=\"text-align: justify;\">Melalui penerapan sistem merit ini, Pemprov Sultra menargetkan terwujudnya birokrasi yang lebih profesional, adaptif, serta mampu memberikan pelayanan publik yang optimal dan responsif terhadap kebutuhan masyarakat.</p><p style=\"text-align: justify;\">“Marilah kita bekerja bukan untuk individu, tetapi untuk kemajuan Sulawesi Tenggara,” pungkasnya.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><b>(Rahwam – Xyron News Network)&nbsp;</b></span></p>','Gubernur Sulawesi Tenggara Andi Sumangerukka saat mengumumkan hasil seleksi pejabat eselon III Dan IV dalam penerapan sistem merit di lingkup Pemprov ',8,'Andi sumangerukka, Gubernur, Sultra, Pemprov ',7,8,'published','https://www.xyronnews.com/uploads/posts/post_69d8ff51610a8.jpeg',104,'2026-04-12 20:21:14'),(25,'Sumringah Dapat Rp 11,42 Triliun dari Kejagung, Purbaya: Bisa untuk Tambal Defisit APBN','sumringah-dapat-rp-11-42-triliun-dari-kejagung-purbaya-bisa-untuk-tambal-defisit-apbn','<h6><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#3984c6\">Menteri Keuangan Purbaya Yudhi Sadewa di Kantor Kejaksaan Agung, Jakarta, Jumat (10/4/2026). (B-Universe Photo/Addin Anugrah Siwi)&nbsp;</font></span></h6><h6><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#3984c6\"><br></font></span></h6><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><b>JAKARTA, Xyron News Network (XXN)—&nbsp;</b>Kejaksaan Agung (Kejagung) menyerahkan dana hasil penegakan hukum dan denda administratif senilai Rp 11,42 triliun kepada pemerintah. Dana tersebut kini telah resmi masuk ke kas negara sebagai tambahan likuiditas.</span></p><p style=\"text-align: justify;\">Penyerahan dilakukan langsung oleh Jaksa Agung ST Burhanuddin kepada Kementerian Keuangan, disaksikan Presiden Prabowo Subianto di Kantor Kejaksaan Agung, Jakarta, Jumat (10/4/2026).</p><p style=\"text-align: justify;\">Menteri Keuangan Purbaya Yudhi Sadewa menyampaikan bahwa dana tersebut akan digunakan untuk memperkuat kondisi fiskal nasional, termasuk membantu menutup defisit APBN tahun 2026.</p><p style=\"text-align: justify;\">“Dana ini bisa kita gunakan untuk menambal defisit atau mendukung kembali program pembangunan yang sempat tertunda,” ujar Purbaya.</p><p style=\"text-align: justify;\">Ia menambahkan, sebagian anggaran juga berpotensi dialokasikan ke sektor prioritas seperti pendidikan, termasuk program beasiswa LPDP.</p><p style=\"text-align: justify;\">“Ke depan masih ada potensi tambahan penerimaan. Prosesnya belum selesai, jadi APBN kita tetap aman,” tambahnya.</p><p style=\"text-align: justify;\">Sumber dana sendiri berasal dari berbagai sektor, mulai dari denda administratif kehutanan, penanganan kasus korupsi, denda lingkungan hidup, hingga penerimaan dari sektor perpajakan.</p>','Menteri Keuangan Purbaya Yudhi Sadewa di Kantor Kejaksaan Agung, Jakarta, Jumat (10/4/2026). (B-Universe Photo/Addin Anugrah Siwi)&nbsp;JAKARTA, Xyron',1,'Berita, Nasional, XNN, purbaya, Indonesia',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69db9ba1a0586.jpeg',200,'2026-04-12 20:18:25'),(26,'DPR Klaim Belum Tahu Soal Akses Udara untuk Militer AS','dpr-klaim-belum-tahu-soal-akses-udara-untuk-militer-as','<h6><font color=\"#6badde\">Foto: F-15ID-AIRCRAFT</font></h6><p align=\"justify\"><strong>Xyron News Network, Jakarta</strong> - Dewan Perwakilan Rakyat\r\n buka suara mengenai kabar dokumen rahasia pertahanan Amerika Serikat \r\nyang menjabarkan rencana untuk mengamankan akses lebih bebas (blanket \r\noverflight access) bagi pesawat militernya melalui wilayah udara \r\nIndonesia.</p>\r\n<p align=\"justify\">Wakil Ketua Komisi I DPR Dave Laksono mengatakan legislatif belum \r\ndapat memberikan komentar lebih jauh sebelum ada kejelasan resmi dari \r\npihak pemerintah. Menurutnya, pemberitaan tersebut sejauh ini masih \r\nbersumber dari dokumen yang belum dikonfirmasi secara resmi oleh \r\npemerintah Indonesia maupun Amerika Serikat.&nbsp;</p>\r\n<p align=\"justify\">“Komisi I DPR RI senantiasa memonitor isu-isu strategis yang \r\nberkaitan dengan pertahanan dan kedaulatan negara, termasuk ruang udara \r\nIndonesia,” ujar Dave, Senin (13/04/2026). </p><p align=\"justify\">Dave mengatakan penggunaan ruang udara Indonesia oleh militer asing \r\nhanya dapat dilakukan berdasarkan izin resmi yang sesuai dengan hukum \r\nnasional, peraturan internasional, serta prinsip kedaulatan negara. \r\nMenurutnya, Indonesia memiliki aturan ketat terkait Alur Laut Kepulauan \r\nIndonesia (ALKI) dan jalur udara strategis sehingga setiap kebijakan \r\nyang menyangkut akses militer asing harus melalui kajian mendalam dan \r\nmekanisme politik yang jelas.</p>\r\n\r\n    \r\n        \r\n        \r\n    \r\n<p align=\"justify\">Dia mengatakan Indonesia memang tetap terbuka terhadap kerja sama \r\npertahanan yang saling menguntungkan, tetapi tidak akan mengorbankan \r\nkedaulatan dan kepentingan nasional. Komisi I DPR mendorong agar \r\npemerintah mengedepankan diplomasi yang tegas, transparan, dan seimbang,\r\n sehingga setiap kerja sama dengan mitra strategis benar-benar \r\nmemperkuat posisi Indonesia di kawasan Indo-Pasifik.</p><p align=\"justify\">“Komisi I DPR RI menegaskan bahwa setiap kebijakan terkait akses \r\nruang udara militer asing harus melalui mekanisme resmi dan transparan. \r\nDPR akan terus menjalankan fungsi pengawasan untuk memastikan bahwa \r\nkepentingan bangsa dan kedaulatan negara tetap menjadi prioritas utama,”\r\n ujarnya.&nbsp;</p>\r\n<p align=\"justify\">Perlu diketahui, terdapat kabar yang menyebut dokumen rahasia \r\npertahanan Amerika Serikat menjabarkan rencana untuk akses lebih bebas \r\n(blanket overflight access) bagi pesawat militernya melalui wilayah \r\nudara Indonesia, setelah pertemuan antara Presiden Prabowo Subianto dan \r\nPresiden AS Donald Trump di Washington.</p>\r\n<p align=\"justify\">Prabowo mengunjungi Washington D.C. dari 18 hingga 20 Februari 2026 \r\nuntuk menghadiri KTT Dewan Perdamaian atau Board of Peace. Selama \r\nkunjungan tersebut, Prabowo disebut menyetujui sebuah proposal untuk \r\nmemberikan izin lintas udara menyeluruh bagi pesawat Amerika Serikat \r\nmelalui wilayah udara Indonesia dalam pertemuan bilateral dengan Trump, \r\nmenurut rincian yang tercantum dalam dokumen rahasia AS.</p><p></p><p></p><p></p>','Foto: F-15ID-AIRCRAFTXyron News Network, Jakarta - Dewan Perwakilan Rakyat\r\n buka suara mengenai kabar dokumen rahasia pertahanan Amerika Serikat \r',1,'',8,NULL,'published','https://images.bloombergtechnoz.com/data/2024/01/image-20240107165927.jpg',195,'2026-04-13 20:44:27'),(27,'Ketua terpilih HMPS Pendidikan jasmani Usn Kolaka Soroti Fasilitas AC Kampus yang tak berfungsi.','ketua-terpilih-hmps-pendidikan-jasmani-usn-kolaka-soroti-fasilitas-ac-kampus-yang-tak-berfungsi','<p align=\"justify\"><b>XNN - Kolaka </b>Meski belum resmi dilantik, Ketua Umum terpilih Himpunan Mahasiswa Program Studi Pendidikan Jasmani mulai menunjukkan kepeduliannya terhadap kondisi fasilitas kampus yang dinilai belum optimal.Santi, selaku Ketua Umum terpilih, menyoroti fasilitas pendingin ruangan (AC) di sejumlah ruang perkuliahan yang diduga tidak berfungsi sebagaimana mestinya. Kondisi ini dinilai mengurangi kenyamanan mahasiswa dalam mengikuti proses belajar mengajar.</p><p align=\"justify\"><br>“Fasilitas itu bukan sekadar dipasang, tapi harus benar-benar berfungsi. AC yang tidak berjalan maksimal sama saja mengabaikan kenyamanan mahasiswa dalam proses belajar,” ujar Santi.</p><p align=\"justify\"><br>Ia menegaskan bahwa keberadaan fasilitas seperti AC seharusnya menjadi penunjang utama dalam menciptakan suasana belajar yang kondusif, terutama di tengah kondisi cuaca yang panas. Namun, jika fasilitas tersebut tidak berfungsi, maka manfaatnya tidak akan dirasakan oleh mahasiswa.</p><p align=\"justify\"><br>Lebih lanjut, Santi juga mempertanyakan pengelolaan dan perawatan fasilitas yang ada di lingkungan kampus. Menurutnya, perlu adanya perhatian serius dari pihak terkait agar fasilitas yang telah disediakan tidak hanya menjadi pelengkap semata.</p><p align=\"justify\"><br>“Kalau hanya menjadi pajangan, untuk apa dipasang? Mahasiswa butuh kenyamanan nyata, bukan fasilitas yang hanya terlihat ada tapi tidak bisa digunakan,” tegasnya. Ia berharap pihak kampus segera melakukan evaluasi dan perbaikan terhadap fasilitas yang bermasalah, sehingga mahasiswa dapat menjalani proses pembelajaran dengan lebih nyaman dan maksimal.</p><p align=\"justify\"><br>Meski belum resmi menjabat, langkah Santi dalam menyuarakan persoalan ini menjadi sinyal awal bahwa kepemimpinan baru HMPS Pendidikan Jasmani akan hadir dengan sikap kritis, responsif, dan berpihak pada kepentingan mahasiswa. Sorotan ini sekaligus mengingatkan bahwa mahasiswa memiliki peran penting sebagai kontrol sosial dalam menjaga kualitas layanan pendidikan di lingkungan kampus.</p>','XNN - Kolaka Meski belum resmi dilantik, Ketua Umum terpilih Himpunan Mahasiswa Program Studi Pendidikan Jasmani mulai menunjukkan kepeduliannya terha',8,'Usn, kolaka, penjas, AC, ketua, terpilih',8,NULL,'draft','https://www.xyronnews.com/uploads/posts/post_69df95497ceb7.jpeg',0,NULL),(28,'Mahasiswa Laporkan Admin FKKU, Diduga Lalai dan Melakukan Pembiaran Hingga Picu Pencemaran Nama Baik ‎','mahasiswa-laporkan-admin-fkku-diduga-lalai-dan-melakukan-pembiaran-hingga-picu-pencemaran-nama-baik','<h6 align=\"justify\"><font color=\"#3984c6\">keterangan foto: Mahasiswa Laporkan Admin FKKU</font></h6><p align=\"justify\"><b>XNN | Kolaka Utara –</b> Sejumlah mahasiswa secara resmi melaporkan admin grup Facebook media sosial “Forum Komentar Kolaka Utara” (FKKU) kepada aparat penegak hukum (APH) atas dugaan kelalaian dalam mengelola forum yang berakhir pada maraknya pencemaran nama baik. Rabu, (15/4/2026).<br>‎<br>‎Laporan tersebut dilayangkan setelah muncul berbagai unggahan dari akun anonim dan palsu yang dinilai menyerang kehormatan serta reputasi individu tertentu tanpa dasar yang jelas.<br>‎<br>‎Mahasiswa menilai, admin FKKU telah melakukan pembiaran terhadap aktivitas tersebut, sehingga konten yang mengandung fitnah terus beredar luas di tengah masyarakat, padahal aturan FKKU jelas dan&nbsp; tidak akan meloloskan unggahan yang mengarah pada penyerangan personal.<br>‎<br>‎Anwar, salah satu perwakilan mahasiswa menyampaikan bahwa media sosial seharusnya menjadi ruang diskusi publik yang sehat dan konstruktif, bukan justru menjadi sarana penyebaran informasi yang merugikan pihak lain.<br>‎<br>‎\"Kami melihat adanya pembiaran yang dilakukan admin terhadap akun-akun anonim yang secara bebas menyebarkan tuduhan tanpa bukti. Ini bukan lagi kebebasan berpendapat, tetapi sudah masuk ranah pencemaran nama baik,\" tegas Anwar kepada awak media pada Rabu, (15/04/2026).<br>‎<br>‎Mahasiswa juga menyoroti bahwa admin grup memiliki tanggung jawab moral dan hukum dalam mengawasi serta memoderasi setiap konten yang dipublikasikan dalam forum tersebut. Terlebih lagi, kelompok dengan jumlah anggota yang besar dinilai memiliki dampak signifikan terhadap opini publik.<br>‎<br>‎Dalam laporan yang disampaikan, mahasiswa meminta agar aparat penegak hukum segera melakukan pemeriksaan terhadap admin forum, termasuk menelusuri akun-akun anonim yang diduga menjadi sumber penyebaran konten bermasalah.<br>‎<br>‎Selain itu, mereka juga mendesak adanya tindakan tegas untuk mencegah kejadian serupa terulang, termasuk kemungkinan penutupan atau pemantauan aktivitas forum jika terbukti melanggar aturan yang berlaku.<br>‎<br>‎Kasus ini kembali menjadi pengingat pentingnya etika dalam bermedia sosial serta peran aktif pengelola platform dalam menjaga ruang digital yang sehat, aman, dan bertanggung jawab</p>','keterangan foto: Mahasiswa Laporkan Admin FKKUXNN | Kolaka Utara – Sejumlah mahasiswa secara resmi melaporkan admin grup Facebook media sosial “Fo',8,'mahasiswa, kolaka utara, FKKU, pencemaran nama baik',8,8,'published','https://www.xyronnews.com/uploads/posts/post_69dfadc64d3b7.jpg',105,'2026-04-15 22:24:54'),(29,'10 Ribu BPJS PBI di Mateng Kembali Diaktifkan, KOHATI Berikan Apresiasi ','10-ribu-bpjs-pbi-di-mateng-kembali-diaktifkan-kohati-berikan-apresiasi','<h6><span style=\"background-color: rgb(255, 255, 255);\"><font color=\"#6badde\">Foto:&nbsp;Sekretaris Kohati Mamuju Tengah, Rahmayun</font></span></h6><h6><span style=\"background-color: rgb(255, 255, 255);\"><font color=\"#6badde\"><br></font></span></h6><p><strong>Xyron News Network</strong>, Mamuju Tengah – Kabar baik bagi \r\nmasyarakat Kabupaten Mamuju Tengah. Program BPJS Penerima Bantuan Iuran \r\n(PBI) yang sempat dinonaktifkan oleh pemerintah daerah per 31 Desember \r\n2025, kini kembali diaktifkan sejak April 2026 setelah melalui proses \r\npendataan ulang dan verifikasi.</p>\r\n<p>Kepala BPJS Kesehatan Cabang Mamuju Tengah, Firman, mengungkapkan \r\nbahwa reaktivasi ini merupakan hasil dari kerja sama lintas sektor, \r\ntermasuk Dinas Sosial yang mengusulkan penambahan peserta baru.</p>\r\n<p>“Iya bu, bulan Maret kemarin ada penambahan usulan peserta dari Dinas\r\n Sosial sebanyak 10 ribuan. Alhamdulillah, tingkat keaktifan peserta di \r\nKabupaten Mamuju Tengah pada April ini sudah naik dari 64 persen menjadi\r\n 80,4 persen, sesuai target RPJMN,” ujar Firman.</p><p>Peningkatan ini menunjukkan progres signifikan dalam upaya pemerintah\r\n daerah memastikan akses layanan kesehatan bagi masyarakat kurang mampu \r\ntetap terjamin melalui program Jaminan Kesehatan Nasional (JKN).</p>\r\n<p>Sementara itu, Sekretaris Kohati Mamuju Tengah, Rahmayuni, turut \r\nmengapresiasi langkah pemerintah dan pihak terkait dalam mengaktifkan \r\nkembali kepesertaan BPJS PBI tersebut.</p>\r\n<p>“Alhamdulillah, akhirnya sudah 80 persen BPJS PBI yang sebelumnya \r\ndinonaktifkan kini kembali diaktifkan. Kami sangat Apresiasi Karena \r\nsetelah melalui proses seleksi ulang, yang benar-benar layak menerima \r\nbantuan itulah yang diaktifkan kembali. Kami juga ikut mendampingi \r\nproses tersebut, dan sesuai harapan kita bersama yang lahir dari RDP” \r\nungkap Rahmayuni.</p>\r\n<p>Reaktivasi ini diharapkan dapat memberikan kepastian layanan \r\nkesehatan bagi masyarakat yang membutuhkan, sekaligus meningkatkan \r\nkualitas perlindungan sosial di Kabupaten Mamuju Tengah.</p><p><br></p><p><br></p>','SULBARPEDIA.COM, Mamuju Tengah – Kabar baik bagi \r\nmasyarakat Kabupaten Mamuju Tengah. Program BPJS Penerima Bantuan Iuran \r\n(PBI) yang sempat d',1,'',8,8,'published','https://sulbarpedia.com/wp-content/uploads/2026/04/IMG-20260409-WA0013-800x726.jpg',91,'2026-04-16 01:30:44'),(30,'Napi Korupsi, Eks Kepala Syahbandar Kolaka Kedapatan Berkeliaran dan ngopi di Kedai Kopi','napi-korupsi-eks-kepala-syahbandar-kolaka-kedapatan-berkeliaran-dan-ngopi-di-kedai-kopi','<h6 align=\"justify\"><font color=\"#6badde\">Foto:<b>&nbsp;</b>Mantan Kepala Syahbandar Kolaka, Supriadi berkeliaran di luar rutan didampingi petugas.</font></h6><h6 align=\"justify\"><font color=\"#6badde\"><br></font></h6><p align=\"justify\"><b>XNN | Xyron News Network -</b> Terpidana kasus korupsi perizinan pertambangan nikel di \r\nKabupaten Kolaka Utara, Sulawesi Tenggara, Supriadi menjadi sorotan \r\npublik.\r\n\r\nItu setelah mantan Kepala Syahbandar Kolaka itu kedapatan keluar rumah \r\ntahanan (rutan) Kelas II A Kendari tanpa pengawalan ketat, Selasa \r\n(14/4/2026).<br></p><p align=\"justify\">Dalam video yang disebarluaskan kendarikini.com, Supriadi terlihat \r\nsempat mampir ke kedai kopi yang berada di Jalan Abunawas, Kelurahan \r\nBende, Kecamatan Kadia.</p><p align=\"justify\">Dalam video berdurasi 27 detik tersebut, Supriadi seperti dikutip dari \r\nInilah.com mengenakan peci putih, kemeja batik lengan pendek, serta \r\ncelana panjang hitam, dan sepatu. Ia santai di luar rutan didampingi \r\nseseorang yang diduga petugas Syahbandar.<br><br><br>Napi kasus korupsi itu tampak santai melenggang bebas di luar tahanan. \r\nUsai mampir ke kedai kopi, dia kemudian melanjutkan ibadah di masjid \r\nterdekat.\r\n\r\nBelum ada tanggapan dari Supriadi atau pun pihak rutan Kelas II A \r\nKendari.</p><p align=\"justify\">Untuk diketahui, Supriadi dinyatakan bersalah dalam praktik penerbitan \r\nSurat Izin Berlayar (SIB) bagi 12 kapal tongkang pengangkut nikel ilegal\r\n milik PT Pandu Citra Mulia (PCM).\r\n\r\nDalam persidangan sebelumnya, Supriadi terbukti menyalahgunakan wewenang\r\n dengan menggunakan dokumen palsu milik PT Alam Mitra Indah Nugraha \r\n(AMIN).</p><p align=\"justify\">Ia juga memfasilitasi pengapalan melalui dermaga jetty PT Kurnia Mining \r\nResources yang tidak berizin.</p><p>Terkait proyek ini, Supriadi menerima suap sebesar Rp100 juta per \r\ntongkang sebagai imbalan penerbitan dokumen. Atas tindakan yang \r\nmerugikan keuangan negara hingga ratusan miliar rupiah, majelis hakim \r\nPengadilan Negeri Tipikor Kendari menjatuhkan vonis 5 tahun penjara, \r\ntermasuk denda Rp600 juta, serta kewajiban membayar uang pengganti \r\nsebesar Rp1,255 miliar.&nbsp;</p>','Foto:&nbsp;Mantan Kepala Syahbandar Kolaka, Supriadi berkeliaran di luar rutan didampingi petugas.XNN | Xyron News Network - Terpidana kasus korupsi p',8,'koruptor, kepala, syahbandar,kedai, kopi',8,NULL,'published','https://img.herald.id/wp-content/uploads/sites/1/2026/04/supriadi-napi_keluar.jpg',110,'2026-04-16 01:25:50'),(31,'DPM FH USN Kolaka Desak Pembubaran FKKU: \"Kebebasan Berpendapat Bukan Tameng untuk Melanggar Hukum\"','dpm-fh-usn-kolaka-desak-pembubaran-fkku-kebebasan-berpendapat-bukan-tameng-untuk-melanggar-hukum','<h6><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\"><font color=\"#6badde\">Foto: ketua DPM Fakultas Hukum Usn Kolaka&nbsp;</font></span></h6><h6><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\"><font color=\"#6badde\"><br></font></span></h6><h6><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\"><font color=\"#6badde\"> </font></span></h6><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\"><b><font color=\"#ff0000\">XNN | Xyron News Network&nbsp;</font></b></span><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><b><font color=\"#ff0000\">KOLAKA UTARA –</font> </b>Eskalasi tuntutan pembubaran Forum Komentar Kolaka Utara (FKKU) memasuki babak baru. Dukungan kini datang dari barisan intelektual muda, Dewan Perwakilan Mahasiswa (DPM) Fakultas Hukum Universitas Sembilanbelas November (USN) Kolaka, yang secara resmi meminta otoritas terkait untuk menertibkan hingga membubarkan forum tersebut.</span></p><p style=\"text-align: justify;\">Dalam rilis resmi yang diterima <font color=\"#ff0000\">XXN Xyron News Network</font> pada Kamis (16/04/2026), Muh Saipul, perwakilan DPM FH USN Kolaka, menyatakan bahwa eksistensi FKKU saat ini telah menyimpang jauh dari khitah asalnya sebagai ruang partisipasi publik.</p><p style=\"text-align: justify;\">Saipul menilai, forum yang seharusnya menjadi wadah diskursus sehat kini justru bertransformasi menjadi inkubator persoalan hukum yang meresahkan masyarakat.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">\"Secara ideal, forum seperti FKKU adalah ruang demokrasi. Namun, ketika konten di dalamnya didominasi oleh narasi yang berpotensi melanggar hukum, maka evaluasi total bukan lagi pilihan, melainkan keharusan,\" tegas Saipul.</span></p><p style=\"text-align: justify;\">Sebagai aktivis hukum, Saipul mengingatkan publik bahwa hak berekspresi di Indonesia tidak bersifat absolut. Ia menekankan bahwa setiap kata yang dilempar ke ruang publik memiliki konsekuensi hukum, terutama terkait kehormatan dan reputasi individu.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Esensi Hukum&nbsp;</span><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Kebebasan berpendapat tidak boleh menjadi alat untuk melakukan fitnah, pencemaran nama baik, atau penyebaran hoaks.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Jika mediasi dan penertiban gagal, pembubaran adalah langkah hukum yang sah dan rasional.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Lebih lanjut, ia menyoroti peran admin atau pengelola forum yang dianggap lalai dalam melakukan moderasi. Menurutnya, pembiaran terhadap aktivitas ilegal di dalam platform merupakan bentuk tanggung jawab renteng yang bisa menyeret pengelola ke ranah pidana.</span></p><p style=\"text-align: justify;\">Menutup pernyataannya, DPM FH USN Kolaka menegaskan berdiri bersama masyarakat yang merasa dirugikan oleh aktivitas di FKKU.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">\"Kami mendukung penuh langkah masyarakat. Jika forum ini terus menjadi pemicu konflik hukum dan sosial tanpa adanya kendali, maka pembubaran adalah solusi final demi menjaga kondusivitas di Kolaka Utara,\" pungkasnya.</span><br></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Hingga berita ini diturunkan, desakan dari elemen mahasiswa ini diprediksi akan menjadi motor penggerak bagi pihak berwenang untuk segera mengambil tindakan preventif maupun represif terhadap tata kelola media sosial di wilayah tersebut.</span><br></p>','Foto: ketua DPM Fakultas Hukum Usn Kolaka&nbsp; XNN | Xyron News Network&nbsp;KOLAKA UTARA – Eskalasi tuntutan pembubaran Forum Komentar Kolaka Utar',8,'DPM, HUKUM, FKKU, Kolaka, utara',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69e151756aaaa.jpeg',86,'2026-04-17 04:15:33'),(32,'Skandal Suap Tambang Nikel, Ketua Ombudsman RI Resmi Jadi Tersangka dan Ditahan!','skandal-suap-tambang-nikel-ketua-ombudsman-ri-resmi-jadi-tersangka-dan-ditahan','<h6 style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#3984c6\">Penyidik Kejaksaan Agung mengawal Ketua Ombudsman RI 2026 - 2031 Hery Susanto (kedua kanan) seusai menjalani pemeriksaan dan penetapan tersangka di Gedung Bundar Jampidsus Kejaksaan Agung, Jakarta, Kamis (16/4/2026). (Foto: ANTARA FOTO/Muhammad Iqbal)&nbsp;</font></span></h6><h6 style=\"text-align: justify;\"><b style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; color: rgb(255, 0, 0); -webkit-text-size-adjust: 100%;\"><br></b></h6><h6 style=\"text-align: justify;\"><b style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; color: rgb(255, 0, 0); -webkit-text-size-adjust: 100%;\">XNN | Xyron News Network</b></h6><p style=\"text-align: justify;\"><font style=\"text-align: var(--bs-body-text-align); font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><b>JAKARTA – </b></font><span style=\"text-align: var(--bs-body-text-align); font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Kejaksaan Agung resmi menetapkan Ketua Ombudsman RI, Hery Susanto, sebagai tersangka dalam kasus dugaan korupsi tata kelola tambang nikel di Sulawesi Tenggara periode 2013-2025. Hery diduga kuat menyalahgunakan wewenangnya sebagai pengawas pelayanan publik untuk memuluskan kepentingan PT TSHI dengan imbalan miliaran rupiah.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Direktur Penyidikan Jaksa Agung Muda Bidang Tindak Pidana Khusus (Dirdik Jampidsus), Syarief Sulaeman Nahdi, mengungkapkan bahwa kasus ini bermula saat pemilik PT TSHI berinisial LD merasa keberatan atas perhitungan Pendapatan Negara Bukan Pajak (PNBP) yang ditetapkan oleh Kementerian Kehutanan (Kemenhut).</span></p><p style=\"text-align: justify;\">Demi menghindari kewajiban bayar kepada negara, LD menemui Hery untuk meminta bantuan. Hery pun menyetujui untuk melakukan pemeriksaan terhadap Kemenhut dengan skenario seolah-olah laporan tersebut datang dari pengaduan masyarakat.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">\"HS (Hery Susanto) bersedia membantu melakukan pemeriksaan kepada Kemenhut yang seolah-olah berawal dari pengaduan masyarakat,\" ujar Syarief kepada wartawan di Jakarta.</span></p><p style=\"text-align: justify;\">Berdasarkan hasil penyidikan, pertemuan mufakat jahat dilakukan pada April 2025 di dua lokasi, yakni Kantor Ombudsman dan Hotel Borobudur. Dalam pertemuan tersebut, pihak PT TSHI meminta Hery menerbitkan surat temuan kesalahan administrasi terkait perhitungan PNBP Izin Pinjam Pakai Kawasan Hutan.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Sebagai imbalan atas intervensi tersebut, Hery dijanjikan uang suap sebesar Rp1,5 miliar.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#ff0000\">\"Dengan kesepakatan saudara HS akan diberikan uang sejumlah Rp1,5 miliar,\" tambah Syarief.</font></span><br></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Hery menjalankan perannya dengan mengatur hasil pemeriksaan sehingga penagihan denda Kemenhut terhadap PT TSHI terlihat keliru. Ia bahkan memerintahkan agar perusahaan diizinkan menghitung sendiri beban yang harus dibayar kepada negara. Tak hanya itu, Hery juga membocorkan draf Laporan Hasil Pemeriksaan (LHP) kepada pihak PT TSHI untuk memastikan hasilnya sesuai keinginan pemesan.</span><br></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Atas perbuatannya, Hery Susanto dijerat dengan <u><font color=\"#ff0000\">Pasal 12 huruf a, 12 huruf b, Pasal 5, dan Pasal 606 KUHP</font></u> tentang tindak pidana korupsi.</span><br></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Guna kepentingan penyidikan, penyidik langsung melakukan penahanan terhadap Hery di Rutan Salemba cabang Kejari Jakarta Selatan selama 20 hari ke depan. Kejagung memastikan akan terus mendalami keterlibatan pihak lain dalam skandal tata kelola tambang ini.</span><br></p>','Penyidik Kejaksaan Agung mengawal Ketua Ombudsman RI 2026 - 2031 Hery Susanto (kedua kanan) seusai menjalani pemeriksaan dan penetapan tersangka di Ge',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69e24d4953b79.jpeg',72,'2026-04-17 22:10:01'),(33,'Pertamina Resmi Menyesuaikan Harga BBM Nonsubsidi Per 18 April 2026: Pertamax Turbo dan Dex Series Melonjak Signifikan','pertamina-resmi-menyesuaikan-harga-bbm-nonsubsidi-per-18-april-2026-pertamax-turbo-dan-dex-series-melonjak-signifikan','<h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#3984c6\">Foto: Petugas SPBU Pertamina di kawasan Bekasi, Jawa Barat, Senin (23/1/2024).</font></h6><h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#3984c6\"><br></font></h6><p data-path-to-node=\"3\" align=\"justify\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\"><b data-path-to-node=\"3\" data-index-in-node=\"0\">XNN | Xyron News Network JAKARTA</b> –</font> PT Pertamina (Persero) kembali melakukan langkah strategis dengan melakukan penyesuaian harga jual eceran bahan bakar minyak (BBM) nonsubsidi. Terhitung mulai Sabtu, 18 April 2026, harga untuk jenis Pertamax Turbo, Dexlite, dan Pertamina Dex resmi mengalami kenaikan yang cukup signifikan di seluruh wilayah Indonesia.</p><p data-path-to-node=\"4\" align=\"justify\">Berdasarkan pengumuman resmi yang dirilis melalui laman perusahaan dan aplikasi MyPertamina, kebijakan ini diambil sebagai respons terhadap dinamika pasar energi global dan perhitungan formula harga dasar yang berlaku.</p><p data-path-to-node=\"6\" align=\"justify\">Rincian lonjatan harga di wilayah DKI jakarta,Untuk wilayah Ibu Kota dan sekitarnya, kenaikan harga terpantau cukup drastis, terutama pada lini bahan bakar diesel nonsubsidi. Berikut adalah rincian perbandingannya:</p><div align=\"justify\"><ol start=\"1\" data-path-to-node=\"7\"><li><p data-path-to-node=\"7,0,0\"><b data-path-to-node=\"7,0,0\" data-index-in-node=\"0\"><font color=\"#ff0000\">Pertamax Turbo (RON 98):</font></b> Mengalami kenaikan menjadi <font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\"><b data-path-to-node=\"7,0,0\" data-index-in-node=\"52\">Rp 19.400 per liter</b>. </font>Jika dibandingkan dengan harga per 1 April 2026 yang berada di angka Rp 13.100, terdapat selisih kenaikan sebesar Rp 6.300 per liter.</p></li><li><p data-path-to-node=\"7,1,0\"><b data-path-to-node=\"7,1,0\" data-index-in-node=\"0\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">Dexlite:</font></b> Produk diesel untuk kendaraan niaga ini kini dibanderol seharga <font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\"><b data-path-to-node=\"7,1,0\" data-index-in-node=\"73\">Rp 23.600 per liter</b>, </font>melonjak tajam dari harga sebelumnya yang hanya Rp 14.200 per liter.</p></li><li><p data-path-to-node=\"7,2,0\"><b data-path-to-node=\"7,2,0\" data-index-in-node=\"0\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">Pertamina Dex:</font></b> Bahan bakar diesel performa tinggi ini naik menjadi <b data-path-to-node=\"7,2,0\" data-index-in-node=\"67\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">Rp 23.900 per liter</font></b> dari harga sebelumnya Rp 14.500 per liter.</p><p data-path-to-node=\"7,2,0\"><br></p></li></ol><p data-path-to-node=\"9\">BBM Subsidi dan pertamax Tetap Stabil Di tengah kenaikan tajam pada produk-produk <i data-path-to-node=\"9\" data-index-in-node=\"44\">high-end</i> tersebut, Pertamina membawa kabar baik bagi pengguna BBM subsidi dan produk RON 92. Perusahaan pelat merah ini memutuskan untuk tidak mengubah harga BBM jenis penugasan dan subsidi.</p><ul data-path-to-node=\"10\"><li><p data-path-to-node=\"10,0,0\"><b data-path-to-node=\"10,0,0\" data-index-in-node=\"0\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">Pertalite (RON 90)</font></b> tetap dipatok pada harga <font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\"><b data-path-to-node=\"10,0,0\" data-index-in-node=\"44\">Rp 10.000 per liter</b>.</font></p></li><li><p data-path-to-node=\"10,1,0\"><b data-path-to-node=\"10,1,0\" data-index-in-node=\"0\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">BioSolar</font></b> tetap bertahan di angka <b data-path-to-node=\"10,1,0\" data-index-in-node=\"33\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">Rp 6.800 per liter</font></b>.</p></li><li><p data-path-to-node=\"10,2,0\"><b data-path-to-node=\"10,2,0\" data-index-in-node=\"0\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">Pertamax (RON 92)</font></b> masih dipertahankan pada harga <font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\"><b data-path-to-node=\"10,2,0\" data-index-in-node=\"49\">Rp 12.300 per liter</b>.</font></p></li><li><p data-path-to-node=\"10,3,0\"><b data-path-to-node=\"10,3,0\" data-index-in-node=\"0\"><font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\">Pertamax Green 95</font></b> juga tidak mengalami perubahan dan tetap di harga <font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\"><b data-path-to-node=\"10,3,0\" data-index-in-node=\"68\">Rp 12.900 per liter</b>.</font></p></li></ul><h4 data-path-to-node=\"11\"><br></h4><p data-path-to-node=\"12\">Pihak manajemen Pertamina menjelaskan bahwa penyesuaian harga ini mengacu pada regulasi pemerintah yang ketat. Formula yang digunakan selaras dengan <font color=\"#ff0000\" style=\"background-color: rgb(255, 255, 255);\"><b data-path-to-node=\"12\" data-index-in-node=\"149\">Keputusan Menteri (Kepmen) ESDM No. 245.K/MG.01/MEM.M/2022</b>,</font> yang merupakan perubahan atas Kepmen No. 62 K/12/MEM/2020 tentang Formula Harga Dasar dalam Perhitungan Harga Jual Eceran Jenis Bahan Bakar Minyak Umum.</p><p data-path-to-node=\"13\">\"Penyesuaian ini dilakukan secara berkala mengikuti tren harga minyak mentah dunia dan rata-rata publikasi harga produk minyak (Mean of Platts Singapore/MOPS). Hal ini demi menjaga ekosistem industri migas yang tetap sehat dan kompetitif,\" tulis manajemen dalam keterangan di laman resminya.</p><h4 data-path-to-node=\"14\"><br></h4><p data-path-to-node=\"15\">Masyarakat dapat memantau perkembangan harga terbaru di setiap daerah melalui situs resmi Pertamina atau melalui fitur di aplikasi MyPertamina. Sebagai informasi tambahan, harga di wilayah lain seperti Sumatera, Kalimantan, dan Papua mungkin memiliki perbedaan karena adanya komponen Pajak Bahan Bakar Kendaraan Bermotor (PBBKB) yang besarannya ditetapkan oleh masing-masing pemerintah daerah.</p><p data-path-to-node=\"16\">Hingga berita ini diturunkan, pemerintah melalui Menteri ESDM belum berencana melakukan pembatasan tambahan untuk pembelian BBM nonsubsidi, meski fluktuasi harga terus dipantau secara ketat setiap bulannya.</p></div><p><br></p>','Foto: Petugas SPBU Pertamina di kawasan Bekasi, Jawa Barat, Senin (23/1/2024).XNN | Xyron News Network JAKARTA – PT Pertamina (Persero) kembali mela',1,'',8,NULL,'published','https://blue.kumparan.com/image/upload/fl_progressive,fl_lossy,c_fill,f_auto,q_auto:best,w_640/v1634025439/01hmr1ppxhwwn57sksy1jt3me0.jpg',138,'2026-04-18 12:43:27'),(34,'Komisi III DPR RI Soroti Urgensi Aturan Turunan KUHP Baru dalam Kunjungan Spesifik ke Sultra','komisi-iii-dpr-ri-soroti-urgensi-aturan-turunan-kuhp-baru-dalam-kunjungan-spesifik-ke-sultra','<h6 data-path-to-node=\"4\"><i><font color=\"#3984c6\">Foto: Anggota Komisi III DPR RI, Benny Kabur Harman, saat memimpin Tim Kunjungan Kerja Spesifik ke Kendari, Kamis (16/4/2026)</font></i></h6><h6 data-path-to-node=\"4\"><i><font color=\"#3984c6\"><br></font></i></h6><p data-path-to-node=\"4\"><font color=\"#ff0000\"><b data-path-to-node=\"4\" data-index-in-node=\"0\">XNN | KENDARI</b>&nbsp;-&nbsp;</font>Komisi III Dewan Perwakilan Rakyat (DPR) RI melakukan evaluasi mendalam terhadap kesiapan aparat penegak hukum di Sulawesi Tenggara (Sultra) terkait implementasi Kitab Undang-Undang Hukum Pidana (KUHP) dan Kitab Undang-Undang Hukum Acara Pidana (KUHAP) yang baru.</p><p data-path-to-node=\"5\">Dalam Kunjungan Kerja Spesifik ke Kendari pada Kamis (16/4/2026), Wakil Ketua Tim Kunjungan, Benny Kabur Harman, menyatakan bahwa meskipun secara prinsip aparat di Sultra telah siap, kendala teknis masih membayangi di lapangan.</p><p data-path-to-node=\"6\">\"Aparat penegak hukum di Sulawesi Tenggara pada prinsipnya sudah siap mengikuti prinsip-prinsip baru dalam KUHP dan KUHAP. Namun, tantangan utamanya adalah belum tersedianya petunjuk teknis pelaksanaan yang memadai,\" ujar Benny.</p><p data-path-to-node=\"7\">Komisi III menyoroti kekosongan sejumlah Peraturan Pemerintah (PP) yang seharusnya menjadi aturan turunan dari kodifikasi hukum pidana baru tersebut. Menurut Benny, tanpa adanya PP yang segera diterbitkan, proses penegakan hukum berisiko mengalami hambatan.</p><p data-path-to-node=\"8\">Selain regulasi teknis, penerapan <i data-path-to-node=\"8\" data-index-in-node=\"34\">the living law</i> atau hukum yang hidup di masyarakat turut menjadi poin krusial. Benny menekankan pentingnya aturan rinci agar konsep tersebut tidak menimbulkan multitafsir dalam praktiknya.</p><p data-path-to-node=\"9\">Dalam agenda tersebut, tim Komisi III berdialog langsung dengan jajaran pimpinan hukum daerah, di antaranya Kapolda Sultra Irjen Pol Didik Agung Widjanarko, Kepala Kejaksaan Tinggi Sultra Abdul Qohar, serta perwakilan BNNP Sultra. Kunjungan ini merupakan bagian dari upaya memastikan reformasi hukum pidana nasional yang mulai berlaku awal 2026 dapat berjalan efektif dan konsisten di seluruh pelosok negeri.</p><p><br></p>','Foto: Anggota Komisi III DPR RI, Benny Kabur Harman, saat memimpin Tim Kunjungan Kerja Spesifik ke Kendari, Kamis (16/4/2026)XNN | KENDARI&nbsp;-&nbsp',8,'',8,NULL,'published','https://kendari.terkini.id/assets/images/2026/04/kendari_fb02eab11b4d316e7a70e84941fd7658-720x405.webp?v=1',117,'2026-04-18 12:57:22'),(35,'Wajah Baru Layanan Air Bersih: Bupati Kolaka Resmikan Kantor Pusat Perumda Tirta Sorume di Kawasan By Pass','wajah-baru-layanan-air-bersih-bupati-kolaka-resmikan-kantor-pusat-perumda-tirta-sorume-di-kawasan-by-pass','<h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#3984c6\">Bupati Kolaka Amri meresmikan kantor baru Perumda Tirta Sorume untuk \r\nmeningkatkan kualitas layanan air bersih, transparansi, dan pemerataan \r\nakses bagi masyarakat/ Dok: Kominfo</font></h6><h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#3984c6\"><br></font></h6><p data-path-to-node=\"3\" align=\"justify\"><font color=\"#ff0000\"><b data-path-to-node=\"3\" data-index-in-node=\"0\">XNN | KOLAKA</b> – </font>Komitmen Pemerintah Kabupaten Kolaka dalam memodernisasi infrastruktur pelayanan publik kembali ditegaskan. Bupati Kolaka, H. Amri, S.STP., M.Si, secara resmi meresmikan gedung kantor baru Perusahaan Umum Daerah (Perumda) Air Minum Tirta Sorume yang terletak strategis di Jalan Mekongga Indah (By Pass), Rabu (15/4/2026).</p><p data-path-to-node=\"4\" align=\"justify\">Gedung yang berdiri megah di kawasan jalur utama tersebut diproyeksikan menjadi pusat kendali (command center) dalam memantau distribusi air bersih di seluruh wilayah Kabupaten Kolaka. Peresmian ini dihadiri oleh jajaran Forkopimda, kepala OPD, serta tokoh masyarakat setempat.</p><p data-path-to-node=\"5\" align=\"justify\"><span data-path-to-node=\"5\" data-index-in-node=\"0\">Bukan Sekadar Bangunan Fisik</span>\r\nDalam pidato sambutannya, Bupati Amri menekankan bahwa keberadaan gedung kantor baru ini jangan hanya dipandang sebagai proyek pembangunan fisik semata. Menurutnya, bangunan ini adalah representasi dari tekad pemerintah daerah untuk memberikan hak dasar masyarakat, yakni akses air bersih yang berkualitas dan terjangkau.</p><p data-path-to-node=\"6\" align=\"justify\">“Gedung ini adalah simbol semangat baru. Lingkungan kerja yang nyaman dan representatif harus menjadi stimulus bagi seluruh jajaran Perumda Tirta Sorume untuk bekerja lebih fokus, kreatif, dan produktif. Tidak ada lagi alasan pelayanan lambat karena kendala administratif atau fasilitas,” tegas Bupati Amri di hadapan jajaran Direksi dan staf Perumda.</p><p data-path-to-node=\"7\" align=\"justify\"><span data-path-to-node=\"7\" data-index-in-node=\"0\">Menuntut Transformasi Pelayanan</span>\r\nLebih lanjut, Bupati juga memberikan catatan kritis terkait standar pelayanan publik. Ia menginstruksikan agar manajemen Perumda segera melakukan transformasi, terutama dalam hal responsivitas terhadap aduan pelanggan. Dengan lokasi kantor yang kini lebih mudah diakses oleh masyarakat, transparansi dan akuntabilitas menjadi hal yang mutlak.</p><p data-path-to-node=\"8\" align=\"justify\">“Seiring dengan diresmikannya gedung ini, saya menuntut adanya peningkatan kinerja yang nyata. Kecepatan dalam menangani kebocoran pipa, transparansi dalam tagihan, hingga keramahan petugas di lapangan harus menjadi budaya baru. Perumda Tirta Sorume harus bertransformasi menjadi lembaga pelayanan publik yang profesional dan modern,” tambahnya.</p><p data-path-to-node=\"9\" align=\"justify\"><span data-path-to-node=\"9\" data-index-in-node=\"0\">Target Pemerataan Akses Air Layak</span>\r\nPembangunan kantor pusat ini juga diharapkan menjadi pemacu dalam mencapai target pemerataan akses air minum layak di seluruh pelosok Kolaka. Bupati Amri berharap koordinasi teknis dapat berjalan lebih solid untuk memperluas jaringan distribusi hingga ke wilayah pemukiman yang selama ini masih mengalami kesulitan akses air bersih.</p><p data-path-to-node=\"10\" align=\"justify\">Acara peresmian tersebut diakhiri dengan penandatanganan prasasti dan pemotongan pita oleh Bupati Amri, didampingi oleh Direktur Utama Perumda Tirta Sorume. Usai peresmian, rombongan melakukan peninjauan ke berbagai ruangan kantor untuk memastikan kesiapan sarana dan prasarana dalam mendukung operasional harian perusahaan pelat merah tersebut.</p><p><br></p>','Bupati Kolaka Amri meresmikan kantor baru Perumda Tirta Sorume untuk \r\nmeningkatkan kualitas layanan air bersih, transparansi, dan pemerataan \r\nak',8,'',8,NULL,'published','https://kendari.terkini.id/assets/images/2026/04/kendari_a5da54154393dcd24d79e3a09a333907-720x405.webp?v=1',100,'2026-04-18 13:17:39'),(36,'Pengabdian di Balik Seragam: Kisah Bripda Ahmad Kabir Mulki, Polisi Hafidz 30 Juz yang Memukau di Arena MTQ Sulsel','pengabdian-di-balik-seragam-kisah-bripda-ahmad-kabir-mulki-polisi-hafidz-30-juz-yang-memukau-di-arena-mtq-sulsel','<h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#6badde\"><i>Foto: Bripda Ahmad Kabir Mulki</i></font></h6><h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#6badde\"><i><br></i></font></h6><p data-path-to-node=\"3\" align=\"justify\"><font color=\"#ff0000\"><b data-path-to-node=\"3\" data-index-in-node=\"0\">XNN | MAROS</b> – </font>Hiruk-pikuk pelaksanaan Musabaqah Tilawatil Qur’an (MTQ) XXXIV tingkat Provinsi Sulawesi Selatan di Kabupaten Maros menyimpan sebuah cerita inspiratif yang melampaui sekadar kompetisi. Di antara ratusan peserta yang hadir, sosok Bripda Ahmad Kabir Mulki menjadi magnet perhatian saat turun di kategori Hifdzil Qur’an 30 Juz, Rabu (15/4/2026).</p><p data-path-to-node=\"4\" align=\"justify\">Bukan sekadar peserta biasa, pemuda yang akrab disapa Mulki ini merupakan anggota Polri aktif yang sehari-hari bertugas di Polres Barru. Mewakili tanah kelahirannya, Kabupaten Bulukumba, Mulki membuktikan bahwa pengabdian kepada negara melalui seragam kepolisian dan pengabdian kepada agama melalui hafalan Al-Qur’an dapat berjalan beriringan tanpa harus saling mengorbankan.</p><p data-path-to-node=\"5\" align=\"justify\"><span data-path-to-node=\"5\" data-index-in-node=\"0\">Akar Spiritual dari Butta Panrita Lopi</span>\r\nLahir dan besar di lingkungan yang religius, bakat spiritual Mulki memang sudah dipupuk sejak dini. Ia merupakan putra dari pasangan tokoh agama terpandang di Bulukumba; ayahnya, H. Mustamin Gau, adalah Imam Besar Masjid Islamic Centre Datu Tiro, sementara ibunya, Hj. Nuraeni, merupakan penyuluh agama Islam di KUA Ujung Bulu.</p><p data-path-to-node=\"6\" align=\"justify\">Perjalanannya sebagai penghafal Al-Qur\'an dimulai sejak bangku Madrasah Tsanawiyah dan semakin matang saat menimba ilmu di Pondok Pesantren Babul Khaer, Bulukumba. Kesalehan dan disiplinnya kemudian mengantarkan Mulki menembus korps kepolisian melalui jalur prestasi Tahfidz sebuah bukti nyata bahwa Polri memberikan ruang luas bagi pemuda-pemuda religius untuk berbakti.</p><p data-path-to-node=\"7\" align=\"justify\"><span data-path-to-node=\"7\" data-index-in-node=\"0\">Menjaga Hafalan di Tengah Tugas Negara</span>\r\nMenjadi seorang polisi tentu menuntut kesiapan fisik dan mental yang ekstra. Namun, di tengah padatnya jadwal piket dan tugas lapangan di Polres Barru, Mulki tidak pernah membiarkan hafalannya memudar. Ia memiliki disiplin diri yang ketat untuk melakukan <i data-path-to-node=\"7\" data-index-in-node=\"294\">murajaah</i> atau pengulangan hafalan.</p><p data-path-to-node=\"8\" align=\"justify\">\"Kuncinya adalah manajemen waktu. Saya selalu menyempatkan murajaah setiap selesai waktu sholat. Dalam sehari, saya targetkan bisa mengulang sampai 5 juz,\" ungkap Mulki dengan rendah hati.</p><p data-path-to-node=\"9\" align=\"justify\">Bahkan saat tugas sedang menumpuk, ia tetap memaksakan diri untuk membaca setidaknya satu atau setengah juz per hari. Baginya, Al-Qur\'an bukan sekadar hafalan, melainkan penjaga ketenangan batin saat ia menjalankan tugas-tugas kemanusiaan di kepolisian.</p><p data-path-to-node=\"10\" align=\"justify\"><span data-path-to-node=\"10\" data-index-in-node=\"0\">Inspirasi bagi Generasi Muda</span>\r\nKehadiran Bripda Mulki di panggung MTQ XXXIV Sulawesi Selatan bukan sekadar mengejar piala. Ia membawa misi besar untuk menunjukkan wajah Polri yang humanis dan religius, sekaligus menjadi pelecut semangat bagi pemuda di Sulawesi Selatan, khususnya di Bulukumba.</p><p data-path-to-node=\"11\" align=\"justify\">\"Saya ingin menunjukkan bahwa Al-Qur\'an itu memudahkan jalan hidup. Apapun profesi kita, jika kita menjadikannya pedoman, insya Allah semua urusan akan dilancarkan,\" tambahnya.</p><p data-path-to-node=\"12\" align=\"justify\">Kisah Mulki menjadi pengingat bagi kita semua bahwa kesibukan duniawi bukan alasan untuk meninggalkan nilai-nilai spiritual. Di balik seragam cokelatnya, terdapat hati yang terus melantunkan ayat-ayat suci, menjaga negeri sekaligus menjaga wahyu Ilahi.</p><p><br></p>','Foto: Bripda Ahmad Kabir MulkiXNN | MAROS – Hiruk-pikuk pelaksanaan Musabaqah Tilawatil Qur’an (MTQ) XXXIV tingkat Provinsi Sulawesi Selatan di Ka',1,'',8,NULL,'published','https://sulsel.kemenag.go.id/assets_web/posts/post_ykCD8yxSQP.jpg',139,'2026-04-18 15:58:09'),(37,'Wajah Baru Organisasi Mahasiswa FKIP USN Kolaka Resmi Dilantik','wajah-baru-organisasi-mahasiswa-fkip-usn-kolaka-resmi-dilantik','<h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#3984c6\" style=\"font-weight: normal;\">Foto: Pelantikan ketua ormawa lingkup FKIP Senin, 20 April 2026 (aril)</font></h6><h6 data-path-to-node=\"3\" align=\"justify\"><font color=\"#3984c6\" style=\"font-weight: normal;\"><br></font></h6><p data-path-to-node=\"3\" align=\"justify\"><font color=\"#ff0000\"><b>XNN | KOLAKA -</b></font> Aula Kampus Universitas Sembilanbelas November (USN) Kolaka menjadi saksi bisu regenerasi kepemimpinan mahasiswa. Tepat pada hari ini, <span data-path-to-node=\"3\" data-index-in-node=\"144\"><font color=\"#ff0000\">Senin, 20 April 2026</font></span>, jajaran Ketua Organisasi Mahasiswa (Ormawa) di lingkup Fakultas Keguruan dan Ilmu Pendidikan (FKIP) resmi dilantik untuk masa bakti 2026-2027.</p><p data-path-to-node=\"4\" align=\"justify\">Acara pelantikan yang berlangsung khidmat ini dihadiri oleh Dekan FKIP Dr. Syarifuddin Tundreng, S.S., M.Pd. Beserta jajaran Wakil Dekan 3, para Koordinator Program Studi, serta ketua lembaga kemahasiswaan se-FKIP. Prosesi pengambilan sumpah jabatan dipimpin langsung oleh pihak birokrasi fakultas sebagai simbol penyerahan amanah dan tanggung jawab.</p><p data-path-to-node=\"6\" align=\"justify\">Pelantikan ini mencakup seluruh elemen lembaga di FKIP, mulai dari<b>&nbsp;</b><span data-path-to-node=\"7,0,0\" data-index-in-node=\"0\">BEM FKIP</span> (Badan Eksekutif Mahasiswa)&nbsp;<span data-path-to-node=\"7,1,0\" data-index-in-node=\"0\">DPM FKIP</span> (Dewan Perwakilan Mahasiswa)&nbsp;<span data-path-to-node=\"7,2,0\" data-index-in-node=\"0\">HMPS</span> (Himpunan Mahasiswa Program Studi) di seluruh prodi keguruan.</p><p data-path-to-node=\"8\" align=\"justify\">Dalam sambutannya, Dekan FKIP menekankan pentingnya sinergi antara prestasi akademik dan organisasi. Beliau berharap para pemimpin baru ini mampu membawa inovasi yang mendukung akreditasi fakultas serta menjadi jembatan aspirasi yang solutif bagi seluruh mahasiswa FKIP.</p><p data-path-to-node=\"10\" align=\"justify\">Ketua BEM FKIP terpilih yang baru saja dilantik menyampaikan gagasan kepada xyron news Network, komitmen untuk membawa ormawa FKIP menjadi wadah yang lebih inklusif dan kolaboratif.</p><div align=\"justify\"><blockquote data-path-to-node=\"11\"><p data-path-to-node=\"11,0\">\"Hari ini bukan sekadar seremonial, tapi titik awal perjuangan. Kami berkomitmen untuk menjadikan FKIP USN Kolaka sebagai kiblat pergerakan mahasiswa yang cerdas, berintegritas, dan menjunjung tinggi nilai-nilai kependidikan,\" ujar ketua BEM FKIP Mustahang Kepada tim XNN.</p></blockquote><p data-path-to-node=\"12\">Dengan dilantiknya kepengurusan baru ini, diharapkan geliat kegiatan kemahasiswaan di lingkungan Universitas Sembilanbelas November Kolaka semakin produktif, terutama dalam menyongsong tantangan dunia pendidikan di masa depan.</p></div><p><br></p>','Foto: Pelantikan ketua ormawa lingkup FKIP Senin, 20 April 2026 (aril)XNN | KOLAKA - Aula Kampus Universitas Sembilanbelas November (USN) Kolaka menja',8,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_69e5f989811b1.jpeg',161,'2026-04-20 17:01:45'),(39,'Peringati Hari Bumi Internasional, HMPS Pendidikan Bahasa Inggris Gelar ‘Earth Clean Up Day’ di Kolaka','peringati-hari-bumi-internasional-hmps-pendidikan-bahasa-inggris-gelar-earth-clean-up-day-di-kolaka','<h6 style=\"text-align: left;\"><font color=\"#3984c6\">Foto: HMPS B.Inggris menyelenggarakan kegiatan Earth Clean Up Day (Rabu 22 April 2026)</font></h6><h6 style=\"text-align: left;\"><font color=\"#3984c6\"><br></font></h6><p style=\"text-align: justify; \"><b><font color=\"#ce0000\">XNN | KOLAKA -</font></b> Dalam rangka memperingati Hari Bumi Internasional, kami dari Himpunan Mahasiswa Program Studi Pendidikan Bahasa Inggris (HMPS) menyelenggarakan kegiatan bertema <b>“Earth Clean Up Day”</b> sebagai bentuk kepedulian nyata terhadap lingkungan, khususnya wilayah pesisir.</p><p style=\"text-align: justify; \">Kegiatan ini dilaksanakan pada hari <b>Rabu, 22 April 2026,</b> di dua lokasi, yaitu Pantai Mandra dan Pantai Cocoa Kolaka. Pemilihan lokasi ini didasarkan pada pentingnya menjaga kebersihan kawasan pantai sebagai ekosistem yang memiliki peran besar dalam menjaga keseimbangan alam serta sebagai ruang publik yang sering dimanfaatkan.</p><p style=\"text-align: justify;\"><b>Melalui Earth Clean Up Day</b>, seluruh rangkaian kegiatan sepenuhnya melibatkan seluruh mahasiswa pengurus HMPS Pendidikan Bahasa Inggris sebagai bentuk kontribusi nyata generasi muda dalam menjaga lingkungan. Kegiatan ini bukan sekadar aksi bersih pantai, tetapi juga menjadi sarana untuk menumbuhkan rasa tanggung jawab, kepedulian, serta kesadaran akan pentingnya menjaga kelestarian bumi.</p><p style=\"text-align: justify;\">Sebagai organisasi yang bergerak di bidang pendidikan, HMPS Pendidikan Bahasa Inggris berkomitmen untuk tidak hanya mengembangkan kemampuan akademik, tetapi juga membentuk karakter mahasiswa yang peduli, aktif, dan berintegritas dalam menghadapi isu-isu lingkungan.</p><p style=\"text-align: justify;\">ketua umum HMPS Pendidikan Bahasa inggris, Uswatun Hasanah mengatakan \"berharap kegiatan ini dapat menjadi langkah kecil yang memberikan dampak besar, serta menjadi contoh bahwa mahasiswa mampu menjadi pelopor dalam menjaga lingkungan. Karena bumi yang bersih dan sehat adalah tanggung jawab kita bersama\"Ujar Uswatun Hasanah kepada XNN.</p>','XNN | KOLAKA - Dalam rangka memperingati Hari Bumi Internasional, kami dari Himpunan Mahasiswa Program Studi Pendidikan Bahasa Inggris (HMPS) menyelen',8,'bahasa, inggris, hmps, kolaka, usn, xnn',8,8,'published','https://www.xyronnews.com/uploads/posts/post_69e8f74b1aadd.jpeg',306,'2026-04-22 23:28:59'),(42,'HMJ PENDIDIKAN SEJARAH PERIODE 2026/2027 RESMI DI LANTIK, SIAP SINERGIKAN KOLABORASI DAN INOVASI PROGRAM KERJA','hmj-pendidikan-sejarah-periode-2026-2027-resmi-di-lantik-siap-sinergikan-kolaborasi-dan-inovasi-program-kerja','<h6><font color=\"#6badde\">Foto: Pelantikan&nbsp;<span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Himpunan Mahasiswa Jurusan (HMJ)</span><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">&nbsp;&nbsp;</span></font></h6><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><br></span><font color=\"#ff0000\" style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><b>XNN | KENDARI - </b></font><span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Himpunan Mahasiswa Jurusan (HMJ) Pendidkan Sejarah Fakultas keguruan dan ilmu pendidikan &nbsp;Universitas Halu Oleo &nbsp;resmi melantik pengurus baru periode 2026-2027. Acara pelantikan berlangsung khidmat di Aula FKIP UHO pada Hari,Rabu, 22 April 2026, dengan mengusung tema \" *Mewujudkan organisasi yang meneguhkan gagasan di tengah persaingan\"*&nbsp;</span></p><p style=\"text-align: justify;\">Prosesi pelantikan dipimpin langsung oleh Ketua Jurusan Pendidikan Sejarah, Prof.Dr. Hj. Darnawati, S,pd.,M,pd yang ditandai dengan pembacaan sumpah jabatan dan penandatanganan berita acara serah terima jabatan dari pengurus lama kepada pengurus baru.</p><p style=\"text-align: justify;\">Dalam sambutannya, &nbsp;Prof. Dr. Hj. Darnawati. S.Pd., M.Pd selaku &nbsp;ketua jurusan Pendidikan Sejarah menyampaikan pesan agar pengurus baru dapat membawa perubahan positif. Sejarah bukan hanya tentang masa lalu, tapi bagaimana kita merancang masa depan. Saya berharap HMJ Pendidikan Sejarah menjadi wadah kolaborasi Antar akademis dan sosial yang aktif, bukan sekadar organisasi formalitas\"<span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">ujarnya.</span></p><p style=\"text-align: justify;\">LA UMA KETUA &nbsp;HMJ Terpilih, yang baru dilantik, menyatakan komitmenya kegiatan ini menjadi pengingat bagi kita semua bahwa sebuah organisasi tidak hanya dituntut untuk hadir dan berjalan, tetapi juga harus mampu berdiri teguh dengan gagasan, nilai, dan visi yang jelas di tengah dinamika serta tantangan zaman yang semakin kompetitif.</p><p style=\"text-align: justify;\">Dan SAZKYA PRATIWI SAKIR WAKIL KETUA HMJ Srikandi Sejarah yang Siap Menggerakkan Perubahan</p><p style=\"text-align: justify;\">Dalam ranah pendidikan sejarah, di mana masa lalu dipelajari untuk merancang masa depan, tampil seorang perempuan muda yang merepresentasikan keberanian, intelektualitas, dan kesiapan untuk memimpin. Sazkya Pratiwi Sakir, sosok yang kini mengemban amanah sebagai Wakil Ketua Umum Himpunan Mahasiswa Jurusan (HMJ) Pendidikan Sejarah, bukanlah nama baru yang asing dengan komitmen dan dedikasi.</p><p style=\"text-align: justify;\">Sazkya tampil sebagai sosok perempuan yang tangguh dan visioner. Ia mematahkan stereotip bahwa kepemimpinan organisasi mahasiswa hanya milik kaum laki-laki. Baginya, menjadi Wakil Ketua Umum bukan sekadar posisi struktural, melainkan ruang pengabdian yang ia ambil dengan kesadaran penuh dan mentalitas \"Siap\".</p><p style=\"text-align: justify;\">Pelantikan ini bukan sekadar seremonial pergantian kepengurusan, melainkan sebuah awal dari tanggung jawab besar untuk menjaga kepercayaan, memperkuat solidaritas, serta menghadirkan karya nyata yang bermanfaat bagi organisasi dan lingkungan sekitar.</p><p style=\"text-align: justify;\">Terakhir kami ingin mengucapkan kepada seluruh pihak senior Alumni yang juga telah membantu dan mendukung hingga pengurus himpunan mahasiswa jurusan (HMJ) pendidikan sejarah baru &nbsp;di lantik.</p><p style=\"text-align: justify;\">Harapannya Himpunan mahasiswa jurusan (HMJ) Pendidikan Sejarah dimasa sekarang akan jauh lebih baik lagi dan Merani membuat inovasi- inovasi baru yg dapat membawa pendidikan sejarah ke Arah lebih baik. Tutup La Uma</p>','Foto: Pelantikan&nbsp;Himpunan Mahasiswa Jurusan (HMJ)&nbsp;&nbsp;XNN | KENDARI - Himpunan Mahasiswa Jurusan (HMJ) Pendidkan Sejarah Fakultas keguruan',8,'HMJ, Pelantikan, kendari, XNN',8,8,'published','https://www.xyronnews.com/uploads/posts/post_69eb8a0b86ab9.jpeg',385,'2026-04-24 22:42:25'),(43,'Hmps PJ Melakukan aksi bersih di pinggir pantai Kolaka sebagai ajan peringati hari bumi','hmps-pj-melakukan-aksi-bersih-di-pinggir-pantai-kolaka-sebagai-ajan-peringati-hari-bumi','<h6><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#6badde\">Foto: HMPS PJ USN Kolaka, Dalam Rangka Memperingati Hari Bumi</font></span></h6><h6><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#6badde\"><br></font></span></h6><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#ce0000\"><b>XNN | KOLAKA -</b>&nbsp;</font>26/04/2026<font color=\"#3984c6\">&nbsp;</font>Dalam rangka memperingati Hari Bumi, Himpunan Mahasiswa Program Studi Pendidikan Jasmani (HMPS PJ) Universitas Sembilanbelas November Kolaka menggelar aksi nyata berupa kegiatan bersih-bersih di kawasan pinggiran Pantai Kolaka. Kegiatan ini dilaksanakan sebagai bentuk kepedulian mahasiswa terhadap lingkungan, khususnya kebersihan wilayah pesisir.</span></p><p style=\"text-align: justify;\">Aksi tersebut melibatkan sejumlah mahasiswa HMPS PJ USN Kolaka yang turun langsung ke lokasi untuk membersihkan sampah di sepanjang area pantai. Sampah yang ditemukan didominasi oleh plastik, botol bekas, serta limbah rumah tangga yang terbawa arus laut maupun ditinggalkan oleh pengunjung.</p><p style=\"text-align: justify;\">Ketua HMPS PJ USN Kolaka, Santi, menyampaikan bahwa kegiatan ini merupakan wujud nyata kepedulian mahasiswa terhadap lingkungan sekaligus upaya mengajak masyarakat untuk lebih sadar akan pentingnya menjaga kebersihan.</p><p style=\"text-align: justify;\">“Kegiatan ini bukan hanya sekadar memperingati Hari Bumi, tetapi juga sebagai bentuk aksi nyata kami dalam menjaga lingkungan. Kami berharap masyarakat juga ikut berpartisipasi dalam menjaga kebersihan pantai,” ujar Ketua HMPS PJ, Santi kepada XNN</p><p style=\"text-align: justify;\">Ia juga menambahkan bahwa kegiatan seperti ini diharapkan dapat terus dilakukan secara berkelanjutan dan melibatkan lebih banyak pihak di masa mendatang.</p><p style=\"text-align: justify;\">Selain sebagai aksi bersih lingkungan, kegiatan ini juga menjadi sarana edukasi bagi masyarakat sekitar mengenai pentingnya menjaga kelestarian alam, khususnya di wilayah pesisir. Sampah plastik yang menumpuk dapat berdampak buruk bagi ekosistem laut dan mengurangi keindahan pantai sebagai salah satu potensi wisata daerah.</p><p style=\"text-align: justify;\">Melalui momentum Hari Bumi, HMPS PJ USN Kolaka ingin menegaskan komitmennya dalam mendukung gerakan pelestarian lingkungan. Aksi ini diharapkan dapat menjadi inspirasi bagi masyarakat luas agar lebih peduli terhadap kebersihan dan kelestarian alam</p>','Foto: HMPS PJ USN Kolaka, Dalam Rangka Memperingati Hari BumiXNN | KOLAKA -&nbsp;26/04/2026&nbsp;Dalam rangka memperingati Hari Bumi, Himpunan Mahasis',8,'Hmps pj, penjas, usn, kolaka, hari bumi,',8,8,'published','https://www.xyronnews.com/uploads/posts/post_69ede7f69e674.jpeg',169,'2026-04-26 17:24:54'),(44,'LIRA Kolaka Dorong Transparansi PPM dan PPJP,Perkuat Peran Forum TJSL dalam Pengawasan CSR','lira-kolaka-dorong-transparansi-ppm-dan-ppjp-perkuat-peran-forum-tjsl-dalam-pengawasan-csr','<p><br></p><p style=\"text-align: justify; \"><b><font color=\"#ff0000\">XNN | KOLAKA - </font></b>Minggu,26,April,2026 — Ketua Lumbung Informasi Rakyat (LIRA) DPD Kolaka, Ilham Lukman, menegaskan pentingnya optimalisasi dan transparansi dalam pelaksanaan Program Pengembangan dan Pemberdayaan Masyarakat (PPM) serta Program Pengembangan dan Peningkatan Jasa Publik (PPJP) oleh perusahaan, khususnya sektor pertambangan di Kabupaten Kolaka.</p><p style=\"text-align: justify; \">Menurut Ilham Lukman, kedua program tersebut merupakan bentuk tanggung jawab sosial perusahaan yang seharusnya memberikan dampak nyata dan berkelanjutan bagi masyarakat sekitar wilayah operasional tambang.</p><p style=\"text-align: justify; \">“PPM dan PPJP bukan sekadar formalitas atau kewajiban administratif, tetapi harus menjadi instrumen strategis untuk meningkatkan kesejahteraan masyarakat secara langsung, baik dari sisi ekonomi, pendidikan, kesehatan, maupun infrastruktur sosial,” ujarnya.</p><p style=\"text-align: justify; \">Ia menambahkan bahwa selama ini masih terdapat sejumlah tantangan dalam implementasi program, di antaranya:</p><p style=\"text-align: justify; \">Belum meratanya distribusi program kepada masyarakat terdampak,Kurangnya transparansi dalam perencanaan dan pelaksanaan, Minimnya pelibatan masyarakat dalam proses pengambilan keputusan</p><p style=\"text-align: justify; \">Selain itu, LIRA Kolaka menyoroti pentingnya penguatan implementasi Peraturan Daerah Kabupaten Kolaka Nomor 15 Tahun 2014 tentang Tanggung Jawab Sosial dan Lingkungan Perusahaan, yang menjadi dasar hukum pelaksanaan CSR di daerah.</p><p style=\"text-align: justify; \">Perda tersebut telah mengamanatkan pembentukan wadah koordinasi berupa Forum Tanggung Jawab Sosial dan Lingkungan Perusahaan (Forum TJSL/CSR) sebagai sarana:</p><p style=\"text-align: justify; \">Sinkronisasi program CSR dengan prioritas pembangunan daerah, Koordinasi antara perusahaan, pemerintah daerah, dan masyarakat, Pengawasan pelaksanaan program CSR agar tepat sasaran</p><p style=\"text-align: justify; \">Sehubungan dengan hal tersebut, DPD LIRA Kolaka juga mendorong penguatan peran Forum TJSL Kabupaten Kolaka sebagai lembaga resmi yang dibentuk untuk mengawal dan mengoordinasikan pelaksanaan CSR di daerah.</p><p style=\"text-align: justify; \">Menurut Ilham Lukman, Forum TJSL harus berfungsi secara maksimal sebagai:</p><p style=\"text-align: justify; \"><br></p><p style=\"text-align: justify; \">- Wadah komunikasi terbuka antara perusahaan dan masyarakat</p><p style=\"text-align: justify; \">- Fasilitator penyusunan program CSR yang tepat sasaran</p><p style=\"text-align: justify; \">- Instrumen pengawasan sosial terhadap pelaksanaan CSR</p><p style=\"text-align: justify; \"><br></p><p style=\"text-align: justify; \">“Forum TJSL Kabupaten Kolaka harus benar-benar diaktifkan dan diperkuat perannya. Jangan hanya ada secara administratif, tetapi harus hadir dan dirasakan manfaatnya oleh masyarakat,” tegasnya.</p><p style=\"text-align: justify; \"><br></p><p style=\"text-align: justify; \">Ia juga menekankan bahwa Forum TJSL bukan lembaga yang berwenang menarik atau mengelola dana CSR dari perusahaan, melainkan berfungsi sebagai:</p><p style=\"text-align: justify; \">- Koordinator program</p><p style=\"text-align: justify; \">- Mediator antara kepentingan masyarakat dan perusahaan</p><p style=\"text-align: justify; \">- Pengawal transparansi dan akuntabilitas</p><p style=\"text-align: justify; \">“Jangan sampai terjadi penyimpangan pemahaman seolah-olah CSR harus disetor ke lembaga tertentu. Itu keliru. CSR tetap menjadi program perusahaan yang harus langsung dirasakan masyarakat,” tambahnya.</p><p style=\"text-align: justify; \">LIRA Kolaka mendorong agar perusahaan lebih terbuka dalam menyampaikan informasi terkait alokasi dan realisasi anggaran PPM dan PPJP, sehingga publik dapat melakukan pengawasan secara partisipatif.</p><p style=\"text-align: justify; \">Selain itu, penting adanya forum komunikasi yang aktif dan inklusif melalui Forum TJSL, sehingga masyarakat tidak hanya menjadi objek, tetapi juga subjek dalam pembangunan melalui program PPM dan PPJP.</p><p style=\"text-align: justify; \">DPD LIRA Kolaka berkomitmen untuk terus mengawal implementasi Perda CSR, memperkuat peran Forum TJSL, serta memastikan pelaksanaan program PPM dan PPJP berjalan sesuai prinsip akuntabilitas, transparansi, dan berorientasi pada kesejahteraan masyarakat Kabupaten Kolaka.</p>','XNN | KOLAKA - Minggu,26,April,2026 — Ketua Lumbung Informasi Rakyat (LIRA) DPD Kolaka, Ilham Lukman, menegaskan pentingnya optimalisasi dan transpa',8,'Lira, Kolaka, csr',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_69edececd641b.jpg',177,'2026-04-26 17:46:04'),(45,'Asrama Berdiri, Fungsi Mati: Mahasiswa Bombana Menagih Keseriusan Pemda','asrama-berdiri-fungsi-mati-mahasiswa-bombana-menagih-keseriusan-pemda','<h6 style=\"text-align: justify; \"><font color=\"#3984c6\" style=\"\">Foto: Ketua Umum Himpunan mahasiswa bombana kolaka</font></h6><h6 style=\"text-align: justify; \"><font color=\"#3984c6\" style=\"\"><br></font></h6><h6 style=\"text-align: justify; \"><font color=\"#3984c6\" style=\"\"> </font></h6><p style=\"text-align: justify; \"><font color=\"#f7c6ce\" style=\"\">XNN | KOLAKA -&nbsp;</font>Kami dari Himpunan Mahasiswa Bombana Kolaka (HIPMAB Kolaka) menyampaikan kritik tegas kepada Pemerintah Daerah Kabupaten Bombana atas kondisi Asrama Mahasiswa Bombana di Kolaka yang sejak tahun 2023 hingga 2026 belum menunjukkan adanya pembangunan lanjutan maupun pembenahan yang berarti. Bahkan lebih ironis, pada anggaran tahun 2025 tidak terdapat alokasi pembangunan tambahan untuk asrama tersebut.</p><p style=\"text-align: justify; \">Asrama ini belum pernah benar-benar difungsikan sebagai tempat tinggal mahasiswa. Bangunannya ada, tetapi kelayakan, keamanan, dan fasilitas dasarnya belum terpenuhi. Selama bertahun-tahun, asrama ini dibiarkan berdiri tanpa arah, tanpa perhatian lanjutan, dan tanpa kepastian kapan benar-benar bisa dimanfaatkan oleh mahasiswa Bombana.</p><p style=\"text-align: justify; \">Persoalan ini bukan sekadar bangunan yang belum ditempati. Ini adalah cerminan lemahnya komitmen pemerintah dalam memastikan fasilitas daerah benar-benar hidup dan bermanfaat. Pembangunan yang berhenti pada fisik tanpa fungsi adalah bentuk pembangunan yang setengah hati—bahkan cenderung simbolik.</p><p style=\"text-align: justify; \">Kami tidak ingin mahasiswa terus diberi janji, lalu dipaksa menunggu tanpa kepastian. Jika jalan belum diperbaiki, fasilitas belum memadai, listrik belum aman, air bersih belum jelas, dan pagar belum dibangun, maka pertanyaannya sederhana: bagaimana mungkin asrama ini disebut layak huni?</p><p style=\"text-align: justify; \">Kondisi saat ini sangat memprihatinkan. Kabel listrik terputus akibat kebakaran hutan, sumur bor tidak jelas pengamanan dan pemanfaatannya, serta belum adanya pagar membuat lokasi asrama rawan terhadap gangguan keamanan, potensi pencurian, dan ancaman binatang buas. Ditambah lagi lokasi asrama yang jauh dari pemukiman warga semakin memperbesar risiko bagi mahasiswa.</p><p style=\"text-align: justify; \">HIPMAB Kolaka menilai bahwa pembiaran ini adalah bentuk kelalaian terhadap kebutuhan dasar mahasiswa. Pemerintah tidak boleh hanya hadir dalam seremoni, tetapi absen ketika mahasiswa menuntut fungsi, keselamatan, dan kelayakan hidup.</p><p style=\"text-align: justify; \">Maka, kami mendesak Pemerintah Daerah Kabupaten Bombana untuk segera merealisasikan perbaikan akses jalan menuju asrama, melakukan pembenahan fasilitas asrama secara menyeluruh, memperbaiki instalasi listrik, memastikan ketersediaan air bersih melalui sumur bor, serta membangun pagar pengaman demi menjamin keamanan mahasiswa.</p><p style=\"text-align: justify; \">Kami tegaskan: asrama yang berdiri tanpa fungsi bukan bukti keberhasilan, melainkan bukti bahwa tanggung jawab belum dituntaskan.</p><p style=\"text-align: justify; \">Mahasiswa Bombana tidak membutuhkan simbol kosong. Kami membutuhkan bukti, keberpihakan, dan tindakan nyata.</p>','Foto: Ketua Umum Himpunan mahasiswa bombana kolaka XNN | KOLAKA - Kami dari Himpunan Mahasiswa Bombana Kolaka (HIPMAB Kolaka) menyampaikan kritik tega',8,'Hipmab, kolaka, asrama',8,8,'published','https://www.xyronnews.com/uploads/posts/post_69ef6af6dec8c.png',168,'2026-04-27 21:05:08'),(46,'PB HMI Mendesak Kementerian ESDM Mencabut IUP PT. TSHI','pb-hmi-mendesak-kementerian-esdm-mencabut-iup-pt-tshi','<h6 style=\"text-align: justify; \"><font color=\"#3984c6\">Foto:&nbsp;<span style=\"text-align: justify;\">Bidang Energi dan Sumber Daya Mineral (ESDM) PB HMI (Munawir)</span><span style=\"text-align: justify;\">&nbsp;</span></font></h6><h6><font color=\"#3984c6\"><span style=\"text-align: justify;\"><br></span></font></h6><p style=\"text-align: justify;\"><font color=\"#ff0000\">XNN | JAKARTA -</font> Bidang Energi dan Sumber Daya Mineral (ESDM) PB HMI (Munawir) kembali menyoroti kasus yang menimpa salah satu perusahaan tambang nikel yang beroperasi di Kecamatan Pomalaa, Kabupaten Kolaka, Sulawesi Tenggara, yakni PT Toshida Indonesia (PT TSHI), yang diduga terlibat dalam kasus suap yang turut menyeret nama Ketua Ombudsman RI.</p><p style=\"text-align: justify;\">Penetapan tersangka terhadap Hery Susanto oleh Kejaksaan Agung Republik Indonesia (Kejagung RI) disebut menjadi buah dari upaya PT TSHI dalam mengatur sengketa perhitungan Pendapatan Negara Bukan Pajak (PNBP) dengan hasil perhitungan yang dilakukan oleh Kementerian Kehutanan.</p><p style=\"text-align: justify;\">PB HMI menilai langkah yang ditempuh PT TSHI merupakan bentuk jalan pintas yang mencederai proses penegakan hukum. Alih-alih mengedepankan kepatutan hukum, perusahaan tersebut diduga berupaya menghindari beban pembayaran besar dengan melibatkan Ombudsman RI untuk mengoreksi kebijakan Kementerian Kehutanan.</p><p style=\"text-align: justify;\">Direktur Penyidikan Jampidsus Kejagung, menjelaskan bahwa PT Toshida Indonesia diduga berkomplot dengan Hery Susanto agar Ombudsman mengeluarkan surat yang memerintahkan PT TSHI melakukan penghitungan ulang terkait beban yang harus dibayar.</p><p style=\"text-align: justify;\">“Bersama-sama dengan Saudara HS untuk mengatur, sehingga surat atau kebijakan yang dilakukan oleh Kemenhut itu dikoreksi oleh Ombudsman, dengan perintah agar PT TSHI melakukan penghitungan sendiri terkait beban yang harus dibayar,” ungkap Syarief, Senin (20/4/2026).</p><p style=\"text-align: justify;\">Kasus dugaan suap senilai Rp1,5 miliar sebagai dana pelicin ini berkaitan dengan carut-marut tata kelola niaga pertambangan nikel dalam kurun waktu 2013 hingga 2025. Dana tersebut diduga berasal dari Direktur PT TSHI kepada Hery Susanto sebagai imbalan atas kemudahan pengaturan tersebut.</p><p style=\"text-align: justify;\">“Sebagai imbalan dalam menjalankan permintaan PT TSHI, tersangka menerima sejumlah uang dari Saudara LKM yang diduga Direktur PT TSHI. Kurang lebih yang sudah diserahkan dari satu orang ini adalah sejumlah satu setengah miliar rupiah atau Rp1,5 miliar,” beber Syarief.</p><p style=\"text-align: justify;\">Selain itu, penertiban yang dilakukan oleh Satuan Tugas Penertiban Kawasan Hutan (Satgas PKH) juga memberikan sanksi administratif berupa denda kepada PT TSHI sebesar Rp1,2 triliun atas aktivitas pertambangan di dalam kawasan hutan di Kecamatan Pomalaa, Kabupaten Kolaka, Sulawesi Tenggara, tanpa izin resmi.</p><p style=\"text-align: justify;\">Denda tersebut dikenakan atas aktivitas pembukaan kawasan hutan seluas 124,52 hektare. Tim Satgas PKH juga telah melakukan penyegelan terhadap wilayah Izin Usaha Pertambangan (IUP) milik PT TSHI dengan memasang plang peringatan di lokasi kegiatan tambang.</p><p style=\"text-align: justify;\">Berdasarkan Undang-Undang Nomor 41 Tahun 1999 tentang Kehutanan dan Peraturan Pemerintah Nomor 23 Tahun 2021 tentang Penyelenggaraan Kehutanan, perusahaan yang melakukan aktivitas pertambangan di kawasan hutan tanpa izin resmi dapat dikenakan sanksi administratif maupun pidana.</p><p style=\"text-align: justify;\">Munawir, Sekretaris Bidang ESDM PB HMI menegaskan dukungannya terhadap langkah Satgas PKH dalam melakukan pengawasan dan penindakan terhadap aktivitas pertambangan ilegal di kawasan hutan, khususnya di Sulawesi Tenggara.</p><p style=\"text-align: justify;\">Mereka juga mendesak Pemerintah Republik Indonesia, khususnya Kementerian ESDM RI, untuk segera melakukan evaluasi menyeluruh dan mencabut Izin Usaha Pertambangan (IUP) PT Toshida Indonesia sebagai efek jera atas pelanggaran hukum yang telah ditimbulkan.</p><p style=\"text-align: justify; \">“Pencabutan IUP PT TSHI merupakan langkah konkret untuk memberikan sanksi tegas serta memastikan tercapainya prinsip Good Mining Practice di sektor pertambangan nasional,” tegas Bidang ESDM PB HMI</p>','Foto:&nbsp;Bidang Energi dan Sumber Daya Mineral (ESDM) PB HMI (Munawir)&nbsp;XNN | JAKARTA - Bidang Energi dan Sumber Daya Mineral (ESDM) PB HMI (Mun',1,'ESDM, PB, HMI, PT, TSHI, PNBP, Kejahgung RI, Ombudsman',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a06a6c325530.jpeg',92,'2026-05-15 11:53:23'),(47,'Dipicu Pesan Instagram, Remaja di Surabaya Jadi Korban Pengeroyokan di Kawasan Wiyung','dipicu-pesan-instagram-remaja-di-surabaya-jadi-korban-pengeroyokan-di-kawasan-wiyung','<h6><font style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\" color=\"#6badde\">Foto: lokasi TKP pengeroyokan inisial AB </font></h6><div><br></div><div><font color=\"#ff0000\">XNN | SURABAYA </font>– Kasus kekerasan jalanan kembali menimpa kalangan remaja di Surabaya. Seorang remaja berinisial AB menjadi korban pengeroyokan oleh sekelompok pemuda di kawasan Mayjen Jonosewojo, dekat McD Graha Family, Wiyung, Surabaya. Aksi kekerasan ini diduga kuat dipicu oleh persoalan asmara dan provokasi melalui media sosial Instagram.</div><div><br></div><div>Akibat insiden tersebut, korban mengalami sejumlah luka fisik serta trauma psikis yang cukup berat. Tak tinggal diam, pihak AB telah resmi melaporkan kasus tindak pidana pengeroyokan ini ke Polrestabes Surabaya dan telah menjalani visum medis untuk keperluan penyelidikan.</div><div><br></div><div>Kronologi Kejadian Bermula dari Pesan DM,&nbsp;<span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Berdasarkan dokumen kronologi resmi dan informasi yang dihimpun, peristiwa ini bermula saat AB menerima pesan melalui Direct Message (DM) Instagram dari seorang perempuan berinisial NS. Dalam pesan tersebut, NS mengabarkan secara informal bahwa ada pihak lain yang menantang AB untuk berkelahi dengan kalimat, \"ko ada sg ngajak berantem HAHAHA\".</span></div><div><br></div><div>Awalnya, korban tidak menganggap serius pesan tersebut. AB membalasnya dengan santai, \"siapa HAHAHA\", lantaran mengira hal itu hanyalah gurauan belaka dan dirinya sama sekali tidak berniat mencari musuh ataupun memicu keributan.</div><div><br></div><div>Namun situasi berubah menjadi provokatif. Korban terus-menerus mendapatkan sorakan, teriakan, serta tantangan terbuka dari beberapa orang di lokasi kejadian. Provokasi yang dilakukan secara berulang-ulang ini akhirnya memancing emosi AB hingga ia memutuskan keluar untuk menemui seorang pria berinisial AA, yang diduga kuat sebagai pelaku utama sekaligus otak di balik perselisihan ini.</div><div><br></div><div>Aksi Pengeroyokan dan Intimidasi di TKP</div><div><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Sesampainya di lokasi pertemuan, korban mendapati bahwa AA tidak datang sendirian. AA telah berkumpul bersama segerombolan pemuda yang merupakan rekan-rekannya.</span><br></div><div><br></div><div>Niat awal yang diduga untuk mengklarifikasi masalah justru berujung pada kekerasan fisik. Perkelahian pun pecah antara AB dan AA. Situasi menjadi tidak berimbang ketika AA mulai memukul korban secara membabi buta hingga menyebabkan AB terjatuh dan tidak berdaya.</div><div><br></div><div>Saat korban terkapar di tanah dan berusaha melindungi dirinya dari hantaman bertubi-tubi, teman-teman AA tidak melerai. Sebaliknya, mereka justru ikut mengintimidasi korban dengan melontarkan kata-kata provokatif yang mengancam nyawa, seperti \"pateni do, matiii\" (bunuh saja, mati kamu). Tindakan verbal ini menimbulkan tekanan psikis dan rasa takut yang mendalam pada diri korban.</div><div><br></div><div>Aksi kekerasan massal ini baru terhenti setelah dua orang petugas keamanan (satpam) yang mengenakan seragam hitam datang ke lokasi kejadian untuk melerai dan membubarkan massa.</div><div><br></div><div>Langkah Hukum&nbsp;<span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Saat ini, kasus tersebut tengah menjadi perhatian publik setelah pihak korban menyerahkan seluruh bukti dan kronologi kepada aparat penegak hukum. Pihak keluarga korban berharap Polrestabes Surabaya dapat segera mengidentifikasi dan menangkap seluruh pelaku, baik pelaku utama (AA) maupun rekan-rekannya yang turut serta melakukan pengeroyokan dan pengancaman.</span></div>','Foto: lokasi TKP pengeroyokan inisial AB XNN | SURABAYA, – Kasus kekerasan jalanan kembali menimpa kalangan remaja di Surabaya. Seorang remaja berin',1,'Surabaya, pengeroyokan, satpam, XNN, beritahariini',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a097de9595a4.jpeg',92,'2026-05-17 15:41:44'),(48,'Perdamaian dengan Boy Hilmi anak dari Advokat Kondang Kurnia Junaidi N,SH.MH. dan istrinya Swastikaningsih,SH. Diwakili oleh Kuasa Hukum Tersangka atas nama Iwan Bintoro yaitu Dr Teguh Suharto Utomo,SH.MH.','perdamaian-dengan-boy-hilmi-anak-dari-advokat-kondang-kurnia-junaidi-n-sh-mh-dan-istrinya-swastikaningsih-sh-diwakili-oleh-kuasa-hukum-tersangka-atas-nama-iwan-bintoro-yaitu-dr-teguh-suharto-utomo-sh-mh','<p style=\"text-align: justify; \"><font color=\"#ff0000\">MERAH PUTIH | SURABAYA</font> – Kasus kecelakaan lalu lintas yang melibatkan sebuah mobil Wuling Almaz dan sepeda motor Honda Beat di Jalan Keputih Tegal, Surabaya, akhirnya berujung damai. Kedua belah pihak yang terlibat sepakat untuk menyelesaikan permasalahan ini secara kekeluargaan melalui penandatanganan Surat Kesepakatan Perdamaian.</p><p style=\"text-align: justify; \">Kecelakaan tersebut terjadi pada hari Jumat, 31 Oktober 2025 sekitar pukul 02.50 WIB di depan SD Muhammadiyah 26 Surabaya. Peristiwa bermula saat mobil Wuling Almaz dengan nomor polisi L-1167-ABA yang dikemudikan oleh Iwan Bintoro terlibat kontak terlebih dahulu dengan sebuah becak motor yang dikemudikan Miftahul Ulum. Mobil kemudian terus melaju ke arah timur dan mengalami kecelakaan lalu lintas dengan sepeda motor Honda Beat bernomor polisi BG-3406-EAF yang dikemudikan oleh Faras Thorfata Bima, dengan penumpang bernama Danny Boy Ilmi Shinenullah. Akibat dari insiden tersebut, Danny Boy Ilmi mengalami luka-luka dan kerugian materiil.</p><p style=\"text-align: justify; \">Dalam dokumen perdamaian yang disusun, Iwan Bintoro selaku Pihak Kedua mengakui adanya kelalaian dalam berkendara yang menyebabkan kecelakaan tersebut. Sebagai bentuk tanggung jawab nyata dan komitmen iktikad baik, Pihak Kedua telah memberikan uang tali asih&nbsp; kepada masing masing&nbsp; korban dan keluarga korban selaku Pihak Pertama (Danny Boy Ilmi beserta orang tua, Kurnia Junaidi, Nababan S.H., M.H., dan Drs Bu&nbsp; Swastiningsih, S.H., Faras soleh selaku korban dan anak dari Lettu TNI Rifkon Soleh, maupun dari Keluarga Korban Miftahul Ulum (alm) telah ikhlas dan menerima bahwasanya ini semua adalah musibah yang tidak dikehendaki oleh siapapun juga.</p><p style=\"text-align: justify; \">Pihak Pertama, Pihak Kedua dan Pihak Ketiga menyatakan telah menerima sepenuhnya ganti rugi tersebut dan menegaskan tidak akan melakukan tuntutan hukum di kemudian hari, baik secara pidana maupun perdata.</p><p style=\"text-align: justify;\">Terkait dengan proses hukum yang sempat berjalan di Satlantas Polrestabes Surabaya dengan Laporan Polisi Nomor: LP/A/1451/X/2025/SPKT, Pihak Pertama menyatakan perkara ini telah dianggap selesai. Pihak Kedua juga menyatakan kesiapannya untuk membantu seluruh proses administrasi perdamaian di instansi terkait, termasuk Kejaksaan dan Pengadilan Negeri Surabaya</p><p style=\"text-align: justify; \">Namun menurut informasi dari Kuasa Hukum Iwan Bintoro selaku Tersangka sudah ada&nbsp; kesepakatan perdamaian&nbsp; ini dan dilakukan tanpa ada paksaan dari pihak manapun, didasari oleh niat baik kedua belah pihak demi ketenangan bersama, serta disaksikan oleh penasihat hukum masing-masing pihak.</p><p style=\"text-align: justify; \">Menurut Kuasa Hukum Terdakwa Iwan Bintoro yaitu DR Teguh Suharto Utomo,SH.MH. berharap agar persoalan ini segera selesai sebab sudah tidak ada persoalan hukum lagi.</p>','MERAH PUTIH | SURABAYA – Kasus kecelakaan lalu lintas yang melibatkan sebuah mobil Wuling Almaz dan sepeda motor Honda Beat di Jalan Keputih Tegal, ',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a0b36ea897c7.png',111,'2026-05-18 22:57:30'),(49,'DPC PERADI Palu Segera Dilantik, Waketum DPN Teguh S. Utomo Sampaikan Ucapan Selamat dan Sinergi Penegakan Hukum','dpc-peradi-palu-segera-dilantik-waketum-dpn-teguh-s-utomo-sampaikan-ucapan-selamat-dan-sinergi-penegakan-hukum','<h6 style=\"text-align: justify; \"><font color=\"#6badde\"><span data-path-to-node=\"3\" data-index-in-node=\"0\" style=\"\">Foto:&nbsp;</span>Wakil Ketua Umum Dewan Pimpinan Nasional (DPN) PERADI, <span data-path-to-node=\"4\" data-index-in-node=\"55\" style=\"\">Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M.</span>,</font><b data-path-to-node=\"3\" data-index-in-node=\"0\">&nbsp;</b></h6><h6 style=\"text-align: justify; \"><b data-path-to-node=\"3\" data-index-in-node=\"0\"><br></b></h6><p style=\"text-align: justify; \"><b>SURABAYA</b> – Menjelang pelaksanaan pelantikan Pengurus Dewan Pimpinan Cabang Perhimpunan Advokat Indonesia (DPC PERADI) Kota Palu yang dijadwalkan pada 2 Juni 2026 mendatang, ucapan selamat dan harapan besar mulai mengalir dari jajaran pimpinan pusat.</p><p data-path-to-node=\"4\" style=\"text-align: justify;\">Wakil Ketua Umum Dewan Pimpinan Nasional (DPN) PERADI, <b data-path-to-node=\"4\" data-index-in-node=\"55\">Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M.</b>, secara resmi menyampaikan apresiasi sekaligus ucapan selamat atas terbentuk dan akan dilantiknya kepengurusan baru di ibukota Provinsi Sulawesi Tengah tersebut.</p><p data-path-to-node=\"5\" style=\"text-align: justify;\">Dalam keterangannya, Dr. Teguh S. Utomo menegaskan pentingnya peran DPC PERADI Kota Palu sebagai ujung tombak organisasi dalam menjaga marwah profesi advokat di daerah.</p><blockquote data-path-to-node=\"6\"><p data-path-to-node=\"6,0\" style=\"text-align: justify;\">\"Saya mengucapkan selamat dan sukses atas pelantikan Pengurus DPC PERADI Kota Palu. Momentum ini harus menjadi langkah awal yang kuat untuk menegaskan kembali komitmen kita sebagai <i data-path-to-node=\"6,0\" data-index-in-node=\"181\">officium nobile</i>—profesi yang mulia. Saya berharap kepengurusan yang baru mampu mengemban amanah ini dengan penuh tanggung jawab, integritas, dan profesionalisme,\" ujar Dr. Teguh.</p></blockquote><p data-path-to-node=\"7\" style=\"text-align: justify;\">Lebih lanjut, Waketum DPN PERADI ini juga menekankan agar DPC PERADI Kota Palu terus bersinergi dengan seluruh elemen penegak hukum serta pemerintah daerah demi mewujudkan keadilan yang merata bagi masyarakat.</p><p data-path-to-node=\"8\" style=\"text-align: justify;\">\"Tantangan penegakan hukum ke depan semakin kompleks. Kehadiran PERADI di Kota Palu harus dirasakan manfaatnya secara nyata, baik dalam memberikan bantuan hukum kepada masyarakat yang membutuhkan, maupun dalam mencetak kader-kader advokat yang berkualitas dan taat kode etik,\" tambahnya.</p><p data-path-to-node=\"9\" style=\"text-align: justify;\">Acara pelantikan yang mengusung tema penguatan organisasi ini rencananya akan dihadiri langsung oleh jajaran teras DPN PERADI, termasuk Ketua Umum Dr. Imam Hidayat, S.H., M.H., Wakil Ketua Umum Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M., serta Sekretaris Jenderal Alam P. Simamora, S.H., M.H.</p><p data-path-to-node=\"10\" style=\"text-align: justify; \">Melalui rilis ini, Dr. Teguh S. Utomo berharap seluruh rangkaian acara pelantikan pada 2 Juni nanti dapat berjalan dengan lancar dan khidmat, serta menjadi awal yang baik bagi kemajuan dunia advokat di Kota Palu.</p>','Foto:&nbsp;Wakil Ketua Umum Dewan Pimpinan Nasional (DPN) PERADI, Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M.,&nbsp;JAKARTA – Menjelang pelaksanaan',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a0c34ae6b9b2.png',92,'2026-05-19 17:00:14'),(50,'Kuasa Hukum Korban Dr Teguh Suharto Utomo,SH.MH. berikan apresiasi dan mendesak segera dilakukan upaya paksa','kuasa-hukum-korban-dr-teguh-suharto-utomo-sh-mh-berikan-apresiasi-dan-mendesak-segera-dilakukan-upaya-paksa','<p style=\"text-align: justify; \"><font color=\"#3984c6\">Foto: Law firm Teguh santoso dan Rekan</font></p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | SURABAYA </font>Jumat, 22 Mei 2026 – Polrestabes Surabaya memastikan penanganan kasus dugaan tindak pidana pencucian uang (TPPU) yang menyeret nama Tan Irwan terus berjalan. Melalui Surat Pemberitahuan Perkembangan Hasil Penyidikan (SP2HP) yang di tanda tangani oleh Kasat Reskrim AKBP Dr Edy Herwiyanto sekaligus atasan penyidik mengungkap sejumlah perkembangan terbaru dalam perkara tersebut.</p><p style=\"text-align: justify; \">Atas nama Kapolrestabes Surabaya, Kasat Reskrim menyampaikan bahwa pihaknya telah melakukan serangkaian tindakan hukum untuk mendalami dugaan pencucian uang yang berkaitan dengan kasus sebelumnya.</p><p style=\"text-align: justify; \">“Penyidik telah melakukan pemeriksaan terhadap lima orang saksi, termasuk melakukan pemeriksaan terhadap saudara Tan Irwan,” demikian keterangan dalam SP2HP yang diterbitkan Satreskrim Polrestabes Surabaya.</p><p style=\"text-align: justify; \">Selain pemeriksaan saksi, penyidik juga disebut telah meminta informasi transaksi keuangan kepada PPATK guna menelusuri aliran dana yang diduga berkaitan dengan tindak pidana tersebut. Dari hasil koordinasi itu, PPATK dikabarkan telah mengeluarkan laporan informasi keuangan yang kini dijadikan bagian dari alat pendukung penyidikan.</p><p style=\"text-align: justify; \">Pihak kepolisian juga menyampaikan telah melakukan penyitaan sejumlah dokumen dan barang bukti dari para saksi guna memperkuat pembuktian perkara.</p><p style=\"text-align: justify; \">“Penyidik juga telah melaksanakan gelar perkara dan menetapkan saudara Tan Irwan sebagai tersangka,” lanjut keterangan tersebut.</p><p style=\"text-align: justify; \">Kasus ini merupakan pengembangan dari perkara penipuan dan penggelapan bisnis pengisian BBM kapal yang sebelumnya telah menjerat Tan Irwan hingga dinyatakan bersalah di persidangan. Dalam perkara tersebut, korban disebut mengalami kerugian mencapai miliaran rupiah setelah dijanjikan keuntungan bisnis yang tidak pernah terealisasi.</p><p style=\"text-align: justify; \">Polrestabes Surabaya menegaskan proses hukum akan terus dikembangkan. Penyidik juga berencana melakukan pemeriksaan lanjutan terhadap tersangka serta berkoordinasi dengan Jaksa Penuntut Umum (JPU) untuk proses hukum berikutnya.</p><p style=\"text-align: justify; \">“Kami memastikan proses penyidikan dilakukan sesuai prosedur hukum yang berlaku dan akan terus dikembangkan berdasarkan alat bukti yang ada,” tulis penyidik dalam surat perkembangan perkara tersebut.</p><p style=\"text-align: justify; \">Sementara itu, pelapor sekaligus kuasa hukum korban, Dr. Teguh S. Utomo, S.H., M.H., berharap aparat penegak hukum segera memberikan kepastian hukum dalam perkara tersebut. Ia meminta agar penyidik segera mengambil langkah tegas terhadap Tersangka Tan Irwan dkk ini sebab selama proses hukum sejak 2022 hingga 2026 Tersangka Tan Irwan telah melakukan berbagai macam Upaya Hukum baik melaporkan Soetijono Korban, Suwandi Ongko selaku anak korban, Kuasa Hukum Pelapor Teguh S.Utomo, Samuel Teguh Santoso selaku Mantan Kuasa Hukum TSK Tan Irwan dan Eddy Yohanes, Liza Angela di DK Peradi Surabaya namun seluruh Laporan tersebut sudah dihentikan Penyedikan nya (SP 3) oleh Polda Jatim, dan Samuel Teguh Santoso juga telah divonis bebas oleh DK Peradi SOHO Surabaya hingga DPN Peradi SOHO Pusat, semua Gugatan dan Perlawanan baik secara pidana hingga Peninjauan Kembali telah kami menangkan telak dan mutlak (sudah inkracht)&nbsp;</p><p style=\"text-align: justify; \">“untuk itu kami berharap segera mendapatkan keadilan dan kebenaran atas perkara ini. Kami juga meminta agar proses hukum terhadap tersangka Tan Irwan segera dipercepat dan dilakukan upaya paksa terhadap yang bersangkutan sesuai ketentuan hukum yang berlaku,” ujar Team Kuasa Hukum TSR Law Firm yang terdiri dari Dr. Teguh S. Utomo, S.Psi,S.H., M.H.,MM.&nbsp; Inka Fadila,SH., Muhammad Wahyu,SH dan Priscilla Xaviera,SH.</p><p style=\"text-align: justify; \">Diketahui juga&nbsp; Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M., juga menjabat sebagai Wakil Ketua Umum DPN PERADI. Ia menegaskan komitmennya untuk terus mengawal proses hukum hingga para korban mendapatkan kepastian hukum dan keadilan sesuai ketentuan perundang-undangan yang berlaku.</p>','Foto: Tan Irwan&nbsp; XNN | SURABAYA Jumat, 22 Mei 2026 – Polrestabes Surabaya memastikan penanganan kasus dugaan tindak pidana pencucian uang (TPPU',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a116a78c2815.jpg',230,'2026-05-23 15:51:04'),(51,'DPD LUMBUNG INFORMASI RAKYAT (LIRA) KOLAKA','dpd-lumbung-informasi-rakyat-lira-kolaka','<p><font color=\"#3984c6\">Foto: Halusinasi</font></p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | KOLAKA</font> Jumat, 22 Mei 2026 Terkait pelaksanaan kegiatan Car Free Day di Kabupaten Kolaka,Ketua DPD LIRA Kolaka Ilham Lukman menilai bahwa pelaksanaan di lapangan tidak berjalan sesuai dengan himbauan dan aturan yang telah diumumkan pemerintah kepada masyarakat.</p><p style=\"text-align: justify; \">Dalam pengumuman resmi disebutkan bahwa selama kegiatan berlangsung terdapat larangan penggunaan kendaraan bermotor, menjaga ketertiban umum, hingga menjaga kebersihan area kegiatan. Namun fakta di lapangan menunjukkan masih adanya kendaraan yang bebas melintas, aktivitas yang mengganggu kenyamanan masyarakat, serta lemahnya pengawasan dari petugas yang berjaga.</p><p style=\"text-align: justify; \">Hal ini menimbulkan pertanyaan besar terhadap keseriusan dan kesiapan pihak penyelenggara maupun petugas yang bertugas di lapangan. Jika aturan sudah diumumkan secara terbuka kepada masyarakat, maka seharusnya pengawasan dilakukan secara maksimal dan tegas, bukan hanya sekadar formalitas kegiatan.</p><p style=\"text-align: justify; \">DPD LIRA Kolaka menilai adanya indikasi kelalaian petugas dalam menjalankan fungsi pengamanan dan pengawasan selama kegiatan berlangsung. Kondisi ini tentu mencederai tujuan utama Car Free Day sebagai ruang publik yang aman, tertib, sehat, dan nyaman bagi masyarakat.</p><p style=\"text-align: justify; \">Kami meminta Pemerintah Kabupaten Kolaka bersama instansi terkait untuk segera melakukan evaluasi menyeluruh terhadap pelaksanaan kegiatan tersebut, termasuk mengevaluasi kinerja petugas di lapangan yang dinilai tidak optimal dalam menjalankan tugas dan tanggung jawabnya.</p><p style=\"text-align: justify; \">Apabila kondisi seperti ini terus dibiarkan, maka kegiatan Car Free Day hanya akan menjadi kegiatan seremonial tanpa pengawasan yang jelas, sementara masyarakat menjadi pihak yang dirugikan.</p><p style=\"text-align: justify; \">DPD LIRA Kolaka juga meminta agar ke depan ada tindakan tegas terhadap setiap pelanggaran yang terjadi selama kegiatan berlangsung, sehingga aturan pemerintah benar-benar dihormati dan dijalankan sebagaimana mestinya.</p>','Foto: HalusinasiXNN | KOLAKA Jumat, 22 Mei 2026 Terkait pelaksanaan kegiatan Car Free Day di Kabupaten Kolaka,Ketua DPD LIRA Kolaka Ilham Lukman menil',8,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a106ed636690.jpg',44,'2026-05-22 21:57:26'),(52,'LAWFIRM TEGUH SANTOSO & REKAN: BERKOMITMEN BERIKAN LAYANAN HUKUM BERKUALITAS, EFEKTIF DAN TERPERCAYA   ','lawfirm-teguh-santoso-rekan-berkomitmen-berikan-layanan-hukum-berkualitas-efektif-dan-terpercaya','<h6 style=\"text-align: start; \"><span style=\"text-align: justify;\"><font color=\"#3984c6\">Foto: Pimpinan LAWFIRM TEGUH SANTOSO &amp; REKAN Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M.</font></span></h6><h6 style=\"text-align: start; \"><span style=\"text-align: justify;\"><font color=\"#3984c6\"><br></font></span></h6><p style=\"text-align: start; \"><span style=\"text-align: justify;\"><font color=\"#ce0000\">XNN | JAKARTA </font>– Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M. Mengutamakan Standar Pelayanan Tinggi Demi Kepuasan dan Perlindungan Hukum Klien Dalam dunia jasa hukum yang semakin berkembang, kebutuhan akan layanan yang profesional, andal, dan berorientasi pada kepentingan klien menjadi hal yang sangat mendesak.</span></p><p style=\"text-align: start; \"><span style=\"text-align: justify;\"> Menjawab tantangan tersebut, LAWFIRM TEGUH SANTOSO &amp; REKAN yang dipimpin langsung oleh Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M., hadir sebagai lembaga hukum yang mengedepankan kualitas, integritas, dan keahlian mendalam dalam menangani berbagai perkara hukum.</span></p><p style=\"text-align: left;\">Lembaga ini didirikan dengan tujuan utama menyediakan layanan hukum berstandar tinggi, mampu menjawab setiap dinamika peraturan perundang‑undangan serta kebutuhan masyarakat maupun pelaku usaha. Sejak awal berdiri, pihaknya senantiasa berupaya mengembangkan kompetensi dan keahlian secara berkesinambungan, agar selalu dapat memenuhi tuntutan serta persyaratan baru yang terus berkembang, dengan memberikan pelayanan yang semakin optimal dari waktu ke waktu.</p><p style=\"text-align: left;\">Komitmen Layanan yang Efektif, Andal, dan Profesional. Sebagai pemimpin lembaga, Dr. Teguh S. Utomo membawa visi kuat untuk menjadikan Lawfirm Teguh Santoso &amp; Rekan sebagai mitra hukum yang paling dipercaya. Beliau menegaskan bahwa keberhasilan dalam memberikan solusi hukum tidak hanya bergantung pada pengetahuan hukum semata, melainkan juga kemampuan memahami kebutuhan klien secara menyeluruh.</p><p style=\"text-align: left;\">“Kami berkomitmen penuh untuk memberikan layanan hukum yang efektif dan andal, didukung oleh tim hukum yang berprestasi serta memiliki pengalaman luas di berbagai bidang industri. Kombinasi latar belakang ilmu pengetahuan yang beragam serta keahlian praktis menjadikan kami mampu memberikan pendekatan penyelesaian kasus yang komprehensif, tepat sasaran, dan berpihak pada keadilan,” ujar Dr. Teguh.</p><p style=\"text-align: left;\">Dengan latar belakang pendidikan yang lengkap dan beragam, beliau mampu memadukan aspek psikologis, yuridis, maupun manajerial dalam setiap penanganan kasus, sehingga solusi yang ditawarkan tidak hanya benar secara hukum, tetapi juga tepat secara strategis dan manusiawi.</p><p style=\"text-align: left;\">Sistem Kerja Terstruktur dan Berorientasi Hasil, Kekuatan utama lembaga ini juga terletak pada pola kerja yang terorganisir dengan baik dan sistem pengawasan yang ketat. Para peneliti serta asisten hukum yang tergabung memiliki kemampuan memadai untuk menangani berbagai jenis tugas dan perkara, mulai dari yang bersifat sederhana hingga kompleks. Seluruh pekerjaan dilakukan di bawah bimbingan, pengawasan, serta arahan langsung dari para mitra dan rekanan yang berpengalaman, termasuk pimpinan utama.</p><p style=\"text-align: left;\">“Setiap langkah penanganan kasus kami pastikan berjalan sesuai prosedur, teliti, dan transparan. Kami menjamin seluruh pekerjaan diselesaikan dengan baik dan tepat waktu, sesuai dengan kebutuhan serta harapan klien. Tanggung jawab penuh terhadap setiap kasus yang dipercayakan merupakan prinsip dasar yang selalu kami pegang teguh,” tambahnya.</p><p style=\"text-align: left;\">Menjadi Rujukan Utama Layanan Hukum Profesional, Dengan landasan keahlian yang luas, integritas yang tinggi, serta komitmen pelayanan prima, Lawfirm Teguh Santoso &amp; Rekan terus tumbuh dan berkembang menjadi salah satu lembaga hukum yang diakui kredibilitasnya. Lembaga ini tidak hanya berperan sebagai pemberi jasa hukum, melainkan juga mitra strategis yang siap memberikan perlindungan hukum yang kokoh serta solusi yang tepat guna bagi setiap permasalahan yang dihadapi klien.</p>','Foto: Pimpinan LAWFIRM TEGUH SANTOSO &amp; REKAN Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M.XNN | JAKARTA – Dr. Teguh S. Utomo, S.Psi., S.H., M.H.,',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a1290e51b33c.jpg',93,'2026-05-24 12:47:17'),(55,'Perkuat Penegakan Hukum, Law Office Suherman, S.H. & Partners Hadir Sebagai Mitra Strategis Masyarakat','perkuat-penegakan-hukum-law-office-suherman-s-h-partners-hadir-sebagai-mitra-strategis-masyarakat','<p><font color=\"#085294\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\">Foto:&nbsp;</span><span style=\"-webkit-text-size-adjust: 100%; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\">Suherman, S.H. &nbsp;</span></font></p><p><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">XNN |&nbsp;</span><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Di tengah kompleksitas permasalahan hukum yang kian meningkat, kebutuhan akan pendampingan hukum yang profesional, berintegritas, dan solutif menjadi sangat krusial bagi masyarakat. Menjawab tantangan tersebut, Kantor Hukum Suherman, S.H. &amp; Partners hadir sebagai entitas hukum yang berkomitmen mengedepankan keadilan dan perlindungan hak-hak hukum bagi seluruh lapisan masyarakat.</span></p><p>Dipimpin langsung oleh Suherman, S.H., Kantor Hukum ini berfokus pada pemberian layanan hukum komprehensif, baik melalui jalur litigasi (persidangan) maupun non-litigasi. Dengan rekam jejak yang terus dibangun di berbagai lingkup peradilan, Suherman menegaskan bahwa profesi advokat bukan sekadar mendampingi perkara, melainkan menjalankan amanah untuk menegakkan kebenaran.</p><p>Kantor Hukum Suherman, S.H. &amp; Partners juga didukung oleh tim yang ahli di berbagai bidang hukum. Kehadiran para praktisi hukum yang kompeten di tim ini memastikan bahwa setiap persoalan yang ditangani—baik sengketa perdata, hukum keluarga, hukum bisnis, maupun perkara pidana—mendapatkan analisis dan strategi pembelaan yang tepat serta mendalam.</p><p>\"Setiap persoalan hukum memiliki dinamika dan karakteristiknya masing-masing. Di Kantor Hukum Suherman, S.H. &amp; Partners, kami memegang teguh prinsip bahwa setiap klien berhak mendapatkan pembelaan yang maksimal, transparan, dan berdasarkan pada koridor hukum yang berlaku,\" ujar Suherman.</p><p>Akses Keadilan yang Lebih Dekat</p><p><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Sebagai bentuk dedikasi dalam memberikan pelayanan terbaik, Kantor Hukum Suherman, S.H. &amp; Partners membuka pintu selebar-lebarnya bagi masyarakat yang membutuhkan konsultasi maupun pendampingan hukum. Bagi masyarakat yang ingin berkonsultasi atau membutuhkan jasa hukum, dapat menghubungi kami melalui:</span></p><p>WhatsApp: ‪+62 857‑2969‑3588‬</p><p>Alamat Kantor:&nbsp;<span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Jl. Masjid Raya RT.06 RW.05 Desa Kranji, Kecamatan Paciran, Kabupaten Lamongan, Jawa Timur</span></p><p>Kami siap mendampingi dan memberikan solusi atas permasalahan hukum yang Anda hadapi dengan prinsip kejujuran, kecakapan, dan ketegasan.</p><p>Tentang Kantor Hukum Suherman, S.H. &amp; Partners:&nbsp;<span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Kantor Hukum Suherman, S.H. &amp; Partners adalah kantor pengacara yang bergerak di bidang layanan hukum komprehensif. Berdedikasi untuk memberikan advokasi terbaik dengan mengedepankan etika profesi dan profesionalisme.</span></p>','Foto:&nbsp;Suherman, S.H. &nbsp;XNN |&nbsp;Di tengah kompleksitas permasalahan hukum yang kian meningkat, kebutuhan akan pendampingan hukum yang profe',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a145a1173705.jpeg',293,'2026-05-25 21:17:53'),(56,'Sebuah kecelakaan lalu lintas terjadi di kawasan jalan raya surabaya pada pagi hari tanggal 20 Mei 2026','sebuah-kecelakaan-lalu-lintas-terjadi-di-kawasan-jalan-raya-surabaya-pada-pagi-hari-tanggal-20-mei-2026','<p style=\"text-align: justify; \"><font color=\"#3984c6\">Foto: korban insiden kecelakaan</font></p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | SURABAYA</font> - Selasa, 26 Mei 2026 Sebuah insiden kecelakaan lalu lintas yang melibatkan seorang anak terjadi di kawasan Jalan H.R. Muhammad, tepatnya di depan Hotel Vasa, Kota Surabaya, pada pagi hari, Rabu (20/05/2026). Detik-detik sebelum terjadinya tabrakan tersebut sempat terekam oleh kamera dashcam dari salah satu kendaraan dan videonya beredar luas.</p><p style=\"text-align: justify; \">Kondisi Korban Akibat peristiwa nahas tersebut, seorang anak dilaporkan mengalami luka yang sangat serius. Berdasarkan pantauan, korban menderita luka berat pada area wajah dan diduga kuat mengalami geger otak. Saat ini, korban tengah mendapatkan penanganan medis dan perawatan intensif di rumah sakit.</p><p style=\"text-align: justify; \">Tindakan Cepat Kepolisian Unit Kecelakaan Lalu Lintas (Laka Lantas) Kepolisian Resor Kota Besar (Polrestabes) Surabaya merespons cepat kejadian ini. Petugas telah melakukan olah Tempat Kejadian Perkara (TKP) untuk menyelidiki kronologi pasti kecelakaan.</p><p style=\"text-align: justify;\">Selain mengamankan rekaman dashcam yang menjadi petunjuk penting, pihak kepolisian juga telah menyita sejumlah barang bukti. Berdasarkan Surat Tanda Terima Kendaraan/Surat dari Polrestabes Surabaya bernomor TBP/24/V/2026/Lantas tertanggal 24 Mei 2026, pihak berwajib telah menyita Kartu Tanda Penduduk (KTP) atas nama Maria Magdalena Mariyeni (30).</p><p style=\"text-align: justify;\">Berikut adalah rincian data terkait bukti yang disita untuk proses penyelidikan lebih lanjut:</p><p style=\"text-align: justify; \">Nama: Maria Magdalena Mariyeni</p><p style=\"text-align: justify; \">Usia: 30 Tahun</p><p style=\"text-align: justify; \">Pekerjaan: Petani</p><p style=\"text-align: justify;\">Alamat: Kencong RT 3/RW 2, Jember</p><p style=\"text-align: justify;\">Lokasi Kejadian: Jl. H.R. Muhammad (Depan Hotel Vasa), Surabaya.</p><p style=\"text-align: justify; \">Hingga berita ini diturunkan, kasus kecelakaan tersebut masih dalam proses penanganan dan penyelidikan intensif oleh penyidik Satlantas Polrestabes Surabaya</p><p style=\"text-align: justify; \">hingga berita ini diturunkan mobil yang digunakan oleh Terlapor/Terduga Penyerempet belum diamankan / ditahan oleh Kepolisian Satlamtas Polrestabes Surabaya yaitu 1 unit Mobil Binguo Plat Mobil Nomer&nbsp;L 1050 CAU.&nbsp;</p><p style=\"text-align: justify; \">Tim kuasa hukum TSR Law Firm M.Wahyu Ferdiansyah, Inka Fadilah. SH Herlini Y.SWeka,SH. Memohon kepada Kapolrestabes Surabaya dan Kasatreskrim Polrestabes Sby agar dapat memberikan atensi dan perhatian yang menyeret korban anak berusia 5 tahun yang mengalami gegar otak parah, namun dari pihak mobil seolah acuh dan adalagi oknum notaris madura yang meneror dan intimidasi korban</p>','Foto: korban insiden kecelakaanXNN | SURABAYA - Selasa, 26 Mei 2026 Sebuah insiden kecelakaan lalu lintas yang melibatkan seorang anak terjadi di kawa',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a1597ad77276.jpg',211,'2026-05-29 20:17:01'),(57,'DR. TEGUH S. UTOMO, S.Psi., S.H., M.H., M.M.PERUNDUNGAN DALAM PERSPEKTIF PSIKOLOGIS – DINAMIKA, DAMPAK, DAN STRATEGI INTERVENSI','dr-teguh-s-utomo-s-psi-s-h-m-h-m-m-perundungan-dalam-perspektif-psikologis-dinamika-dampak-dan-strategi-intervensi','<p><font color=\"#3984c6\">Foto: DR. TEGUH S. UTOMO, S.Psi., S.H., M.H., M.M.</font></p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | SURABAYA</font><font color=\"#3984c6\">&nbsp;-&nbsp;</font>Selasa, 26 MEI 2026 Waketum DPN PERHIMPUNAN ADVOKAT INDONESIA Tegaskan Karakteristik Perilaku, Mekanisme Psikologis, serta Implikasi Jangka Panjang bagi Individu dan Lingkungan Sosial.Perundungan merupakan fenomena psikososial yang hingga saat ini masih menjadi perhatian utama dalam kajian psikologi, mengingat dampaknya yang signifikan terhadap perkembangan kepribadian, fungsi kognitif, serta kesejahteraan psikologis individu. Dalam kerangka pemikiran ilmiah, perundungan tidak sekadar dipandang sebagai bentuk interaksi sosial yang menyimpang, melainkan sebagai pola perilaku agresif yang terstruktur, berulang, serta ditandai dengan adanya ketimpangan kekuasaan atau kekuatan antara pihak yang terlibat.</p><p style=\"text-align: justify; \">Hal tersebut dikemukakan oleh Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M. selaku Wakil Ketua Umum Dewan Pimpinan Nasional Perhimpunan Advokat Indonesia (DPN PERADI), dalam wawancara khusus yang mengangkat kajian mendalam mengenai perundungan ditinjau dari landasan teori dan prinsip-prinsip psikologi. Berbekal integrasi pemahaman antara ilmu perilaku, hukum, dan manajemen organisasi, ia memaparkan bahwa pemahaman yang komprehensif mengenai mekanisme psikologis yang mendasari perilaku ini, termasuk dampak luas yang ditimbulkannya, menjadi prasyarat utama dalam merancang upaya pencegahan dan penanganan yang efektif.</p><p style=\"text-align: justify; \">Konsep dan Karakteristik Perundungan dalam Tinjauan Psikologi</p><p style=\"text-align: justify; \">Secara teoritis, Dr. Teguh menjelaskan bahwa perundungan didefinisikan sebagai segala bentuk tindakan atau perilaku yang dilakukan secara sengaja, berulang dalam kurun waktu tertentu, serta bertujuan menimbulkan rasa sakit, ketidaknyamanan, ketakutan, atau kerusakan psikologis maupun fisik pada pihak lain yang berada dalam posisi kurang berdaya atau memiliki keterbatasan dalam membela diri. Berdasarkan tipologi perilakunya, perundungan diklasifikasikan menjadi beberapa bentuk utama, yaitu:</p><p style=\"text-align: justify;\">1.&nbsp;Perundungan Fisik: Ditandai dengan adanya kontak fisik yang bersifat menyakiti atau merusak, yang secara psikologis merupakan manifestasi dari dorongan agresi terbuka serta keinginan untuk mendominasi secara nyata.</p><p style=\"text-align: justify;\">2.&nbsp;Perundungan Verbal: Berbentuk pernyataan lisan yang menghina, mencela, mengancam, atau merendahkan, yang berfungsi sebagai sarana penegasan superioritas pelaku sekaligus penekanan harga diri korban melalui mekanisme psikologis penolakan dan penghakiman.</p><p style=\"text-align: justify;\">3.&nbsp;Perundungan Relasional atau Sosial: Berupa upaya memutus hubungan sosial, pengucilan, atau penyebaran informasi yang tidak benar, yang bertujuan merusak citra diri serta posisi individu dalam struktur kelompok, dengan dampak utama berupa gangguan fungsi sosial dan rasa memiliki.</p><p style=\"text-align: justify; \">4.&nbsp;Perundungan Digital: Merupakan bentuk adaptasi perilaku agresif di ruang maya, yang memiliki karakteristik khusus berupa jangkauan dampak yang luas, durasi paparan yang berkelanjutan, serta sifat jejak informasi yang permanen, sehingga memperparah beban psikologis yang dialami korban.</p><p style=\"text-align: justify; \">“Dalam perspektif psikologi perkembangan dan psikologi sosial, perilaku perundungan tidak muncul secara tiba-tiba, melainkan merupakan hasil dari interaksi kompleks antara faktor internal individu dan faktor eksternal lingkungan. Faktor internal mencakup struktur kepribadian, regulasi emosi, kemampuan kognitif sosial, serta pola internalisasi nilai. Sedangkan faktor eksternal meliputi dinamika sistem keluarga, pola asuh, iklim kelompok sebaya, norma lingkungan, serta pengaruh budaya yang berlaku,” papar Dr. Teguh secara akademis.</p><p style=\"text-align: justify; \">Dampak Psikologis Perundungan: Multidimensi, Menyeluruh, dan Berjangka Panjang</p><p style=\"text-align: justify; \">Berdasarkan kajian empiris serta landasan teori psikologi klinis, perkembangan, dan sosial, Dr. Teguh memaparkan bahwa dampak perundungan bersifat sangat luas, menyentuh berbagai aspek fungsi psikologis individu, serta dapat berlangsung dalam jangka waktu yang panjang, bahkan menetap hingga tahapan perkembangan selanjutnya. Dampak ini tidak hanya dirasakan oleh pihak korban, namun juga berdampak signifikan bagi pelaku maupun saksi yang menyaksikan kejadian tersebut.</p><p style=\"text-align: justify; \">Dampak Bagi Korban Pengalaman perundungan berperan sebagai peristiwa stresor traumatik yang dapat mengganggu keseimbangan psikologis serta proses perkembangan yang sedang berlangsung. Secara terperinci, dampak yang terjadi meliputi:</p><p style=\"text-align: justify; \">Aspek Kognitif: Terjadi gangguan pada proses berpikir, daya konsentrasi, serta kemampuan memecahkan masalah. Korban cenderung mengembangkan skema kognitif negatif yang menetap, seperti persepsi diri sebagai individu yang tidak berharga, lemah, atau tidak mampu, serta persepsi lingkungan sebagai tempat yang berbahaya, tidak adil, dan tidak dapat dipercaya. Hal ini berpengaruh langsung terhadap penurunan prestasi akademik atau kinerja kerja, serta hambatan dalam pengambilan keputusan.</p><p style=\"text-align: justify; \">Aspek Emosional: Muncul berbagai gangguan regulasi emosi, antara lain peningkatan kecemasan umum maupun spesifik, rasa takut yang berlebihan, kemarahan yang terpendam, perasaan sedih yang mendalam, hingga gejala depresi. Korban seringkali mengalami perasaan terisolasi, kesepian, serta kehilangan minat terhadap aktivitas yang sebelumnya disukai. Dalam kasus tertentu dapat berkembang menjadi gangguan stres pascatrauma (GSPT) yang ditandai dengan ingatan yang terus muncul kembali, penghindaran terhadap hal yang berkaitan dengan kejadian, serta peningkatan respons fisiologis.</p><p style=\"text-align: justify; \">Aspek Sosial: Terjadi gangguan signifikan dalam fungsi adaptasi sosial, berupa penarikan diri dari pergaulan, ketidakmampuan membangun hubungan yang sehat dan saling percaya, serta penurunan kemampuan berkomunikasi dan berinteraksi dengan orang lain. Korban cenderung menjadi pasif, penurut, atau sebaliknya menjadi mudah tersinggung dan agresif sebagai bentuk mekanisme pertahanan diri.</p><p style=\"text-align: justify; \">Aspek Kepribadian: Pengalaman negatif yang berulang dapat mengubah pola pembentukan kepribadian, menimbulkan rasa rendah diri yang kronis, hilangnya rasa percaya diri, serta ketidakmampuan mengenali dan menghargai nilai diri sendiri. Dalam kondisi yang paling berat, dampak ini dapat memicu munculnya kecenderungan perilaku menyakiti diri sendiri hingga keinginan untuk mengakhiri hidup sebagai bentuk pelarian dari penderitaan yang dirasakan.</p><p style=\"text-align: justify; \">Dampak Bagi Pelaku Bagi pihak yang melakukan perundungan, dampak psikologis yang terjadi tidak kalah serius, meskipun seringkali tidak disadari secara langsung:</p><p style=\"text-align: justify; \">Pola perilaku agresif yang tidak dikoreksi akan mengalami proses pembiasaan dan internalisasi, sehingga menjadi bagian dari struktur kepribadian yang menetap.</p><p style=\"text-align: justify; \">Terjadi hambatan signifikan dalam perkembangan empati, kemampuan memahami perasaan dan perspektif orang lain, serta pembentukan hati nurani dan pertimbangan moral.</p><p style=\"text-align: justify; \">Pelaku cenderung mengembangkan pola pikir yang menganggap kekuasaan dan kekuatan adalah hal yang paling utama, sehingga sulit membangun hubungan sosial yang setara, saling menghargai, dan berkelanjutan.</p><p style=\"text-align: justify; \">Dalam jangka panjang, hal ini meningkatkan risiko terjadinya gangguan perilaku, pelanggaran norma dan aturan, serta kecenderungan melakukan tindakan yang melanggar hak orang lain di masa mendatang.</p><p style=\"text-align: justify; \">Dampak Bagi Saksi dan Lingkungan Bagi individu yang menyaksikan perundungan, dampak psikologis yang muncul antara lain rasa takut menjadi korban selanjutnya, rasa tidak berdaya, kebingungan dalam menentukan sikap, hingga penurunan rasa aman dan kepercayaan terhadap lingkungan. Secara keseluruhan, hal ini membentuk iklim psikososial yang tidak sehat, penuh ketegangan, serta jauh dari rasa saling menghargai dan mendukung.</p><p style=\"text-align: justify; \">“Secara prinsip psikologi, kerusakan yang ditimbulkan perundungan bukan hanya bersifat sementara atau sekadar luka yang terlihat mata, melainkan merusak struktur dasar fungsi psikologis individu yang menjadi dasar dalam menjalani kehidupan sehari-hari dan perkembangan di masa depan. Dampak ini seringkali bersifat kumulatif, artinya semakin sering dan semakin berat perundungan yang dialami, semakin besar pula kerusakan yang terjadi dan semakin sulit proses pemulihannya,” jelas Dr. Teguh.</p><p style=\"text-align: justify; \">Analisis Dinamika Psikologis: Akar Masalah dan Mekanisme Terjadinya</p><p style=\"text-align: justify; \">Dr. Teguh menekankan bahwa pemahaman terhadap akar masalah harus didasarkan pada prinsip dasar psikologi bahwa setiap perilaku memiliki fungsi dan makna tertentu bagi individu yang melakukannya. Perilaku perundungan pada dasarnya merupakan bentuk respons adaptasi yang keliru terhadap kebutuhan psikologis dasar, seperti kebutuhan akan pengakuan, rasa berkuasa, rasa aman, atau keinginan untuk diterima dalam kelompok.</p><p style=\"text-align: justify; \">“Banyak pelaku perundungan sendiri berasal dari lingkungan atau pola pengasuhan yang kurang mendukung perkembangan kepribadian yang sehat, seperti kurangnya kehangatan emosional, pola didik yang terlalu keras atau sebaliknya terlalu permisif, serta paparan terhadap model perilaku agresif. Dalam hal ini, perilaku yang ditampilkan sebenarnya merupakan bentuk proyeksi dari ketidaknyamanan psikologis, ketidakmampuan mengelola emosi, atau kekosongan kebutuhan batin yang dialami oleh pelaku itu sendiri,” urainya.</p><p style=\"text-align: justify; \">Meskipun demikian, pemahaman mengenai latar belakang psikologis tersebut tidak dimaksudkan untuk membenarkan tindakan yang dilakukan, melainkan sebagai dasar ilmiah dalam merancang pendekatan penanganan yang tepat sasaran. Penanganan yang efektif harus mampu mengidentifikasi akar masalah, memperbaiki pola pikir dan perilaku yang menyimpang, serta mengembangkan aspek psikologis yang belum matang, baik pada korban maupun pelaku.</p><p style=\"text-align: justify; \">Pendekatan Intervensi dan Strategi Pengembangan Psikologis</p><p style=\"text-align: justify; \">Berdasarkan prinsip psikologi positif dan psikologi pendidikan, Dr. Teguh mengemukakan bahwa upaya penanganan dan pencegahan harus dilaksanakan secara terpadu, berfokus pada pengembangan potensi psikologis individu serta pembentukan lingkungan yang mendukung kesehatan mental. Beberapa pendekatan utama yang dianjurkan meliputi:</p><p style=\"text-align: justify; \">Pertama, pendekatan kognitif-perilaku, yang bertujuan mengubah pola pikir, keyakinan, serta cara memaknai diri dan lingkungan yang keliru, sekaligus melatih keterampilan pengelolaan emosi, penyelesaian masalah, dan komunikasi yang konstruktif.</p><p style=\"text-align: justify; \">Kedua, pengembangan kecerdasan emosional dan sosial, yaitu kemampuan mengenali, memahami, serta mengelola emosi diri dan orang lain, mengembangkan rasa empati, serta membangun pola hubungan sosial yang sehat dan saling menghargai.</p><p style=\"text-align: justify; \">Ketiga, pembentukan iklim lingkungan yang positif, yang menekankan prinsip kesetaraan, keadilan, serta dukungan sosial, sehingga setiap individu merasa aman, dihargai, dan memiliki rasa memiliki yang kuat.</p><p style=\"text-align: justify; \">Keempat, integrasi nilai-nilai luhur dan prinsip etika ke dalam proses pembentukan kepribadian, yang menjadi landasan internal dalam mengarahkan perilaku serta memberikan makna pada setiap tindakan yang dilakukan.</p><p style=\"text-align: justify; \">“Secara prinsip psikologi, tujuan akhir dari seluruh upaya ini adalah mewujudkan perkembangan kepribadian yang utuh, sehat, dan berfungsi optimal. Memahami kedalaman dampak yang ditimbulkan menjadi alasan utama mengapa perundungan tidak dapat dianggap sebagai hal sepele, serta tidak dapat dihilangkan hanya dengan aturan atau sanksi semata. Perubahan harus dimulai dari pemahaman ilmiah, kesadaran menyeluruh, serta perbaikan dalam cara berpikir, merasa, dan berperilaku yang berakar dari kematangan psikologis setiap individu,” tegas Dr. Teguh dalam penutup pemaparannya.</p><p style=\"text-align: justify; \">Pemaparan ilmiah ini diharapkan dapat menjadi landasan teoritis dan praktis dalam menyusun kebijakan, program, serta langkah-langkah penanganan yang berbasis bukti dan sesuai dengan prinsip-prinsip ilmu perilaku yang berlaku.</p>','Foto: DR. TEGUH S. UTOMO, S.Psi., S.H., M.H., M.M.XNN | SURABAYA&nbsp;-&nbsp;Selasa, 26 MEI 2026 Waketum DPN PERHIMPUNAN ADVOKAT INDONESIA Tegaskan Ka',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a159a9640a59.jpeg',67,'2026-05-26 20:05:26'),(58,'Tangis Anak 5 Tahun Dibungkam? Dr. Teguh Ancam Bawa Kasus Hingga Kapolri dan DPR RI','tangis-anak-5-tahun-dibungkam-dr-teguh-ancam-bawa-kasus-hingga-kapolri-dan-dpr-ri','<p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | SURABAYA</font> - Menindaklanjuti kasus kecelakaan yang menimpa anak di bawah umur bernama Marlince Viola (5 tahun), Advokat Dr. Teguh Suharto Utomo, SH., MH bersama tim kuasa hukum yakni Adv. Sumiatin, Indahwati, Inka Fadila, dan M. Wahyu menyatakan akan turun langsung mengawal penuh perjuangan hukum korban dan keluarga hingga mendapatkan keadilan yang sebenar-benarnya.</p><p style=\"text-align: justify;\">Dr. Teguh dengan nada tegas dan geram menyampaikan bahwa kasus ini tidak bisa dianggap sepele, sebab yang menjadi korban adalah seorang anak kecil yang masa depannya terancam akibat peristiwa tersebut.</p><p style=\"text-align: justify;\">“Ini bukan sekadar kecelakaan biasa. Ini menyangkut masa depan seorang anak berusia 5 tahun yang pertumbuhan dan perkembangan otaknya bisa terganggu seumur hidup. Jangan ada pihak yang mencoba menutupi fakta atau bermain-main dengan penderitaan rakyat kecil,” tegas Dr. Teguh.</p><p style=\"text-align: justify;\">Pihaknya juga mengaku sangat prihatin atas dugaan adanya intimidasi terhadap ibu korban, yakni Maria Magdalena, yang disebut-sebut dipaksa berdamai dan diarahkan untuk mengakui kejadian tersebut sebagai kecelakaan tunggal.</p><p style=\"text-align: justify;\">“Kami mendapat informasi bahwa ibu korban yang hanya seorang petani desa dan saat ini bekerja sebagai pembantu rumah tangga didatangi secara beramai-ramai, ditekan untuk menerima uang Rp10 juta, lalu disuruh mengakui bahwa ini kecelakaan tunggal. Bahkan disebut ada keterlibatan oknum notaris di Bangkalan. Kalau benar ini terjadi, maka ini tindakan yang sangat tidak manusiawi dan mencederai hukum,” ujar Dr. Teguh dengan nada keras.</p><p style=\"text-align: justify;\">Menurutnya, kondisi keluarga korban yang lemah secara ekonomi tidak boleh dijadikan celah untuk membungkam suara keadilan.</p><p style=\"text-align: justify;\">“Jangan mentang-mentang korban orang kecil lalu dianggap bisa ditekan dan disuruh diam. Kami akan lawan segala bentuk intimidasi, tekanan, maupun upaya pengaburan fakta. Hukum tidak boleh tajam ke bawah dan tumpul ke atas,” tambahnya.</p><p style=\"text-align: justify;\">Tim kuasa hukum menuntut adanya pertanggungjawaban penuh, baik secara moral maupun materiil, terhadap korban dan keluarganya. Mereka juga mendesak aparat penegak hukum bertindak profesional dan transparan dalam mengusut perkara tersebut.</p><p style=\"text-align: justify; \">“Kalau perkara ini tidak dibereskan dengan benar, maka kami siap membawa perjuangan ini sampai ke Kapolri bahkan Komisi III DPR RI. Kami tidak akan mundur selangkah pun demi keadilan anak ini,” tutup Dr. Teguh.</p>','XNN | SURABAYA - Menindaklanjuti kasus kecelakaan yang menimpa anak di bawah umur bernama Marlince Viola (5 tahun), Advokat Dr. Teguh Suharto Utomo, S',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a170634c1792.jpg',109,'2026-05-27 21:56:52'),(59,'Advokat Dr Teguh Suharto Utomo Bersama Perguruan Karate ASBKI Rutin Gelar Bakti Sosial di Panti Asuhan dan Panti Jompo','advokat-dr-teguh-suharto-utomo-bersama-perguruan-karate-asbki-rutin-gelar-bakti-sosial-di-panti-asuhan-dan-panti-jompo','<p style=\"text-align: justify;\"><span style=\"background-color: rgb(255, 255, 255);\"><font color=\"#3984c6\">Foto:&nbsp;<span style=\"font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">DR. Teguh Suharto Utomo</span></font></span></p><p style=\"text-align: justify;\"><font color=\"#ce0000\">XNN | Surabaya </font>– Kepedulian terhadap sesama terus ditunjukkan Advokat DR. Teguh Suharto Utomo yg juga Wakil Ketua Umum DPN Peradi bersama Perguruan Karate ASBKI (Akademi Seni Bertarung Kyokushin Indonesia) melalui berbagai kegiatan sosial yang rutin dilaksanakan setiap tahun.</p><p style=\"text-align: justify;\">Sedikitnya dua kali dalam setahun, ASBKI menggelar aksi bakti sosial dengan menyambangi panti asuhan dan panti jompo di sejumlah wilayah. Kegiatan tersebut menjadi bagian dari komitmen organisasi dalam menanamkan nilai kemanusiaan, kepedulian sosial, serta semangat berbagi kepada para anggota dan masyarakat luas.</p><p style=\"text-align: justify;\">Pimpinan Pusat ASBKI sekaligus Pimpinan TSR Law Firm Surabaya yaitu Dr Teguh Suharto Utomo, mengatakan bahwa kegiatan sosial merupakan salah satu bentuk pengabdian kepada masyarakat yang harus terus dijaga dan dilestarikan. Menurutnya, seni bela diri tidak hanya mengajarkan kemampuan fisik dan disiplin, tetapi juga membentuk karakter yang peduli terhadap lingkungan sosial.</p><p style=\"text-align: justify;\">\"Kami ingin menanamkan kepada seluruh anggota ASBKI bahwa kekuatan sejati bukan hanya soal kemampuan bertarung, tetapi juga bagaimana memiliki kepedulian dan rasa empati kepada sesama yang membutuhkan,\" ujar Teguh.</p><p style=\"text-align: justify;\">Dalam setiap kegiatan bakti sosial, ASBKI menyalurkan bantuan berupa kebutuhan pokok, makanan, perlengkapan sehari-hari, serta santunan kepada penghuni panti asuhan maupun panti jompo. Selain itu, para anggota juga berinteraksi langsung dengan penghuni panti untuk memberikan semangat dan kebahagiaan.</p><p style=\"text-align: justify;\">Kegiatan tersebut mendapat sambutan positif dari pengurus panti maupun masyarakat sekitar. Kehadiran rombongan ASBKI dinilai mampu memberikan motivasi serta membantu meringankan kebutuhan para penghuni panti.</p><p style=\"text-align: justify;\">Teguh menegaskan bahwa program bakti sosial akan terus menjadi agenda rutin ASBKI sebagai bentuk tanggung jawab sosial organisasi.</p><p style=\"text-align: justify;\">\"Semoga apa yang kami lakukan dapat memberikan manfaat dan keberkahan bagi semua pihak. Kami berharap semangat berbagi ini dapat menginspirasi lebih banyak orang untuk peduli terhadap sesama,\" tambahnya.</p><p style=\"text-align: justify;\">Melalui kegiatan sosial yang konsisten dilaksanakan, ASBKI tidak hanya dikenal sebagai perguruan karate yang fokus pada pembinaan prestasi dan karakter, tetapi juga sebagai organisasi dan Kantor Hukum TSR Law Firm &nbsp;yang aktif berkontribusi dalam kegiatan kemanusiaan dan sosial di tengah masyarakat.</p>','Foto:&nbsp;DR. Teguh Suharto UtomoXNN | Surabaya – Kepedulian terhadap sesama terus ditunjukkan Advokat DR. Teguh Suharto Utomo yg juga Wakil Ketua ',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a1c4fcca16e2.jpeg',56,'2026-05-31 22:12:12'),(60,'Harapan Kasasi Siek Liani Puspitasari akhirnya Kandas','harapan-kasaai-siek-liani-puspitasari-akhirnya-kandas','<p><font color=\"#ce0000\">XNN | SURABAYA</font> - Berbagai upaya hukum Siek Liani Puspitasari untuk mengambil yang bukan hak nya, melawan Putusan 695/Pdt.G/2021/PN.Sby Jo No.189/Pdt.G/2022/PT.Sby Jo Putusan Mahkamah Agung&nbsp; No.553/PDT/PK/MARI yang dimenangkan keseluruhan oleh Soetijono, melalui Penasehat Hukum Dr Teguh Suharto Utomo,S.Psi,SH.MH.MM dari TSR Law Firm, menjelaskan Siek Liani Puspitasari telah mengajukan Perlawanan terhadap Putusan yang sudah Inkracht / atau BHT, dengan cara cara yang kurang terpuji yaitu mengajukan Gugatan Perlawanan No.1338/PDT.BTH/2025/PN.Sby lalu Putusan Banding No.774/PDT/2025/PT.Sby hingga terakhir Putusan Mahkamah Agung RI No.1358 K/PDT/2026, tgl 11 Mei 2026 dan Gugatan Perlawanan semuanya DITOLAK dari Pengadilan Negeri, Pengadilan Tiinggi hingga Mahkamah Agung RI, Majelis Hakim sudah sepakat menolak seluruh dalil dan alasan Siek Liani Puspitasari, menurut Dr Teguh Suharto Utomo seluruh dalil Siek Liani Puspitasari ini mengada ada, bahkan fitnah dan setelah Putusan Yang sudah Berkekuatan Hukum Tetap ini kami dapatkan, kami akan lakukan upaya hukum balik, baik secara Pidana maupun Perdata, seluruh dalil yang digunakan Palsu dan dengan adanya Putusan Inkracht ini jelas membuktikan tuduhan Siek Liani Puspitasari bohong dan tidak benar adanya, selain itu kami akan ajukan Eksekusi Pengosongan., kami berharap kepada Ketua Pengadilan Negeri Surabaya dan Kapolrestabes Surabaya agar memberikan atensi khusus untuk ini.</p>','XNN | SURABAYA - Berbagai upaya hukum Siek Liani Puspitasari untuk mengambil yang bukan hak nya, melawan Putusan 695/Pdt.G/2021/PN.Sby Jo No.189/Pdt.G',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a1dbed7f1694.jpg',65,'2026-06-03 22:57:11'),(61,'HIPMAB Kolaka Kawal Korban Dugaan Pencemaran Nama Baik, Desak Polda Sultra Usut Akun \"ARYA KOE\"','hipmab-kolaka-kawal-korban-dugaan-pencemaran-nama-baik-desak-polda-sultra-usut-akun-arya-koe','<p><span style=\"color: rgb(99, 74, 165); text-align: justify; font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Foto: Ketua hipmab kolaka bersama rekan di polda Sultra</span><br></p><p style=\"text-align: justify;\"><font color=\"#ce0000\">XNN | KENDARI</font> -Himpunan Mahasiswa Bombana Kolaka (HIPMAB Kolaka) memberikan pendampingan kepada korban dugaan pencemaran nama baik yang telah melaporkan kasusnya secara resmi ke Kepolisian Daerah Sulawesi Tenggara (Polda Sultra). Laporan tersebut berkaitan dengan dugaan penyebaran informasi melalui akun media sosial bernama \"ARYA KOE\" yang diduga telah merugikan korban secara pribadi maupun sosial.</p><p style=\"text-align: justify;\">Pendampingan yang dilakukan HIPMAB Kolaka merupakan bentuk komitmen organisasi dalam mengawal perlindungan hak-hak masyarakat serta memastikan proses penegakan hukum berjalan secara profesional, objektif, dan transparan.</p><p style=\"text-align: justify;\">Selain dugaan pencemaran nama baik, HIPMAB Kolaka juga menyoroti adanya konten yang diduga mengandung unsur SARA. Berdasarkan laporan yang diterima, akun \"ARYA KOE\" diduga memuat pernyataan yang menyinggung salah satu kelompok suku sehingga berpotensi menimbulkan keresahan serta mengganggu keharmonisan sosial di tengah masyarakat.</p><p style=\"text-align: justify;\">Ketua HIPMAB Kolaka menegaskan bahwa pihaknya mendesak aparat penegak hukum untuk melakukan penyelidikan secara menyeluruh guna mengungkap identitas pihak yang diduga berada di balik akun tersebut serta menindaklanjuti laporan korban sesuai mekanisme hukum yang berlaku.</p><p style=\"text-align: justify;\">\"Kami meminta Polda Sultra untuk menangani perkara ini secara profesional, objektif, dan transparan. Seluruh konten yang dilaporkan, baik yang berkaitan dengan dugaan pencemaran nama baik maupun dugaan unsur SARA, perlu didalami secara menyeluruh. Apabila terbukti terdapat pelanggaran hukum, maka pihak yang bertanggung jawab harus mempertanggungjawabkan perbuatannya sesuai ketentuan yang berlaku,\" tegasnya.</p><p style=\"text-align: justify;\">HIPMAB Kolaka menilai maraknya penggunaan akun anonim atau akun palsu untuk menyebarkan informasi yang belum terverifikasi tidak hanya berpotensi merugikan individu tertentu, tetapi juga dapat menciptakan keresahan sosial, memicu konflik di tengah masyarakat, serta mencederai etika dalam ruang digital. Oleh karena itu, organisasi tersebut berharap penanganan kasus ini dapat menjadi bagian dari upaya penegakan hukum terhadap berbagai bentuk pelanggaran yang terjadi di media sosial.</p><p style=\"text-align: justify;\">Korban yang didampingi HIPMAB Kolaka berharap laporan yang telah disampaikan dapat segera ditindaklanjuti sehingga seluruh fakta yang berkaitan dengan perkara tersebut dapat terungkap secara objektif melalui proses penyelidikan yang profesional dan berlandaskan hukum.</p><p style=\"text-align: justify;\">Selain mengawal proses hukum yang sedang berjalan, HIPMAB Kolaka juga mengajak masyarakat untuk lebih bijaksana dalam memanfaatkan media sosial dengan mengedepankan prinsip kehati-hatian, tanggung jawab, serta penghormatan terhadap hak dan martabat setiap individu. Kebebasan berekspresi, menurut organisasi tersebut, harus dilaksanakan dalam koridor hukum dan etika yang berlaku serta tidak digunakan untuk menyebarkan fitnah, ujaran kebencian, maupun konten yang berpotensi menyinggung identitas suku, agama, ras, dan antargolongan.</p><p style=\"text-align: justify;\">Sebagai bentuk komitmen terhadap tegaknya keadilan, HIPMAB Kolaka menyatakan akan terus memantau dan mengawal perkembangan perkara ini hingga terdapat kepastian hukum yang jelas. Organisasi menegaskan bahwa tidak boleh ada ruang bagi praktik penyebaran fitnah, informasi menyesatkan, pencemaran nama baik, maupun tindakan yang berpotensi memecah belah masyarakat melalui akun-akun palsu di media sosial.</p><p style=\"text-align: justify;\">\"Kami akan terus mengawal proses ini hingga tuntas. Penegakan hukum yang tegas dan berkeadilan sangat penting untuk memberikan perlindungan kepada masyarakat serta menjaga ketertiban, persatuan, dan kepercayaan publik terhadap supremasi hukum.”</p>','Foto: Ketua hipmab kolaka bersama rekan di polda SultraXNN | KENDARI -Himpunan Mahasiswa Bombana Kolaka (HIPMAB Kolaka) memberikan pendampingan kepada',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a1fe53a80071.jpeg',127,'2026-06-03 15:26:34'),(62,'Advokat Dr Teguh Suharto Utomo Laporan IS sudah naik Tahap Penyidikan! Andi harap kooperatif dan patuhi Hukum','advokat-dr-teguh-suharto-utomo-laporan-is-sudah-naik-tahap-penyidikan-andi-harap-kooperatif-dan-patuhi-hukum','<p style=\"text-align: justify; \"><font color=\"#3984c6\">Foto: Dr teguh suharto utomo </font></p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | SURABAYA</font> - Dugaan tindak pidana penipuan dan penggelapan investasi kembali dilaporkan ke Polrestabes Surabaya. Seorang warga berinisial IS mengaku dirugikan hingga Rp1,7 miliar oleh Andi Gunawan, rekan yang dikenalnya sejak 2015.</p><p style=\"text-align: justify; \">Berdasarkan informasi yang dihimpun, IS tertarik menanamkan modal setelah dijanjikan keuntungan 1 persen per bulan. Pada 2017-2018, dana diserahkan bertahap dengan total Rp1,7 miliar ke rekening Kadiano Gunawan, ayah kandung terlapor.</p><p style=\"text-align: justify; \">Namun keuntungan maupun dana pokok tak pernah dikembalikan. Sebagai pengganti, Andi Gunawan menyerahkan 2 lembar bilyet giro Bank BCA tertanggal 21 April 2025. BG pertama nomor EB 831670 senilai Rp1 miliar, BG kedua EB 831671 senilai Rp1,646 miliar.</p><p style=\"text-align: justify; \">Saat dicairkan di BCA Pakuwon City, kedua giro ditolak karena saldo rekening tidak mencukupi. Terlapor juga disebut tidak memiliki dana untuk memenuhi kewajibannya.</p><p style=\"text-align: justify; \">Merasa dirugikan, IS melaporkan kasus ini ke Polrestabes Surabaya. Laporan tercatat Nomor: LP/B/1118/X/2025/SPKT/Polrestabes Surabaya/Polda Jatim tertanggal 5 Oktober 2025 dengan dugaan Pasal 378 dan/atau Pasal 372 KUHP.</p><p style=\"text-align: justify; \">Advokat korban, Dr. Teguh Suharto Utomo, menyebut laporan kliennya sudah naik ke tahap penyidikan. “Laporan klien kami sudah naik penyidikan. Tegakkan hukum! Proses pelakunya!” ujarnya.</p><p style=\"text-align: justify; \">Hingga berita ini ditulis, terlapor belum memberikan keterangan resmi. Sesuai asas praduga tak bersalah, seluruh pihak yang disebut dianggap tidak bersalah sampai ada putusan pengadilan yang berkekuatan hukum tetap.</p>','Foto: Dr teguh suharto utomo XNN | SURABAYA - Dugaan tindak pidana penipuan dan penggelapan investasi kembali dilaporkan ke Polrestabes Surabaya. Seor',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a204cf701071.jpg',46,'2026-06-03 22:49:11'),(63,'KECELAKAAN DI DEPAN HOTEL VASA, MARLINCE VIOLA (5) LUKA BERAT. IBU AJUKAN GUGATAN GANTI RUGI','kecelakaan-di-hotel-vasa-anak-dibawah-umur-alami-luka-berat-advokat-dr-teguh-suharto-utomo-gugat-ganti-rugih','<p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#3984c6\">Foto: Tim TSR Law&nbsp; Firm dan Korban Laka</font></span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#ce0000\"> XNN | SURABAYA -</font>&nbsp;</span>Seorang bocah 5 tahun bernama Marlince Viola harus menjalani perawatan intensif usai menjadi korban kecelakaan lalu lintas di Jalan H.R. Muhammad, tepat di depan Hotel Vasa Surabaya, Rabu (20/5/2026) pagi. Korban mengalami luka berat di wajah dan diduga gegar otak.</p><p style=\"text-align: justify;\">Kronologi kecelakaan sempat terekam kamera dashcam milik salah satu pengendara. Video rekaman itu kemudian viral dan beredar luas di media sosial, memicu keprihatinan publik.</p><p style=\"text-align: justify;\">Berdasarkan informasi yang dihimpun, akibat benturan keras, Marlince Viola mengalami luaka parah di bagian kepala, trauma dan jugak wajah. Tim medis juga menduga korban mengalami gegar otak sehingga harus ditangani intensif di rumah sakit.</p><p style=\"text-align: justify;\">Sebagai langkah hukum awal, sang ibu bersama kuasa hukum resmi menandatangani Surat Kuasa. Penandatanganan dilakukan di hadapan advokat Dr. Teguh Suharto Utomo yang akan mewakili Marlince Viola dalam proses gugatan ganti rugi ke pengadilan.</p><p style=\"text-align: justify;\">\"Dengan adanya SK ini, kami resmi berwenang mendampingi kepentingan hukum Marlince Viola selama proses penyidikan hingga&nbsp; pengajuan gugatan ganti rugi di Pengadilan nanti dan Berkas akan segera kami lengkapi sesuai prosedur,\" terang Dr. Teguh Suharto Utomo, Muhammad, Wahyu Ferdiansyah,SH, Inka Fadilah,SH dan HERLINI YASTI STEFEN WEKA, S.H&nbsp; (3/6/2026).</p><p style=\"text-align: justify;\">Hingga berita ini ditulis, kronologi lengkap dan pihak yang bertanggung jawab atas kecelakaan masih dalam penyelidikan pihak kepolisian. Kuasa hukum memastikan akan mengawal kasus ini hingga tuntas demi pemulihan hak korban.</p><p style=\"text-align: justify;\">\"Sesuai asas praduga tak bersalah, seluruh pihak yang terkait dalam perkara ini dianggap tidak bersalah sampai adanya putusan pengadilan yang berkekuatan hukum tetap,\" tegas Dr. Teguh Suharto Utomo, Wahyu Ferdiansyah,SH, Inka Fadilah,SH dan HERLINI Y STEFEN WEKA, S.H</p>','XNN | SURABAYA - Seorang bocah 5 tahun bernama Marlince Viola harus menjalani perawatan intensif usai menjadi korban kecelakaan lalu lintas di Jalan H',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a206a048aa6e.jpg',59,'2026-06-04 00:53:08'),(64,'DR. TEGUH SUHARTO UTOMO, S.PSI., S.H., M.H., M.M.: TINJAUAN YURIDIS PUTUSAN PERKARA SOETIJONO – PERBUATAN TERBUKTI, NAMUN BUKAN TINDAK PIDANA','perkara-banding-dan-mahkamah-agung-selesai-soetijono-dilepaskan-dari-segala-tuntutan-hukum','<h6><font color=\"#3984c6\">Foto:&nbsp;Soetijono, terdakwa kasus penyerobotan lahan saat menjalani sidang di PN Surabaya beberapa waktu lalu.</font></h6><p><br></p><h6><span style=\"font-size: 1rem;\"><font color=\"#ce0000\">XNN | SURABAYA </font>- Penguatan Putusan Hingga Mahkamah Agung, Tuduhan Pelapor Dinilai Tidak Terbukti Sepenuhnya,&nbsp;</span><span style=\"font-size: 1rem;\">Perjalanan hukum yang menyertai Soetijono, yang dikenal luas sebagai pelaku usaha dan pemilik sejumlah Stasiun Pengisian Bahan Bakar Umum (SPBU), telah mencapai titik penyelesaian yang menyeluruh. Kasus ini bermula dari laporan yang disampaikan oleh Kurniawan Soedewo dengan sejumlah dalil dan tuduhan, namun setelah melalui pemeriksaan berjenjang di tiga tingkat peradilan, seluruh dakwaan dinilai tidak dapat dibuktikan sepenuhnya menurut ketentuan hukum yang berlaku.</span></h6><h6>&nbsp;</h6><h6>Putusan tingkat banding ditetapkan oleh Pengadilan Tinggi Surabaya melalui Nomor 196/PID/2015/PT SBY pada 11 Mei 2015, sebagai tindak lanjut dari putusan Pengadilan Negeri Surabaya Nomor 2148/Pid.B/2014/PN.Sby tertanggal 19 Januari 2015. Ketetapan ini kemudian diperkuat oleh Mahkamah Agung Republik Indonesia, sehingga kedudukan hukum serta nama baik Soetijono dipulihkan sepenuhnya.</h6><h6>&nbsp;</h6><h6>Menanggapi putusan hukum tersebut, Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M. memberikan uraian dan penilaian hukum yang mendalam serta komprehensif. Menurut beliau, keputusan yang diambil oleh majelis hakim di berbagai tingkatan ini merupakan bentuk penegakan keadilan yang sesungguhnya, di mana kebenaran materiil ditempatkan sebagai landasan utama di atas pertimbangan lainnya.</h6><h6>&nbsp;</h6><h6>“Putusan ini menjadi contoh nyata bahwa dalam sistem hukum kita, keberadaan suatu perbuatan secara fakta tidak serta-merta menjadikannya sebagai tindak pidana. Ada syarat mutlak yang harus dipenuhi, yaitu kesesuaian dengan unsur-unsur yang dirumuskan dalam undang-undang. Seseorang tidak dapat dipidana hanya karena perbuatannya diketahui terjadi, jika perbuatan tersebut tidak masuk dalam kualifikasi yang diatur hukum. Inilah bentuk perlindungan hukum yang menjamin kepastian dan rasa adil bagi seluruh warga negara,” ungkap Dr. Teguh.</h6><h6>&nbsp;</h6><h6>TAHAPAN PROSEDURAL PENYELESAIAN PERKARA</h6><h6>&nbsp;</h6><h6>Berdasarkan catatan administrasi hukum yang tersedia, permohonan banding diajukan oleh kedua belah pihak, baik dari Jaksa Penuntut Umum maupun pihak Terdakwa. Dalam proses persidangan tersebut, kepentingan hukum diwakili oleh kuasa hukum Djamin Susanto, S.H., sementara Soetijono juga bertindak selaku pembanding untuk kepentingan hukumnya sendiri.</h6><h6>&nbsp;</h6><h6>Alur proses berjalan sesuai mekanisme hukum acara yang berlaku, dengan rincian tahapan sebagai berikut:</h6><h6>&nbsp;</h6><h6>- Pemberitahuan permohonan banding: 26 Februari 2015</h6><h6>- Penerimaan memori banding: 3 Maret 2015</h6><h6>- Pemeriksaan berkas (inzage): 5 Maret 2015 bagi pihak penuntut dan 19 Maret 2015 bagi pihak terdakwa</h6><h6>- Pengiriman berkas lengkap ke Pengadilan Tinggi Surabaya: 1 April 2015, nomor surat W.14-U1/2454/HK.01/IV/2015</h6><h6>&nbsp;</h6><h6>Dr. Teguh menilai seluruh rangkaian ini telah berjalan secara tertib dan memenuhi asas hukum. “Setiap tahapan yang dilalui memberikan ruang yang setara bagi kedua belah pihak untuk menyampaikan dalil dan pembelaannya. Hal ini mencerminkan proses hukum yang transparan dan menjamin hak-hak hukum para pihak secara seimbang,” tambahnya.</h6><h6>&nbsp;</h6><h6>PERTIMBANGAN MATERIIL: ANTARA FAKTA DAN UNSUR HUKUM</h6><h6>&nbsp;</h6><h6>Setelah menelaah secara saksama seluruh dokumen, alat bukti tertulis, serta mendengarkan uraian para pihak, Majelis Hakim yang diketuai oleh H. Muhammad Tarid Palimari, S.H., M.H. beserta anggota menyampaikan kesimpulan hukumnya.</h6><h6>&nbsp;</h6><h6>Dalam pertimbangannya, majelis hakim menyatakan bahwa perbuatan yang dijadikan objek perkara memang terbukti dilakukan secara nyata. Namun secara yuridis, perbuatan tersebut tidak mengandung unsur-unsur yang sesuai dengan kualifikasi tindak pidana sebagaimana diatur dalam peraturan perundang-undangan. Hal ini sekaligus menjadi jawaban hukum yang jelas terhadap seluruh dalil yang disampaikan pelapor, yang pada akhirnya dinilai tidak memiliki landasan hukum yang cukup.</h6><h6>&nbsp;</h6><h6>Menyikapi hal tersebut, Dr. Teguh menjelaskan secara akademis.<span style=\"font-size: 1rem;\">“Dalam teori hukum pidana terdapat perbedaan yang sangat mendasar antara kenyataan kejadian dengan kualifikasi hukumnya. Adanya perbuatan hanyalah salah satu syarat, namun syarat yang paling utama adalah terpenuhinya seluruh unsur pasal yang didakwakan. Jika salah satu unsur tidak ada atau tidak terbukti, maka perbuatan tersebut tidak dapat dikategorikan sebagai tindak pidana. Keputusan melepaskan terdakwa dari segala tuntutan hukum dalam perkara ini sangat tepat dan sejalan dengan prinsip hukum yang berlaku, karena hakim telah memisahkan dengan jelas apa yang nyata terjadi dan apa yang dapat dipertanggungjawabkan secara pidana.”</span></h6><h6>&nbsp;</h6><h6>Berdasarkan analisis tersebut, majelis hakim menetapkan melepaskan Soetijono dari segala bentuk tuntutan hukum, serta memulihkan kedudukan, hak, harkat, dan martabatnya seperti keadaan semula sebelum tersangkut perkara ini. Keputusan ini sejalan dengan prinsip negara hukum yang menjamin perlindungan hak asasi dan kepastian hukum bagi setiap warga negaranya.</h6><h6>&nbsp;</h6><h6>PENGATURAN BARANG BUKTI DAN BEBAN BIAYA</h6><h6>&nbsp;</h6><h6>Dalam amar putusannya, ditetapkan pula status barang bukti yang terdiri dari dokumen pengampunan hak administrasi TNI Angkatan Laut, surat ukur tanah milik PT Senopati Samudra Perkasa, serta berkas administrasi dan surat keberatan ukur milik CV Lensa Informatika. Seluruh dokumen tersebut dikembalikan kepada pihak yang berhak, sedangkan biaya perkara dibebankan kepada keuangan negara.</h6><h6>&nbsp;</h6><h6>“Pengaturan ini juga telah sesuai dengan ketentuan hukum acara. Pengembalian barang bukti kepada pemilik yang sah serta pembebanan biaya kepada negara merupakan bagian dari penyelesaian yang utuh dan adil, sehingga tidak ada hak yang dirugikan maupun beban yang dipikul secara sepihak,” jelas Dr. Teguh.</h6><h6>&nbsp;</h6><h6>PENYELESAIAN ADMINISTRATIF DAN PENUTUPAN PERKARA</h6><h6>&nbsp;</h6><h6>Putusan resmi dibacakan oleh Panitera Pengganti Putut Djati Waluyo, S.H., M.H., kemudian seluruh berkas dikembalikan ke Pengadilan Negeri Surabaya pada 22 Juli 2015 untuk keperluan administrasi dan pencatatan. Dengan adanya penguatan di tingkat kasasi, maka seluruh proses hukum dinyatakan selesai dan berkekuatan hukum tetap.</h6><h6>&nbsp;</h6><h6>Dr. Teguh menutup pandangannya dengan menyatakan:<span style=\"font-size: 1rem;\">“Perkara ini memberikan pelajaran berharga bagi kita semua, bahwa penegakan hukum harus selalu berpijak pada fakta, bukti, dan ketentuan perundang-undangan. Tuduhan semata tidak cukup untuk menjatuhkan seseorang, dan kebenaran materiillah yang pada akhirnya akan menang dan melindungi hak-hak setiap warga negara.”</span></h6>','XNN | SURABAYA – Pengadilan Tinggi Surabaya dan MA Tegaskan: Perbuatan Terbukti, Namun Bukan Tindak Pidana jadi Harus Lepas Demi Hukum Kasus hukum y',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a20ee01e398c.jpeg',43,'2026-06-04 10:29:33'),(65,'Dr Teguh Suharto Utomo Waketum DPN Peradi mengucapkan selamat dan sukses buat Adinda Ito Lawputra dilantik sebagai Ketua DPC PERADI PALU, DOA dan Harapan teriring Peradi Kota Palu semakin besar','dr-teguh-suharto-utomo-waketum-dpn-peradi-mengucapkan-selamat-dan-sukses-buat-adinda-ito-lawputra-dilantik-sebagai-ketua-dpc-peradi-palu-doa-dan-harapan-teriring-peradi-kota-palu-semakin-besar','<p><font color=\"#3984c6\">Foto: Pelantikan pengurus dewan pimpinan peradi kota palu</font></p><p style=\"text-align: justify; \"><font color=\"#9c0000\">XNN | PALU –</font> Dewan Pimpinan Cabang (DPC) Perhimpunan Advokat Indonesia (Peradi) Kota Palu periode 2026–2030 resmi dilantik oleh Ketua Umum Dewan Pimpinan Nasional (DPN) Peradi, Dr. Imam Hidayat, S.H., M.H., di Aula Milenium Waterpark Palu, Selasa (2/6/2026).</p><p style=\"text-align: justify;\">Pelantikan turut dihadiri Sekretaris Jenderal DPN Peradi, Alam P. Simamora, S.H., M.H., serta unsur penegak hukum dan berbagai lembaga di Sulawesi Tengah. Prosesi diawali dengan pembacaan Surat Keputusan penetapan pengurus DPC Peradi Kota Palu, dilanjutkan dengan pengucapan sumpah jabatan yang dipimpin langsung oleh Ketua Umum DPN Peradi.</p><p style=\"text-align: justify;\"><br></p><p style=\"text-align: justify; \">Kepengurusan DPC Peradi Kota Palu dipimpin oleh Ito Lawputra, S.H., S.I.Kom., M.H., C.Med., CTA sebagai ketua. Rusman Andhika, S.H. sebagai Sekretaris, Rukly Chahyadi, S.H. sebagai Bendahara, Muhammad Rexy, S.H. sebagai Koordinator Bidang, serta Anak Agung Gede Ngurah Oka P, S.H. sebagai Dewan Penasehat.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Dalam sambutannya, Ito menegaskan, kehadiran Peradi tidak semata-mata untuk mendampingi masyarakat di ruang persidangan, tetapi juga mendorong penyelesaian persoalan hukum melalui pendekatan yang lebih konstruktif.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Menurutnya, advokat memiliki tanggung jawab untuk memastikan masyarakat memperoleh akses terhadap keadilan, baik melalui jalur litigasi maupun penyelesaian sengketa secara musyawarah dan mediasi.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">“Keadilan merupakan prinsip yang harus diperjuangkan. Tidak semua persoalan harus berakhir di pengadilan. Dalam banyak kasus, musyawarah dan mufakat juga menjadi jalan untuk menghadirkan keadilan bagi para pihak,” ujarnya.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Ito berharap kepengurusan yang baru dapat membangun kemitraan dengan berbagai elemen di Kota Palu, guna memperkuat supremasi hukum dan memperluas layanan bantuan hukum bagi masyarakat.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Pemerintah Kota Palu menyambut positif terbentuknya kepengurusan baru DPC Peradi Kota Palu. Wali Kota Palu dalam sambutan tertulisnya yang dibacakan Asisten Bidang Pemerintahan dan Kesejahteraan Rakyat, Usman mengatakan, organisasi advokat memiliki peran penting dalam melindungi hak-hak warga dan memperjuangkan akses terhadap keadilan, terutama bagi kelompok masyarakat yang rentan.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Pemerintah Kota Palu juga berharap Peradi dapat hadir lebih dekat dengan masyarakat melalui penyuluhan, pendampingan, serta edukasi hukum yang berkelanjutan, tidak hanya berfokus pada pendampingan perkara di pengadilan.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Sementara itu, Ketua Umum DPN Peradi, Dr. Imam Hidayat, menekankan pentingnya peran advokat sebagai salah satu pilar penegakan hukum. Ia mendorong DPC Peradi Kota Palu untuk membangun sinergi dengan aparat penegak hukum sekaligus memperkuat kegiatan pendidikan dan penyuluhan hukum kepada masyarakat.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">“Kehadiran DPC Peradi Kota Palu harus menjadi bagian dari upaya meningkatkan kesadaran hukum masyarakat. Jangan lelah memberikan pendidikan dan penyuluhan hukum agar masyarakat memahami hak dan kewajibannya,” katanya.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Terpisah, ucapan selamat juga hadir dari Wakil Ketua Umum DPN Peradi, Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M. Dirinya menyampaikan apresiasi sekaligus ucapan selamat atas terbentuk dan akan dilantiknya kepengurusan baru DPC Peradi Kota Palu.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Dr. Teguh S. Utomo menegaskan pentingnya peran DPC Peradi Kota Palu sebagai ujung tombak organisasi dalam menjaga marwah profesi advokat di daerah.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">“Saya mengucapkan selamat dan sukses atas pelantikan Pengurus DPC Peradi Kota Palu. Momentum ini harus menjadi langkah awal yang kuat untuk menegaskan kembali komitmen kita sebagai officium nobile—profesi yang mulia. Saya berharap kepengurusan yang baru mampu mengemban amanah ini dengan penuh tanggung jawab, integritas, dan profesionalisme,” ujar Dr. Teguh.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Selain melantik pengurus baru, kegiatan tersebut juga menjadi momentum memperkuat kolaborasi antara organisasi advokat, pemerintah daerah, dan aparat penegak hukum dalam mendorong pelayanan hukum yang lebih mudah diakses masyarakat.</p><p style=\"text-align: justify; margin: 0px 0px 15px; overflow-wrap: break-word; color: rgb(68, 68, 68); font-family: Roboto, &quot;Helvetica Neue&quot;, sans-serif;\">Acara pelantikan dihadiri perwakilan Kejaksaan Tinggi Sulawesi Tengah, Kejaksaan Negeri Palu, Pengadilan Negeri, Pengadilan Agama, Polresta Palu, APINDO Sulawesi Tengah, PSMTI Sulawesi Tengah, STAH Dharma Sentana, serta sejumlah tamu undangan lainnya.</p>','Foto: Pelantikan pengurus dewan pimpinan peradi kota paluXNN | PALU – Dewan Pimpinan Cabang (DPC) Perhimpunan Advokat Indonesia (Peradi) Kota Palu p',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a20f3e164e81.jpg',21,'2026-06-04 10:41:21'),(66,'SOMASI ALI SELAMAT DINILAI TIDAK TEPAT, FOKUS SEHARUSNYA PADA DUGAAN PENYALAHGUNAAN ASET WARISAN','somasi-ali-selamat-dinilai-tidak-tepat-fokus-seharusnya-pada-dugaan-penyalahgunaan-aset-warisan','<p><br></p><p style=\"text-align: justify;\">Putusan Pengadilan Telah Inkracht, Ali Selamat Bahkan Telah Dilaporkan ke Polisi dan Perkaranya Naik ke Tahap Penyidikan</p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | MAKASSAR </font>– Sengketa warisan yang telah melalui proses hukum panjang hingga memperoleh putusan berkekuatan hukum tetap (inkracht van gewijsde) kembali menjadi sorotan setelah munculnya somasi yang dilayangkan oleh Ali Selamat kepada Lyana Lisana.</p><p style=\"text-align: justify;\">Perkara warisan tersebut sebelumnya telah diperiksa secara berjenjang mulai dari Pengadilan Negeri hingga tingkat kasasi di Mahkamah Agung Republik Indonesia. Dalam seluruh proses tersebut, hak-hak Lyana Lisana sebagai ahli waris telah diakui dan dilindungi oleh putusan pengadilan yang telah berkekuatan hukum tetap.</p><p style=\"text-align: justify;\">Kuasa hukum ahli waris, Teguh Suharto Utomo, menegaskan bahwa langkah somasi yang dilakukan Ali Selamat justru bertentangan dengan semangat kepastian hukum yang telah ditegakkan melalui putusan pengadilan.</p><p style=\"text-align: justify;\">Menurutnya, putusan Pengadilan Negeri hingga Mahkamah Agung RI secara tegas menyatakan bahwa Lyana Lisana memiliki hak waris atas aset berupa rumah di Jalan Mochtar Luthfi serta hak atas aset yang berkaitan dengan Hotel M Regency. Oleh karena itu, upaya-upaya yang berpotensi mengingkari putusan tersebut dinilai tidak memiliki dasar yang kuat.</p><p style=\"text-align: justify;\">Somasi Disebar ke Publik, Dinilai Bertujuan Mempermalukan Ahli Waris</p><p style=\"text-align: justify;\">Dr. Teguh juga menyoroti penyebaran surat somasi yang dilakukan Ali Selamat kepada khalayak umum serta ditembuskan kepada sejumlah pihak yang dinilai tidak memiliki relevansi langsung dengan pokok sengketa.</p><p style=\"text-align: justify;\">Menurutnya, tindakan tersebut patut diduga bertujuan membentuk opini negatif dan mempermalukan Lyana Lisana di hadapan publik, padahal yang bersangkutan hanya sedang memperjuangkan hak-haknya berdasarkan putusan pengadilan yang sah dan mengikat.</p><p style=\"text-align: justify;\">“Somasi seharusnya menjadi sarana komunikasi hukum yang proporsional, bukan alat untuk membangun stigma atau mempermalukan pihak lain di ruang publik. Terlebih ketika hak-hak Lyana Lisana telah ditegaskan oleh putusan pengadilan sampai tingkat Mahkamah Agung,” ujar Dr. Teguh.</p><p style=\"text-align: justify;\">Ali Selamat Telah Dilaporkan ke Polisi</p><p style=\"text-align: justify;\">Lebih lanjut, Dr. Teguh mengungkapkan bahwa Ali Selamat sendiri telah dilaporkan ke pihak kepolisian terkait dugaan perbuatan yang berhubungan dengan pengelolaan aset warisan.</p><p style=\"text-align: justify;\">Laporan tersebut tercatat dengan LP Nomor: 1034/V/2026/Polrestabes Makassar tanggal 23 Mei 2026, dan saat ini perkara tersebut telah ditingkatkan ke tahap penyidikan.</p><p style=\"text-align: justify;\">Menurut Dr. Teguh, perkembangan hukum tersebut menunjukkan bahwa persoalan utama yang semestinya menjadi perhatian adalah dugaan tindakan terhadap aset-aset warisan yang masih menjadi hak bersama para ahli waris, bukan justru menyerang pihak yang sedang memperjuangkan haknya berdasarkan putusan pengadilan.</p><p style=\"text-align: justify;\">Dugaan Penjaminan dan Pengalihan Aset Warisan</p><p style=\"text-align: justify;\">Dalam perkara ini juga muncul dugaan bahwa sejumlah aset warisan telah dijaminkan kepada pihak perbankan tanpa persetujuan seluruh ahli waris yang berhak. Selain itu, terdapat informasi mengenai dugaan pengalihan atau pemindahtanganan aset kepada pihak ketiga secara sepihak.</p><p style=\"text-align: justify;\">Apabila terbukti, tindakan tersebut berpotensi menimbulkan kerugian bagi ahli waris lainnya karena aset warisan merupakan hak bersama yang tidak dapat dikelola atau dialihkan secara sepihak tanpa persetujuan pihak-pihak yang berhak.</p><p style=\"text-align: justify;\">Hormati Putusan yang Telah Inkracht</p><p style=\"text-align: justify;\">Dr. Teguh menegaskan bahwa seluruh pihak semestinya menghormati putusan pengadilan yang telah berkekuatan hukum tetap dan mengedepankan penyelesaian yang berlandaskan hukum.</p><p style=\"text-align: justify;\">“Fokus penyelesaian sengketa seharusnya diarahkan pada pertanggungjawaban atas dugaan penguasaan, penjaminan, maupun pengalihan aset warisan yang dilakukan tanpa hak. Bukan dengan menyebarkan somasi kepada publik untuk menyerang pihak yang sedang memperjuangkan haknya berdasarkan putusan pengadilan yang telah inkracht,” tegasnya.</p><p style=\"text-align: justify; \">Ia berharap seluruh proses hukum yang sedang berjalan dapat memberikan kepastian, keadilan, dan perlindungan terhadap hak-hak seluruh ahli waris sebagaimana telah ditegaskan dalam putusan pengadilan yang berkekuatan hukum tetap.</p>','Putusan Pengadilan Telah Inkracht, Ali Selamat Bahkan Telah Dilaporkan ke Polisi dan Perkaranya Naik ke Tahap PenyidikanXNN | MAKASSAR – Sengketa wa',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a21afbcbb4db.png',58,'2026-06-05 00:02:52'),(67,'WAKIL KETUA KONI KOTA BATU SINAL ABIDIN DILAPORKAN DUGAAN PENGEROYOKAN, PERISTIWA DI DEPAN GEDUNG SERBAGUNA DADAPREJO','wakil-ketua-koni-kota-batu-sinal-abidin-dilaporkan-dugaan-pengeroyokan-peristiwa-di-depan-gedung-serbaguna-dadaprejo','<p><font color=\"#ce0000\" style=\"text-align: justify;\"><br></font></p><p><font color=\"#ce0000\" style=\"text-align: justify;\">XNN | KOTA BATU -</font><span style=\"text-align: justify;\"> Wakil Ketua Umum KONI Kota Batu, Sinal Abidin,  MM, dilaporkan ke Polres Batu terkait dugaan tindak pidana pengeroyokan. Laporan teregister dengan nomor STTLPM/358/VI/2026/SPKT/Polres Batu/Polda Jawa Timur.</span></p><p style=\"text-align: justify; \">Pelapor bernama Ronny Christian, 39 tahun, warga Jl. Suropati 5 1 D RT 01 RW 12 Kel. Ngaglik Kota Batu. Dalam STTLP tertanggal 2 Juni 2026, peristiwa diduga terjadi Selasa 2 Juni 2026 sekira pukul 00.30 WIB di depan gedung serbaguna Ds. Dadaprejo Kec. Junrejo Kota Batu.</p><p style=\"text-align: justify; \">Berdasarkan uraian dalam STTLP, awalnya pelapor dihampiri oleh Sdr. Hari dan Sdr. Martin usai pertandingan bulu tangkis. Pelapor mengaku tidak ada masalah. Namun komunikasi memanas hingga terjadi dorongan dan pemukulan.</p><p style=\"text-align: justify; \">Dalam laporan itu disebut Sdr. Sinal Abidin juga mendorong pelapor di bagian dada. Kemudian Sdr. Hari memukul bagian kepala samping kiri belakang. Setelah itu Sdr. Sinal Abidin memukul muka pelapor dengan tangan terbuka sambil memaki. Sdr. Martin juga ikut mendorong dan memukul bagian muka. Akibatnya pelapor mengalami pusing, mual, dan sakit di bagian kepala belakang.</p><p style=\"text-align: justify; \">Dalam STTLP, pihak terlapor yang disebut: SINAL ABIDIN, HARI, MARTIN. Status hukum para terlapor saat ini masih dalam tahap penyelidikan Polres Batu.</p><p style=\"text-align: justify; \">Sinal Abidin diketahui publik Kota Batu sebagai mantan Kepala Dinas Koperindag Pemkot Kota Batu. Berdasarkan data SIPP Mahkamah Agung RI, pada Selasa 17 April 2018 ia divonis Pengadilan Tipikor pidana penjara 1 tahun 8 bulan dan denda Rp50 juta subsidair 2 bulan kurungan karena terbukti korupsi secara bersama-sama. Saat ini ia menjabat Wakil Ketua Umum KONI Kota Batu.</p><p style=\"text-align: justify; \">Redaksi menjunjung asas praduga tak bersalah. Setiap orang dianggap tidak bersalah sampai ada putusan pengadilan berkekuatan hukum tetap.</p><p style=\"text-align: justify; \"> telah berupaya mengonfirmasi kebenaran STTLP, kronologi, dan langkah hukum selanjutnya ke Kasi Humas Polres Batu, pihak pelapor Ronny Christian, serta Sinal Abidin dan pengurus KONI Kota Batu. Konfirmasi resmi masih ditunggu.</p><p style=\"text-align: justify; \">Sesuai UU Pers No. 40/1999, redaksi membuka ruang hak jawab dan hak koreksi seluas-luasnya bagi para terlapor dan pihak terkait untuk menyampaikan versi kejadian.</p>','XNN | KOTA BATU - Wakil Ketua Umum KONI Kota Batu, Sinal Abidin,  MM, dilaporkan ke Polres Batu terkait dugaan tindak pidana pengeroyokan. Laporan ter',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a22dd3716c83.jpg',48,'2026-06-05 21:29:11'),(68,'Tagihan Ratusan Juta Rupiah Belum Lunas, Advokat Dr Teguh Suharto Utomo,S.Psi,SH,MH,MM, PT Sucofindo Harus tanggung jawab!','tagihan-ratusan-juta-rupiah-belum-lunas-advokat-dr-teguh-suharto-utomo-s-psi-sh-mh-mm-pt-sucofindo-harus-tanggung-jawab','<p><br></p><p style=\"text-align: justify;\"><font color=\"#ce0000\">XNN | SURABAYA&nbsp;</font>– Kantor Hukum Kharisma Law Firm under TSR Law Firm Surabaya &nbsp;melayangkan surat undangan klarifikasi kepada Syaifullah yang disebut sebagai bagian Divisi Umum PT Sucofindo Surabaya terkait sisa pembayaran sejumlah invoice jasa perjalanan dinas dan sewa kendaraan yang hingga kini belum terselesaikan.</p><p style=\"text-align: justify;\">Surat undangan bernomor 003/UND-KHARISMA/IX/2025 tersebut ditandatangani oleh Dr. Teguh S. Utomo, S.Psi., S.H., M.H., M.M. dan Herlini Yasti Stefen Weka, S.H., selaku kuasa hukum Ricko Anes Ratulangie, pemilik perusahaan jasa perjalanan (travel).</p><p style=\"text-align: justify;\">Dalam surat tersebut, Syaifullah diundang untuk hadir dalam pertemuan klarifikasi yang dijadwalkan pada Jumat, 26 September 2025 pukul 10.00 WIB di Kantor Kharisma Law Firm, Jalan Kertajaya Nomor 84, Kecamatan Gubeng, Surabaya.</p><p style=\"text-align: justify;\">Menurut keterangan pihak kuasa hukum, Syaifullah diduga melakukan pemesanan tiket pesawat, hotel, dan kebutuhan perjalanan lainnya untuk keperluan rombongan dari PT Sucofindo. Akumulasi pemesanan tersebut mengakibatkan tagihan mencapai hampir Rp500 juta.</p><p style=\"text-align: justify;\">Karena pembayaran tidak kunjung diselesaikan, pihak Ricko Anes Ratulangie melalui kuasa hukumnya sempat melayangkan somasi. Setelah somasi tersebut, disebutkan bahwa baru sebagian tagihan yang dibayarkan, yakni sebesar Rp184.802.100 untuk salah satu invoice.</p><p style=\"text-align: justify;\">Adapun rincian invoice yang masih menjadi permasalahan antara lain:</p><p style=\"text-align: justify;\">Invoice sewa mobil KRB SCU00001 tertanggal 16 Juni 2025 sebesar Rp30.962.400;</p><p style=\"text-align: justify;\">Invoice tiket dan hotel INV/2025/C0067 tertanggal 16 Juni 2025 sebesar Rp184.805.000 (telah dibayar sebagian besar);</p><p style=\"text-align: justify;\">Invoice tiket dan hotel INV/2025/C0129 tertanggal 2 Oktober 2025 sebesar Rp188.130.000;</p><p style=\"text-align: justify;\">Invoice sewa mobil KRB SCU000100 sebesar Rp38.268.000.</p><p style=\"text-align: justify;\">Berdasarkan perhitungan pihak Ricko Anes Ratulangie, setelah pembayaran sebesar Rp184.802.100 tersebut, masih terdapat Nota lain &nbsp;yang belum dibayar sama sekali ekitar Rp257.360.400 atau sekitar Rp260 juta.</p><p style=\"text-align: justify;\">Kuasa hukum berharap pertemuan klarifikasi dapat menjadi sarana penyelesaian secara baik dan memberikan kepastian terkait pembayaran tagihan yang masih tertunggak.</p><p style=\"text-align: justify;\">Selain itu, pihak kuasa hukum menyebut bahwa Syaifullah yang mengaku sebagai bagian Divisi Umum PT Sucofindo yang berkantor di Jalan Kalibutuh No. 215 Surabaya dinilai sulit untuk ditemui dan menghindar &nbsp;untuk membahas penyelesaian tagihan tersebut.</p><p style=\"text-align: justify;\">Hingga berita ini ditulis, belum ada keterangan atau tanggapan resmi dari pihak PT Sucofindo maupun Syaifullah terkait undangan klarifikasi dan klaim tunggakan pembayaran yang disampaikan oleh pihak kuasa hukum Ricko Anes Ratulangie.</p>','XNN | SURABAYA&nbsp;– Kantor Hukum Kharisma Law Firm under TSR Law Firm Surabaya &nbsp;melayangkan surat undangan klarifikasi kepada Syaifullah yang',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a23294fd623c.jpeg',43,'2026-06-06 02:53:51'),(69,'Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M. (Direktur Lawfirm TSR): Menang di Atas Kertas Penyalahgunaan Partij Verzet Ancam Asas Kepastian Hukum & Executio Rei Iudicatae','dr-teguh-suharto-utomo-s-psi-s-h-m-h-m-m-direktur-lawfirm-tsr-menang-di-atas-kertas-penyalahgunaan-partij-verzet-ancam-asas-kepastian-hukum-executio-rei-iudicatae','<p>Analisis Singkat: Celah Normatif, Doktrin Misbruik van Procesrecht, dan Batas Sah Perlawanan Pihak</p><p><font color=\"#ce0000\">XNN | SURABAYA</font> - 06 Juni 2026 Putusan perdata yang telah berkekuatan hukum tetap (Inkracht van Gewijsde) belum menjamin keadilan tercapai sepenuhnya. Ironi hukum kerap terjadi: kemenangan di pengadilan hanya menjadi tulisan di atas kertas, karena tahap eksekusi dijegal lewat pengajuan Partij Verzet (perlawanan pihak) tanpa dasar yang sah.</p><p>Menurut Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M. selaku Direktur Lawfirm TSR, instrumen hukum yang sejatinya melindungi hak pembelaan diri (audi et alteram partem) kini kerap bergeser fungsi menjadi taktik penundaan proses (dilatory defense), yang mencederai prinsip Executio Rei Iudicatae—kewajiban melaksanakan putusan.</p><p>Disonansi Aturan: Celah yang Dimanfaatkan Secara normatif, Pasal 207 ayat (3) HIR menegaskan perlawanan tidak otomatis menangguhkan eksekusi (non suspensive). Namun, Pedoman Administrasi Peradilan Perdata membuka ruang penangguhan jika perlawanan dianggap beralasan, yang diperkuat praktik kehati‑hatian hakim. Meski diatur SK Dirjen Badilum No.40/2019 agar bersifat kasuistik, ketidaksinkronan ini menciptakan zona abu‑abu yang disalahgunakan. Ditambah lagi risiko terputusnya pemahaman perkara saat terjadi pergantian hakim, kepastian hukum (rechtszekerheid) pun runtuh.</p><p>Doktrin Misbruik van Procesrecht: Penyalahgunaan Hak Prosedural,Dr. Teguh menegaskan fenomena ini sesuai doktrin hukum Belanda Misbruik van Procesrecht (penyalahgunaan hukum acara), turunan dari larangan penyalahgunaan wewenang (Misbruik van Bevoegdheid). Merujuk yurisprudensi Hoge Raad 26 Juni 1959, instrumen hukum yang diajukan semata untuk merugikan lawan atau mengulur waktu—tanpa tujuan mencari kebenaran—harus dinyatakan Tidak Dapat Diterima (NOV).</p><p>“Hak mengajukan perlawanan bukan mutlak. Ia harus sesuai tujuannya (recht moet worden uitgeoefend overeenkomstig haar bestemming). Jika hanya menjegal eksekusi, hilanglah kepentingan hukumnya (gebrek aan procesbelang) dan kapasitasnya sebagai gugatan sah,” urai Dr. Teguh.</p><p>Batasan Sah Berdasarkan SEMA No.7/2012</p><p>Berdasarkan Surat Edaran Mahkamah Agung, perlawanan pihak hanya beralasan sah jika didasarkan pada dua kondisi:</p><p>1.&nbsp;Pihak tereksekusi telah memenuhi kewajiban sesuai amar putusan (volledige nakoming); atau</p><p>2.&nbsp;Terjadi kesalahan prosedural penyitaan/ketidaksesuaian objek (onregelmatigheid in het beslag).</p><p>Di luar koridor ini, perlawanan adalah akal‑akalan hukum yang melanggar asas Rechtskracht van Gewijsde (kekuatan mengikat putusan), karena berupaya mengulang pokok perkara yang sudah selesai diperiksa.</p><p>Kesimpulan &amp; Rekomendasi</p><p>Dr. Teguh mengingatkan prinsip kuno Litis Finiri Oportet: setiap sengketa harus ada akhirnya. Penyalahgunaan Partij Verzet menghambat tujuan hukum itu sendiri.</p><p>“Pembaruan hukum acara mendesak mengadopsi larangan penyalahgunaan hukum acara dan mekanisme penyaringan gugatan (pretrial). Sudah saatnya kemenangan tidak hanya ada di atas kertas, tetapi berujung pada pelaksanaan putusan yang nyata dan berkeadilan,” pungkasnya.</p>','Analisis Singkat: Celah Normatif, Doktrin Misbruik van Procesrecht, dan Batas Sah Perlawanan PihakXNN | SURABAYA - 06 Juni 2026 Putusan perdata yang t',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a2434a17886e.jpg',39,'2026-06-06 21:54:25'),(70,'Tersangka Kasus Mafia Tanah Mojokerto Judy Puwastuti, SH Meninggal Dunia; Dr. Teguh Suharto Utomo, S.Psi, SH, MH, MM: Kami Akan Tuntut Ganti Rugi ke Ahli Waris dan Kejar Dalang di Baliknya','tersangka-kasus-mafia-tanah-mojokerto-judy-puwastuti-sh-meninggal-dunia-dr-teguh-suharto-utomo-s-psi-sh-mh-mm-kami-akan-tuntut-ganti-rugi-ke-ahli-waris-dan-kejar-dalang-di-baliknya','<p style=\"text-align: justify; \">Dinamika Hukum Pasca Kematian Tersangka: Gugurnya Status Pidana dan Langkah Pemulihan Hak</p><p style=\"text-align: justify; \"><font color=\"#9c0000\">XNN | MOJOKERTO</font> – Kabar duka sekaligus dinamika hukum baru menyelimuti kasus sengketa pertanahan di wilayah Kabupaten Mojokerto. Judy Puwastuti, SH, yang berstatus tersangka dalam perkara dugaan tindak pidana pertanahan, dikabarkan resmi meninggal dunia pada hari ini, Sabtu, 6 Juni 2026. Berpulangnya tersangka ini membawa implikasi hukum yang signifikan terhadap jalannya perkara, sekaligus membuka babak baru dalam upaya penegakan hukum dan pencarian keadilan bagi pihak korban.</p><p style=\"text-align: justify; \">Gugurnya Status Tersangka dan Implikasi Hukum</p><p style=\"text-align: justify; \">Berdasarkan ketentuan hukum acara pidana yang berlaku di Indonesia, meninggalnya seseorang yang sedang berstatus tersangka mengakibatkan gugurnya status hukum tersebut serta berakhirnya proses pidana yang dijalani. Hal ini dikarenakan tanggung jawab pidana bersifat pribadi, melekat pada diri individu, dan tidak dapat diwariskan kepada ahli waris maupun pihak lain.</p><p style=\"text-align: justify; \">Kendati demikian, berakhirnya proses pidana terhadap almarhum tidak serta‑merta memadamkan atau menghapuskan upaya hukum yang dilakukan oleh pihak yang dirugikan. Rosaleny Martianus, yang menjadi korban utama dari perbuatan yang diduga dilakukan oleh almarhum Judy Puwastuti, telah menempuh jalur hukum dan didampingi oleh tim pengacara.</p><p style=\"text-align: justify; \">Kuasa Hukum Rosaleny sekaligus Wakil Ketua Umum Dewan Pimpinan Nasional PERADI, Dr. Teguh Suharto Utomo, S.Psi, SH, MH, MM, menyampaikan rasa belasungkawa mendalam atas berpulangnya almarhum, namun menegaskan bahwa upaya pencarian keadilan bagi kliennya tidak berhenti di sini.</p><p style=\"text-align: justify; \">\"Kami menyampaikan rasa duka cita yang mendalam dan turut berbelasungkawa atas meninggalnya Ibu Judy Puwastuti, SH. Sebagai manusia biasa, kami tetap mengedepankan nilai kemanusiaan di tengah persoalan hukum yang besar yang ada di antara kami,\" ungkap Dr. Teguh dalam keterangan persnya, Sabtu sore.</p><p style=\"text-align: justify; \">Meski status tersangka gugur karena kematian, Dr. Teguh menegaskan bahwa dampak hukum dan tanggung jawab atas kerugian materiil maupun immateriil yang telah diderita kliennya tetap harus dipertanggungjawabkan melalui jalur hukum lain yang tersedia. Menurutnya, gugurnya proses pidana terhadap almarhum tidak menghapus hak konstitusional korban untuk menuntut pemulihan hak dan ganti rugi atas kerugian yang timbul.</p><p style=\"text-align: justify; \">\"Dalam pandangan hukum, meninggalnya tersangka memang menghentikan proses pidana. Namun, kerugian nyata yang dialami oleh klien kami, Rosaleny Martianus, tetap ada, terbukti, dan harus dipulihkan sepenuhnya. Oleh karena itu, kami akan mengambil langkah‑langkah hukum yang tepat untuk menuntut pertanggungjawaban perdata dan ganti rugi tersebut kepada keluarga serta para ahli waris dari almarhum Judy Puwastuti,\" tegasnya.</p><p style=\"text-align: justify; \">Indikasi Jaringan Mafia Tanah dan Peran Oknum Kepala Desa</p><p style=\"text-align: justify; \">Lebih jauh, Dr. Teguh mengungkapkan bahwa kasus ini memiliki jaring yang sangat luas dan mengarah pada praktik‑praktik sistematis yang diduga kuat sebagai bagian dari jaringan mafia tanah yang beroperasi di wilayah tersebut. Berdasarkan hasil penelusuran, pengumpulan data, dan bukti‑bukti otentik yang dikumpulkan selama proses hukum berjalan, terindikasi adanya pihak lain yang berperan besar sebagai aktor di balik layar yang turut serta dan menikmati keuntungan besar dalam kasus ini.</p><p style=\"text-align: justify; \">Ada dugaan kuat bahwa pelaku utama di balik transaksi tanah yang bermasalah tersebut adalah seorang oknum yang saat ini masih menjabat sebagai Kepala Desa di wilayah sekitar Kabupaten Mojokerto. Oknum tersebut diduga telah membeli aset tanah yang menjadi objek sengketa dari almarhum Judy Puwastuti tanpa dilengkapi bukti kepemilikan yang sah, dokumen pertanahan yang lengkap, alas hak yang jelas, maupun prosedur peralihan hak yang sesuai dengan peraturan perundang‑undangan.</p><p style=\"text-align: justify; \">\"Terungkap fakta hukum yang sangat jelas bahwa tanah milik sah klien kami ini dikuasai dan dibeli oleh seorang oknum Kepala Desa setempat dari almarhum Judy Puwastuti, tanpa dasar hukum yang jelas, tanpa alas hak yang sah, dan tanpa bukti‑bukti otentik kepemilikan. Dengan meninggalnya almarhum Judy Puwastuti, maka secara otomatis, gugur dan hilanglah pula dasar hak atau alas hak yang selama ini dijadikan satu‑satunya pegangan oleh oknum Kepala Desa tersebut untuk menguasai tanah itu. Artinya, saat ini oknum tersebut sama sekali tidak memiliki landasan hukum apa pun atas tanah yang ia kuasai dan tempati,\" papar Dr. Teguh.</p><p style=\"text-align: justify; \">Hilangnya Alas Hak dan Imbauan Itikad Baik</p><p style=\"text-align: justify; \">Menanggapi situasi hukum yang kini semakin terang dan melemahkan posisi hukum pihak lawan tersebut, Dr. Teguh menyampaikan imbauan keras namun tetap berlandaskan prinsip keadilan dan kemanusiaan kepada oknum Kepala Desa yang dimaksud. Ia meminta agar pihak terkait segera menyadari posisi hukumnya yang kini sangat lemah dan tidak memiliki pijakan sama sekali di mata hukum.</p><p style=\"text-align: justify; \">\"Kami menghimbau secara tegas namun penuh kesabaran kepada oknum Kepala Desa tersebut untuk segera menunjukkan itikad baik yang nyata dan terbuka. Kami minta ia berani mengakui kesalahannya, meminta maaf secara terbuka maupun melalui jalur hukum kepada klien kami, dan bersedia mengganti seluruh kerugian yang telah diderita Rosaleny Martianus akibat perbuatan‑perbuatan yang melanggar hukum ini,\" ujarnya.</p><p style=\"text-align: justify; \">Imbauan ini bukan tanpa konsekuensi hukum. Dr. Teguh menegaskan, jika imbauan ini tidak diindahkan dan oknum Kepala Desa tersebut tetap bertahan menguasai aset tanpa hak serta tidak mau berdamai atau menyelesaikan secara kekeluargaan, maka pihaknya tidak akan ragu menempuh seluruh jalur hukum yang tersedia dan mempertanggungjawabkan segala perbuatannya hingga tuntas.</p><p style=\"text-align: justify; \">\"Apabila imbauan ini diabaikan dan itikad baik tidak ditunjukkan, maka kami akan melakukan segala upaya hukum yang ada dan kami kuasai. Kami tidak segan untuk melaporkan dan menuntut secara pidana maupun perdata. Kami akan mengejar dan membongkar mafia tanah yang ada di balik semua ini hingga ke akar‑akarnya, karena hukum harus tegak dan hak klien kami harus kembali utuh, jelas, dan terlindungi,\" pungkas Dr. Teguh Suharto Utomo.</p><p style=\"text-align: justify; \">Hingga berita ini diturunkan, pihak keluarga almarhum maupun oknum Kepala Desa yang disebutkan dalam kasus ini belum memberikan tanggapan resmi terkait pernyataan dan langkah hukum yang disampaikan oleh kuasa hukum korban. Situasi hukum ini pun menjadi sorotan publik, mengingat kasus ini menegaskan bahwa berakhirnya nyawa seseorang tidak menutup tanggung jawab atas kerugian yang ditimbulkan, serta menjadi momentum penting dalam upaya pemberantasan praktik mafia tanah yang masih menjadi persoalan di wilayah Kabupaten Mojokerto.(red)</p>','Dinamika Hukum Pasca Kematian Tersangka: Gugurnya Status Pidana dan Langkah Pemulihan HakXNN | MOJOKERTO – Kabar duka sekaligus dinamika hukum baru ',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a24580be757e.jpg',35,'2026-06-07 00:25:31'),(71,'Dr Teguh S.Utomo,S.Psi,SH,MH,MM : Ferdyanto Salim dikelabui, Perjanjian dibuat tidak dilandasi itikad baik','dr-teguh-s-utomo-s-psi-sh-mh-mm-ferdyanto-salim-dikelabui-perjanjian-dibuat-tidak-dilandasi-itikad-baik','<p style=\"text-align: justify; \"><font color=\"#085294\">Foto: wahyu Ferdiansyah dan korban Ferdyanto salim</font></p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | SURABAYA</font> - Tim Kuasa Hukum Teguh,Santoso dan Rekan atas nama klien : Ferdyanto Salim  yaitu Wahyu Ferdiansyah,SH, Inka Fadilah,SH, Herlini Y.S Weka,SH menilai somasi yang dilayangkan oleh PT. ClickWork Solusi Indonesia melalui Ilham Akbar Harahap merupakan langkah yang keliru, salah sasaran, dan tidak didasarkan pada pemahaman yang utuh terhadap fakta yang sebenarnya terjadi.</p><p style=\"text-align: justify; \">Menurut Tim Kuasa Hukum, tuntutan yang disampaikan dalam somasi tersebut terkesan ambisius dan lebih berorientasi pada kepentingan sepihak dibandingkan upaya mencari penyelesaian yang adil. Bahkan, substansi tuntutan yang diajukan dinilai tidak memberikan jalan keluar terhadap permasalahan yang ada, melainkan hanya berfokus pada tuntutan materiil tanpa mempertimbangkan aspek kemanusiaan, rasa keadilan, serta tanggung jawab dari seluruh pihak yang terlibat.</p><p style=\"text-align: justify;\">Ferdyanto Salim sendiri merasa dirugikan karena pada saat penandatanganan perjanjian, tidak pernah diberikan penjelasan yang memadai mengenai keseluruhan isi perjanjian maupun konsekuensi hukumnya. Klien kami juga baru mengetahui adanya klausul pilihan domisili hukum di Jakarta setelah munculnya sengketa dan somasi tersebut. Padahal, sejak awal Ferdyanto Salim berdomisili di Surabaya dan tidak pernah memahami bahwa apabila terjadi sengketa harus diselesaikan melalui domisili hukum yang berada di luar tempat tinggalnya.</p><p style=\"text-align: justify; \">Keadaan tersebut menimbulkan pertanyaan mengenai sejauh mana klien kami benar-benar diberikan kesempatan untuk memahami isi dan konsekuensi hukum dari dokumen yang ditandatanganinya. Oleh karena itu, tidak berlebihan apabila klien kami merasa ditempatkan pada posisi yang tidak seimbang dan dirugikan dalam hubungan hukum tersebut.</p><p style=\"text-align: justify; \">Sebelum somasi dilayangkan, Ferdyanto Salim juga telah berupaya membuka ruang komunikasi dan penyelesaian secara musyawarah. Namun alih-alih mengedepankan dialog dan penyelesaian yang berkeadilan, pihak perusahaan justru memilih mengirimkan somasi yang menurut kami tidak hanya salah sasaran, tetapi juga berpotensi menimbulkan tekanan dan kerugian lebih lanjut bagi klien kami.</p><p style=\"text-align: justify; \">Tim Kuasa Hukum  Teguh, Santoso dan Rekan menegaskan bahwa setiap hubungan hukum seharusnya dibangun di atas prinsip itikad baik, keterbukaan, keseimbangan hak dan kewajiban, serta penghormatan terhadap nilai-nilai kemanusiaan. Oleh sebab itu, kami menilai bahwa pendekatan yang hanya berorientasi pada keuntungan dan tuntutan sepihak tanpa mempertimbangkan kondisi nyata yang dialami pihak lain bukanlah cara yang tepat untuk menyelesaikan suatu permasalahan hukum.</p><p style=\"text-align: justify; \">Atas dasar tersebut, Ferdyanto Salim melalui Tim Kuasa TSR Law Firm yaitu Wahyu Ferdiansyah,SH, Inka Fadilah,SH dan Herlini Y.S Weka,SH akan menggunakan seluruh hak hukum yang tersedia untuk membela kepentingan Ferdyanto Salim serta memastikan bahwa fakta-fakta yang sebenarnya dapat terungkap secara utuh tanpa ancaman dan intimidasi dari PT Clickwork Solusi Indonesia</p>','XNN | SURABAYA - Tim Kuasa Hukum Teguh,Santoso dan Rekan atas nama klien : Ferdyanto Salim  yaitu Wahyu Ferdiansyah,SH, Inka Fadilah,SH, Herlini Y.S W',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a25930d252e9.jpg',43,'2026-06-07 22:49:33'),(72,'3 EKOR SAPI 400 KG MENDARAT DI KEDIRI: DR. TEGUH SUHARTO UTOMO BAGIKAN KURBAN KE LINGKUNGAN PEMKOT & PONDOK KASIH','3-ekor-sapi-400-kg-mendarat-di-kediri-dr-teguh-suharto-utomo-bagikan-kurban-ke-lingkungan-pemkot-pondok-kasih','<p><font color=\"#3984c6\">Foto: sapi kurban TSR</font></p><p style=\"text-align: justify; \"><font color=\"#ce0000\">XNN | KEDIRI</font> - Semangat Idul Adha 1447 H/2026 dirasakan warga Kediri. Dr. Teguh Suharto Utomo,  SH, MH, Wakil Ketua Umum DPN PERADI, menyalurkan 3 ekor sapi kurban bobot ±400 kg/ekor untuk lingkungan Pemkot Kediri dan Pondok Kasih.</p><p style=\"text-align: justify; \">Daging kurban dibagikan langsung ke masyarakat sekitar Balai Kota Kediri dan anak-anak asuh di Pondok Kasih. Aksi ini jadi bentuk kepedulian advokat nasional untuk warga Kediri.</p><p style=\"text-align: justify; \">Kolaborasi Advokat &amp; Aparat</p><p style=\"text-align: justify; \">Momen penyerahan Dr. Teguh terlihat melakukan tosan/salam kompak bersama Erwandi, aparat yang mendampingi kegiatan.</p><p style=\"text-align: justify; \">\"Idul Adha itu momentum berbagi dan keadilan sosial. Sebagai advokat, kita harus hadir bukan hanya di ruang sidang, tapi juga di tengah masyarakat yang membutuhkan,\" ujar Dr. Teguh saat meninjau lokasi kurban di Kediri, Jumat 6 Juni 2026.</p><p style=\"text-align: justify; \">Tepat Sasaran: Pemkot Kediri &amp; Pondok Kasih</p><p style=\"text-align: justify;\">Distribusi daging kurban difokuskan ke dua titik:</p><p style=\"text-align: justify; \">1. Lingkungan Pemkot Kediri - untuk warga sekitar, petugas, dan dhuafa di area Balai Kota</p><p>2. Pondok Kasih- untuk anak-anak asuh dan pengurus panti</p><p>Total 3 ekor sapi dengan bobot 400 kg dipilih agar pembagian bisa merata dan mencukupi kebutuhan selama hari tasyrik.</p><p>Menurut Dr. Teguh, profesi advokat tidak cukup bicara pasal. Kode Etik Advokat Indonesia mewajibkan advokat mengabdi untuk kepentingan masyarakat.</p><p>\"Kalau adik-adik di Pondok Kasih bisa makan daging kurban dengan layak di hari raya, itu juga bentuk kita menegakkan keadilan,\" tegasnya.</p><p>Apresiasi mengalir dari pengurus Masjid sekitar Pemkot dan pengelola Pondok Kasih. Mereka menyebut bantuan sapi besar ini sangat membantu mencukupi kebutuhan konsumsi warga dan anak asuh.</p>','Foto: sapi kurban TSRXNN | KEDIRI - Semangat Idul Adha 1447 H/2026 dirasakan warga Kediri. Dr. Teguh Suharto Utomo,  SH, MH, Wakil Ketua Umum DPN PERA',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a259b51b34df.jpg',44,'2026-06-07 23:25:16'),(73,'Advokat Dr Teguh S.Utomo,S.Psi,SH,MH,MM,CTT : Perdamaian Resmi Diputuskan Hakim Sah! Dan Mengikat seluruh Pihak! Perkara Tuntas!','advokat-dr-teguh-s-utomo-s-psi-sh-mh-mm-ctt-perdamaian-resmi-diputuskan-hakim-sah-dan-mengikat-seluruh-pihak-perkara-tuntas','<p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\"><span style=\"font-family: Arial;\">Keterangan ﻿foto:</span><font color=\"#3984c6\"><span style=\"font-family: Arial;\">&nbsp;</span></font></span><span style=\"color: rgb(57, 132, 198); font-family: Arial; text-align: justify;\">seluruh keluarga besar korban, yang secara hukum diwakili dan didampingi oleh kuasa hukumnya Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M., sepakat menempuh jalan damai dengan pihak terkait.</span><br></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Majelis Hakim PN Surabaya Putuskan Penyelesaian Akhir Perkara Kecelakaan yang Menyeret Tiga Korban</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\"><br></span><span style=\"font-family: &quot;Times New Roman&quot;;\"><font color=\"#ce0000\"><b>SURABAYA, 10 JUNI 2026</b></font> – Titik terang dan kepastian hukum akhirnya menyelimuti perkara tindak pidana kecelakaan lalu lintas yang menimpa tiga korban, yakni almarhum Miftahul Ulum, Faras, dan Boy Hilmi. Perkara yang sempat berliku dan menyita perhatian ini kini dinyatakan tuntas dan selesai sepenuhnya setelah Majelis Hakim Pengadilan Negeri Surabaya secara resmi menjatuhkan putusan yang mengukuhkan kesepakatan perdamaian yang telah dicapai antar para pihak.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Kepastian hukum ini lahir setelah seluruh keluarga besar korban, yang secara hukum diwakili dan didampingi oleh kuasa hukumnya Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M., sepakat menempuh jalan damai dengan pihak terkait. Naskah kesepakatan damai yang telah disusun dan ditandatangani bersama tersebut kemudian diajukan secara resmi ke Pengadilan Negeri Surabaya guna mendapatkan pengesahan serta kekuatan hukum tetap.</span><span style=\"font-family: &quot;Times New Roman&quot;;\"></span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Dalam sidang pembacaan putusan yang berlangsung khidmat dan tertib, Majelis Hakim PN Surabaya akhirnya mengabulkan permohonan tersebut dan secara tegas menyatakan bahwa isi perdamaian tersebut SAH serta MENGIKAT seluruh para pihak yang berperkara.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Dalam amar putusannya yang diketukkan di persidangan, Majelis Hakim menegaskan bahwa kesepakatan damai yang telah disusun secara sadar, sukarela, dan tanpa tekanan apa pun memiliki kedudukan serta kekuatan hukum yang sama dengan putusan pengadilan yang telah berkekuatan hukum tetap. Konsekuensi hukum mutlak dari putusan ini adalah tidak ada lagi tuntutan, gugatan, klaim, atau penagihan dalam bentuk apa pun yang boleh diajukan di kemudian hari terkait peristiwa dan seluruh kerugian yang timbul dari perkara kecelakaan lalu lintas tersebut.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M., selaku kuasa hukum yang mewakili dan mendampingi seluruh keluarga besar korban, menyambut gembira dan mengapresiasi putusan hukum ini. Ia menilai, keputusan hakim ini menjadi penutup yang melegakan, sekaligus memberikan kepastian hukum yang utuh dan mutlak bagi semua pihak yang terlibat.</span><span style=\"font-family: &quot;Times New Roman&quot;;\"></span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">\"Alhamdulillah, segala puji bagi Tuhan. Setelah melalui proses panjang, diskusi, dan pembahasan mendalam bersama seluruh keluarga besar korban, akhirnya kita sampai pada titik penyelesaian yang sah, beradab, dan berkeadilan.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Perdamaian ini telah kita rumuskan secara matang, rinci, dan penuh tanggung jawab, dan hari ini Majelis Hakim resmi mengukuhkannya menjadi a putusan yang sah serta mengikat. Artinya, perkara ini sudah selesai sepenuhnya, tuntas sampai ke akar‑akarnya, dan tidak akan ada lagi sengketa atau tuntutan apa pun di masa mendatang,\" ungkap Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M. usai persidangan.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Lebih lanjut, ia menjelaskan bahwa langkah perdamaian ini diambil demi kepentingan bersama, pemulihan suasana, kemanusiaan, serta untuk menegakkan keadilan melalui jalur penyelesaian yang damai namun tetap kokoh berdasarkan landasan hukum yang berlaku. Hal ini juga menjadi wujud tanggung jawab para pihak untuk saling menutup lembaran masa lalu dan melangkah ke depan tanpa beban hukum lagi.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Dengan diketukkannya putusan ini, maka seluruh proses hukum yang berkaitan dengan peristiwa kecelakaan lalu lintas yang menimpa Miftahul Ulum, Faras, dan Boy Hilmi tersebut dinyatakan berakhir sepenuhnya. Kini, seluruh hak dan kewajiban para pihak telah diselesaikan dan dilunasi sesuai apa yang telah disepakati dan ditetapkan secara sah oleh Pengadilan Negeri Surabaya, sehingga tidak ada lagi ruang untuk perselisihan hukum di kemudian hari</span><span style=\"font-family: &quot;Courier New&quot;;\">﻿</span></p>','Majelis Hakim PN Surabaya Putuskan Penyelesaian Akhir Perkara Kecelakaan yang Menyeret Tiga KorbanSURABAYA, 10 JUNI 2026 – Titik terang dan kepastia',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a2917474fddf.png',49,'2026-06-10 14:59:18'),(74,'NAHKODA BARU FADLI TERPILIH SEBAGAI KETUA UMUM HMI CABANG KOLAKA PERIODE 2026–2027','nahkoda-baru-fadli-terpilih-sebagai-ketua-umum-hmi-cabang-kolaka-periode-2026-2027','<p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%; font-family: Arial;\"><font color=\"#3984c6\">Foto: fadli nahkoda baru himpunan mahasiswa islam cabang kolaka</font></span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%; font-family: Arial;\"><font color=\"#ce0000\"><span style=\"font-family: Arial;\">XNN | KOLAKA - </span></font><span style=\"font-family: &quot;Helvetica Neue&quot;;\">Konferensi HMI Cabang Kolaka (Konfercab) ke-IX yang dilaksanakan pada tanggal</span><span style=\"font-family: Arial;\"> 07–11 Juni 2026 di Aula Rumah Adat Kolaka telah berlangsung dengan sukses dan penuh khidmat. Kegiatan ini menjadi forum tertinggi dalam struktur organisasi Himpunan Mahasiswa Islam (HMI) di tingkat cabang, yang bertujuan untuk mengevaluasi kepengurusan sebelumnya serta menetapkan arah baru kepemimpinan organisasi ke depan.</span></span><br></p><p style=\"text-align: justify;\">Konfercab kali ini dihadiri oleh seluruh kader HMI Cabang Kolaka dari berbagai komisariat, serta para alumni dan tamu undangan. Meskipun sempat diwarnai dinamika dan perbedaan pandangan selama proses persidangan, seluruh rangkaian kegiatan tetap berjalan dengan menjunjung tinggi AD/ART, nilai-nilai demokrasi, intelektualitas, dan kekeluargaan yang menjadi ciri khas HMI.</p><p style=\"text-align: justify;\">Dalam forum pleno yang berlangsung secara demokratis, Fadli akhirnya terpilih sebagai Ketua Umum HMI Cabang Kolaka periode 2026–2027. Terpilihnya Fadli menjadi harapan baru bagi seluruh kader untuk membawa HMI Cabang Kolaka ke arah yang lebih progresif, responsif terhadap isu-isu keumatan dan kebangsaan, serta tetap berpegang teguh pada nilai-nilai keislaman dan keindonesiaan.</p><p style=\"text-align: justify;\">Didalam Forum Konfercab setelah di tetapkannya sebagai Ketua Umum, Fadli menyampaikan komitmennya untuk menjadikan HMI Cabang Kolaka sebagai organisasi yang lebih solid, berintegritas, dan mampu menjadi garda terdepan dalam memperjuangkan kepentingan umat dan rakyat.</p><p style=\"text-align: justify;\">“Ini bukan hanya kemenangan pribadi, tetapi kemenangan seluruh kader HMI Cabang Kolaka. Mari kita bersatu, memperkuat barisan, dan bersama-sama membawa HMI menjadi organisasi yang lebih maju dan bermartabat,” ujar Fadli.</p><p style=\"text-align: justify;\">Ia juga menegaskan pentingnya menjaga semangat kaderisasi, memperkuat tradisi intelektual, serta meningkatkan peran strategis HMI dalam menjawab tantangan zaman.</p><p style=\"text-align: justify;\">Dengan berakhirnya Konfercab ke-IX ini, diharapkan kepengurusan baru di bawah kepemimpinan Fadli mampu menjalankan amanah organisasi dengan baik serta memberikan kontribusi nyata bagi masyarakat, daerah, dan bangsa.</p>','Foto: fadli nahkoda baru himpunan mahasiswa islam cabang kolakaKonferensi HMI Cabang Kolaka (Konfercab) ke-IX yang dilaksanakan pada tanggal 07–11 J',8,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a2be58a3ce75.jpeg',38,'2026-06-12 17:57:52'),(75,'Ini Kronologi Dugaan Pengeroyokan yang Libatkan Wakil Ketua KONI Kota Batu','ini-kronologi-dugaan-pengeroyokan-yang-libatkan-wakil-ketua-koni-kota-batu','<h6><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#ce0000\"><span style=\"font-family: Arial;\"><br></span></font></span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><font color=\"#ce0000\"><span style=\"font-family: Arial;\">XNN | BATU </span></font><span style=\"font-family: Arial;\">- Kasus dugaan penganiayaan dan pengeroyokan menimpa warga Kota Batu berinisial RC. Mirisnya, peristiwa ini melibatkan Wakil Ketua Komite Olahraga Nasional Indonesia (KONI) Kota Batu, SA beserta dua rekannya.</span></span></p><div style=\"text-align: justify;\"><span style=\"font-size: 1rem; text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Kuasa Hukum sekaligus paman korban, Teguh Suharto Utomo, mengungkapkan peristiwa dugaan pengeroyokan terjadi usai pertandingan persahabatan bulu tangkis di gedung serbaguna, Dadaprejo, Kecamatan Junrejo, Kota Batu. Tepatnya pada 2 Juni 2026 dini hari.</span></div></h6><h6><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\"><span style=\"font-size: 1rem; text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">\"Jadi saat pertandingan bulutangkis korban ini mendukung tim bulu tangkis kenalannya yang waktu itu menghadapi tim yang didukung dia (SA). Awalnya tidak ada masalah, pertandingan berjalan lancar hingga akhirnya tim lawan itu menang,\" ungkap Teguh, Jumat (12/6/2026).</span></div></h6><h6><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\"><span style=\"font-size: 1rem; text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">\"Korban akhirnya pulang setelah pertandingan berakhir. Tepat di depan gedung keponakan saya dicegat, dimarahi karena tidak mendukung timnya dia (SA). Korban pun menjelaskan kalau yang tanding adalah teman sekolahnya, tapi tiba-tiba dada korban didorong,\" imbuhnya.</span></div></h6><h6><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\"><span style=\"font-size: 1rem; text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Ketegangan semakin memuncak ketika dua orang rekan SA yang diidentifikasi bernama H dan M ikut turun tangan. Tanpa peringatan, H diduga memukul kepala bagian belakang korban hingga korban tersungkur di lantai.</span></div></h6><h6><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\"><span style=\"font-size: 1rem; text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Tak berhenti disitu, ketika korban berdiri sambil dibantu temannya bernama Evan, SA langsung melayangkan tamparan beberapa kali sambil memaki korban dengan kasar dan kotor berulangkali. Aksi penamparan itu juga dilakukan M terhadap korban.</span></div></h6><h6><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\"><span style=\"font-size: 1rem; text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Aksi brutal di depan puluhan orang tersebut akhirnya berhenti setelah dilerai. Pada hari yang sama korban pun memutuskan untuk melaporkan kasus yang dialaminya ke Polres Batu.</span></div></h6><h6><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\"><span style=\"font-size: 1rem; text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">\"Itu kan kejadian dini hari sekitar pukul 00.30 WIB. Nah paginya itu korban langsung melaporkan kasus pengeroyokan yang dialaminya ke Polres Batu,\" tandas Teguh.</span></div></h6>','XNN | BATU - Kasus dugaan penganiayaan dan pengeroyokan menimpa warga Kota Batu berinisial RC. Mirisnya, peristiwa ini melibatkan Wakil Ketua Komite O',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a2d50655c9d0.jpeg',34,'2026-06-13 19:43:17'),(76,'Mediasi Kasus Pengeroyokan Diduga Libatkan KONI Batu Gagal','mediasi-kasus-pengeroyokan-diduga-libatkan-koni-batu-gagal','<p style=\"text-align: justify;\"><font color=\"#085294\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Foto:</span><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">&nbsp;kuasa hukum korban , Wahyu F dan Inka Fadilah saat berada di Polres Batu.&nbsp;</span></font></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><br></span><font color=\"#9c0000\" style=\"text-align: var(--bs-body-text-align); font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">XNN | BATU </font><span style=\"text-align: var(--bs-body-text-align); font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">- Upaya penyelesaian secara damai dalam kasus dugaan pengeroyokan yang melibatkan seorang pengurus organisasi olahraga di Kota Batu berakhir tanpa kesepakatan.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Mediasi yang difasilitasi penyidik kepolisian Polres Batu tidak membuahkan hasil sehingga proses hukum tetap berlanjut.</span><br></p><p style=\"text-align: justify;\">Kuasa hukum korban, Teguh Suharto Utomo mengungkapkan bahwa mediasi mempertemukan kliennya berinisial RC dengan tiga terlapor berinisial S.A., H., dan M. di Mapolres Batu pada Selasa (9/6/2026).</p><p style=\"text-align: justify;\">Pertemuan tersebut berlangsung dengan pendampingan keluarga dan kuasa hukum dari masing-masing pihak.</p><p style=\"text-align: justify;\">Namun setelah dilakukan pembahasan, kedua belah pihak belum menemukan titik temu untuk menyelesaikan perkara di luar jalur hukum.</p><p style=\"text-align: justify;\">\"Mediasi sudah dilakukan, tetapi belum menghasilkan kesepakatan. Karena itu kami menghormati proses hukum yang saat ini masih berjalan,\" ujarnya., Sabtu (13/6/2026).</p><p style=\"text-align: justify;\">Menurutnya, korban masih menginginkan kepastian hukum atas peristiwa yang dialaminya.&nbsp;</p><p style=\"text-align: justify;\">Karena itu, pihaknya memilih menyerahkan sepenuhnya penanganan kasus kepada aparat penegak hukum.</p><p style=\"text-align: justify;\">Kasus tersebut berawal dari sebuah pertandingan persahabatan bulu tangkis yang digelar di wilayah Dadaprejo, Kecamatan Junrejo, Kota Batu, pada awal Juni 2026.&nbsp;</p><p style=\"text-align: justify;\">Korban yang hadir sebagai penonton disebut memberikan dukungan kepada salah satu tim yang bertanding.</p><p style=\"text-align: justify;\">Usai pertandingan, terjadi perselisihan yang kemudian diduga berujung pada aksi kekerasan.&nbsp;</p><p style=\"text-align: justify;\">Dalam laporan yang telah disampaikan kepada kepolisian, korban mengaku mengalami pemukulan dan penamparan oleh beberapa orang di lokasi kejadian.</p><p style=\"text-align: justify;\">Peristiwa itu sempat menjadi perhatian para penonton yang berada di sekitar arena pertandingan hingga akhirnya berhasil dilerai.</p><p style=\"text-align: justify;\">Tak lama setelah kejadian, korban melaporkan dugaan pengeroyokan tersebut ke Polres Batu untuk diproses sesuai ketentuan hukum yang berlaku.</p><p style=\"text-align: justify;\">Sementara itu, Satreskrim Polres Batu masih melakukan penyelidikan dengan memeriksa sejumlah pihak yang mengetahui peristiwa tersebut. Polisi juga telah mengumpulkan hasil visum korban sebagai bagian dari alat bukti dalam penanganan perkara.</p><p style=\"text-align: justify;\">Dr Teguh S.Utomo,S.Psi,SH,MH,MM Percaya &nbsp;kepada Kepolisian akan Profesional, Transparan dan Akuntabel</p><p style=\"text-align: justify;\">Saya percaya Kapolres Batu AKBP Aris Putranto,SIK., Kasatreskrim Polres Batu AKP Zaenal Arifin dan jajaran Kanit Penyidik Polres Batu akan mentutaskan Perkara Pengeroyokan yang dilakukan Sinal Abidin, Hari dan Martin secara bersama sama, ditambahkan lagi apabila Tetap tidak ada Itikad baik dari para Terlapor, klien kami akan &nbsp;kembali membuat Laporan Polisi &nbsp;baru yaitu &nbsp;UU Nomor 40 Tahun 2008 tentang Penghapusan Diskriminasi Ras dan Etnis.</p><p style=\"text-align: justify;\">UU ini masih berlaku dan memang dibuat untuk melindungi seseorang dari tindakan diskriminasi atau kebencian berdasarkan ras dan etnis.</p><p style=\"text-align: justify;\">UU tersebut tidak hanya mengatur diskriminasi dalam pekerjaan atau pelayanan publik, tetapi juga perbuatan yang menunjukkan kebencian karena perbedaan ras atau etnis, termasuk melontarkan kata-kata tertentu di tempat umum yang dapat didengar orang lain.&nbsp;</p><p style=\"text-align: justify;\">Ancaman Pidana nya 5 Tahun, sebab Klien kami dihina dan dicaci maki dengan umpatan : \"Cina Cina Jancukan\" ini sangat tragis sekali, Pelapor / Korban ini Adalah Warga Negara Indonesia, bukan Warga Negara Asing / WARGA NEGARA CINA!</p>','Foto:&nbsp;kuasa hukum korban , Wahyu F dan Inka Fadilah saat berada di Polres Batu.&nbsp;XNN | BATU - Upaya penyelesaian secara damai dalam kasus dug',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a2d547947f46.jpeg',30,'2026-06-13 20:00:41'),(77,'Mediasi Dugaan Pengeroyokan Gagal, Sinal Abidin Terancam Dilaporkan atas Dugaan Ujaran Kebencian','mediasi-dugaan-pengeroyokan-gagal-sinal-abidin-terancam-dilaporkan-atas-dugaan-ujaran-kebencian','<p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\"><font color=\"#085294\">Foto: Sinal Abidin</font></span></p><p style=\"text-align: justify; \"><font color=\"#9c0000\"><span style=\"font-family: &quot;Times New Roman&quot;;\">XNN | BATU </span></font><span style=\"font-family: &quot;Times New Roman&quot;;\">– Upaya mediasi dalam perkara dugaan pengeroyokan yang dilaporkan Ronny Christian terhadap Sinal Abidin, Hari, dan Martin berakhir tanpa kesepakatan damai. Peristiwa yang dipersoalkan terjadi usai pertandingan bulutangkis di depan Gedung Serbaguna, Desa Dadaprejo, Kecamatan Junrejo, Kota Batu.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">Kuasa hukum Ronny Christian, Dr. Teguh Suharto Utomo, S.Psi., S.H., M.H., M.M., didampingi Wahyu Ferdiansyah, Inka Fadilah, dan tim, menjelaskan bahwa mediasi tersebut digelar atas permintaan pihak terlapor. Proses pertemuan difasilitasi oleh jajaran Satreskrim Polres Batu yang dipimpin Kasatreskrim, Kanit Reskrim, dan penyidik terkait.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">Namun, pertemuan tersebut tidak menghasilkan kesepakatan. Menurut pihak korban, permohonan maaf yang disampaikan para terlapor secara lisan dinilai belum mencerminkan bentuk pertanggungjawaban yang memadai atas peristiwa yang dilaporkan.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">Teguh menyatakan pihaknya tetap menghormati proses hukum yang sedang berjalan dan meyakini Polres Batu akan menuntaskan penanganan perkara tersebut.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">\"Saya percaya Kapolres Batu AKBP Aris Putranto, S.I.K., Kasatreskrim AKP Zaenal Arifin, serta jajaran penyidik Polres Batu akan menuntaskan perkara dugaan pengeroyokan ini sesuai ketentuan hukum yang berlaku,\" ujar Teguh.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: &quot;Times New Roman&quot;;\">Ia juga menyampaikan bahwa apabila para terlapor dinilai tidak menunjukkan itikad baik, pihaknya mempertimbangkan untuk membuat laporan polisi baru terkait dugaan pelanggaran Undang-Undang Nomor 40 Tahun 2008 tentang Penghapusan Diskriminasi Ras dan Etnis.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">Menurut Teguh, kliennya mengaku menerima penghinaan bernuansa etnis berupa ucapan \"Cina-Cina Jancukan\" yang diduga dilontarkan di tempat umum dan didengar oleh sejumlah orang.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">\"Klien kami adalah Warga Negara Indonesia. Jika benar terdapat ucapan yang bernuansa penghinaan ras atau etnis, maka hal tersebut berpotensi masuk dalam ketentuan UU Nomor 40 Tahun 2008 tentang Penghapusan Diskriminasi Ras dan Etnis,\" katanya.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">Meski demikian, dugaan tersebut masih memerlukan pembuktian lebih lanjut melalui proses penyelidikan dan penyidikan oleh aparat penegak hukum.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">Dalam keterangannya, Teguh juga menyinggung rekam jejak Sinal Abidin yang pernah menjalani proses hukum dalam perkara korupsi pada tahun 2018. Saat ini, Sinal diketahui menjabat sebagai Wakil Ketua Umum KONI Kota Batu.</span></p><p style=\"text-align: justify; \"><span style=\"font-family: &quot;Times New Roman&quot;;\">Hingga berita ini diturunkan, Sinal Abidin belum memberikan keterangan resmi terkait gagalnya mediasi maupun rencana pelaporan atas dugaan ujaran kebencian tersebut. Upaya konfirmasi yang dilakukan kepada yang bersangkutan belum memperoleh tanggapan.</span></p>','Foto: Sinal AbidinXNN | BATU – Upaya mediasi dalam perkara dugaan pengeroyokan yang dilaporkan Ronny Christian terhadap Sinal Abidin, Hari, dan Mart',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a2ddeec24b90.jpg',31,'2026-06-14 05:51:24'),(78,'Jejak Wakil Ketua KONI Kota Batu yang Terseret Dugaan Pengeroyokan, Pernah Dipenjara Kasus Korupsi','jejak-wakil-ketua-koni-kota-batu-yang-terseret-dugaan-pengeroyokan-pernah-dipenjara-kasus-korupsi','<p style=\"text-align: justify;\"><font color=\"#ce0000\">XNN | KOTA BATU</font> - Kasus dugaan pengeroyokan yang dilakukan Wakil Ketua KONI Kota Batu, Jawa Timur, Sinal Abidin, kini menjadi perbincangan hangat, baik di media sosial maupun di tempat tongkrongan masyarakat luas.</p><p style=\"text-align: justify;\">Itu lantaran selain diduga melakukan pengeroyokan terhadap RC (pelapor) usai menonton pertandingan bulutangkis di depan Gedung Serbaguna Kelurahan Dadaprejo, Kecamatan Junrejo, Kota Batu, Selasa (2/6/2026) lalu, riwayat ketiga terlapor yakni Sinal Abidin, Hari Nugroho dan Arif Dwi Santoso alias Martin diketahui seluruhnya merupakan mantan narapidana dengan kasus yang berbeda-beda.</p><p style=\"text-align: justify;\">Sinal Abidin pernah dipenjara karena kasus korupsi saat ia menjabat sebagai Kepala Dinas Koperasi, Usaha Mikro, dan Perdagangan (Koperindag) Kota Batu.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Berdasarkan putusan Pengadilan Tipikor Surabaya tahun 2018, ia divonis hukuman penjara selama 1 tahun 8 bulan.</span><br></p><p style=\"text-align: justify;\">Kasus korupsi yang menjerat Sinal Abidin pada saat itu berkaitan dengan penyalahgunaan atau pemalsuan anggaran reklame saat menjabat sebagai Kepala Bagian Humas Pemkot Batu.</p><p style=\"text-align: justify;\">Sedangkan Hari Nugroho penah dipenjara karena kasus narkoba, sementara Arif Dwi Santoso dipenjara lantaran kasus pengeroyokan berujung tewasnya seseorang bernama Damianus Egi Tuturon.</p><p style=\"text-align: justify;\">Kejadiannya pada tahun 2017 lalu di Kecamatan Bantur, Kabupaten Malang karena korban tidak dapat membayar utang sebesar Rp 300.000.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Tentunya riwayat ketiganya yang terpampang dalam Sistem Informasi Penelusuran Perkara Pengadilan ini akan menjadi bahan pertimbangan Polres Batu dalam menangani kasus dugaan pengeroyokan ini.</span><br></p><p style=\"text-align: justify;\">Kasat Reskrim Polres Batu, AKP Zainal Arifin menegaskan, penanganan kasus ini masih terus berjalan.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Bahkan polisi akan menambah dua saksi lagi, setelah sebelumnya telah memerika enam saksi.</span><br></p><p style=\"text-align: justify;\">“Benar, sampai dengan saat ini proses penyelidikan masih terus berjalan.\"</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">\"Saat ini sudah enam saksi yang kami mintai keterangan dan minggu ini kami jadwalkan untuk memanggil dua saksi lagi,” jelas AKP Zainal Arifin kepada SURYAMALANG.COM, Minggu (14/6/2026).</span><br></p><p style=\"text-align: justify;\">Seperti diberitakan sebelumnya, kejadian bermula saat RC selesai menonton pertandingan bulutangkis di depan Gedung Serbaguna Kelurahan Dadaprejo, Kecamatan Junrejo, Kota Batu pada Selasa (2/6/2026) lalu.</p><p style=\"text-align: justify;\">Berdasarkan penuturan Kuasa hukum korban, Teguh Suharto Utomo, saat itu RC datang untuk memberikan dukungan kepada tim sekolah temannya untuk bertanding bulutangkis.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Kemudian tim yang didukung RC kalah dari tim yang didukung Sinal Abidin dan setelah pertandingan terjadi ketegangan.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Saat hendak pulang RC dicegat dan didorong oleh Sinal meskipun telah berusaha memberikan penjelasan.</span></p><p style=\"text-align: justify;\">Namun situasi justru memanas setelah Hari Nugroho dan Arif Dwi Santoso yang merupakan rekan Sinal ikut terlibat dalam ketegangan itu.</p><p style=\"text-align: justify;\">“Saat itu Sinal langsung menampar klien kami sebanyak beberapa kali sambil memaki korban dengan menyebut Bajingan kamu, China Jancok berulangkali,” tutur Teguh Suharto Utomo.</p><p style=\"text-align: justify;\">Sementara itu dari pihak Sinal Abidin melalui Penasihat hukumnya, Bagas Dwi Wicaksono membantah tudingan itu dan mengatakan kliennya tidak melakukan pengeroyokan.</p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Menurutnya aksi dorong dan antisipasi kekerasan antar suporter pertandingan bulu tangkis itu merupakan hal yang biasa terjadi di pertandingan.</span><br></p><p style=\"text-align: justify;\">“Antar suporter pertandingan saling memberikan dukungan.\"</p><p style=\"text-align: justify;\">\"Kalah dan menang adalah biasa pada saat aksi saling dukung tim pemain dan aksi dorong mendorong merupakan hal yang lumrah dan wajar.\"</p><p style=\"text-align: justify;\">Artinya tidak ada sama sekali aksi kekerasan yang di duga di lakukan oleh klien kami,” kata Bagas Dwi Wicaksono.</p><p style=\"text-align: justify;\">source:&nbsp;<span style=\"-webkit-text-size-adjust: 100%; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\">SURYAMALANG.COM</span></p>','XNN | KOTA BATU - Kasus dugaan pengeroyokan yang dilakukan Wakil Ketua KONI Kota Batu, Jawa Timur, Sinal Abidin, kini menjadi perbincangan hangat, bai',1,'',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a2ede8e83c74.webp',27,'2026-06-15 00:02:06'),(79,'Pakar Kebijakan Publik dan Ekonom, Dr. Teguh S Utomo, merilis analisis komprehensif mengenai proyeksi arah perekonomian 12 bulan ke depan','pakar-kebijakan-publik-dan-ekonom-dr-teguh-utomo-merilis-analisis-komprehensif-mengenai-proyeksi-arah-perekonomian-12-bulan-ke-depan','<p style=\"text-align: justify;\"><span style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><font color=\"#085294\">Foto: halusinasi&nbsp;</font></span></p><p style=\"text-align: justify;\"><span style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><b><font color=\"#ce0000\">XNN | SURABAYA</font></b>— Pakar Kebijakan Publik dan Ekonom, Dr. Teguh Utomo, merilis analisis komprehensif mengenai proyeksi arah perekonomian domestik, tantangan ketenagakerjaan, hingga kualitas Sumber Daya Manusia (SDM) Indonesia untuk 12 bulan ke depan. Analisis ini menyajikan skenario berbasis data makro terbaru guna membaca arah gerak Indonesia di panggung global.</span></p><p data-path-to-node=\"9\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Dalam rilis tertulisnya, Dr. Teguh Utomo memaparkan empat poin krusial yang menjadi jangkar pergerakan ekonomi nasional:</p><p data-path-to-node=\"10\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><b data-path-to-node=\"10\" data-index-in-node=\"0\">1. Arah Ekonomi Indonesia: Tumbuh Stabil, Bukan Meledak</b>&nbsp;\"Arah ekonomi Indonesia kemungkinan tetap tumbuh, tetapi tidak meledak,\" ujar Dr. Teguh Utomo. Berdasarkan skenario dasar yang disusunnya, pertumbuhan ekonomi nasional akan berada di kisaran sekitar 4,8%–5,2% dalam 12 bulan ke depan.</p><p data-path-to-node=\"11\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Proyeksi ini didasarkan pada data valid dari berbagai lembaga otoritas keuangan; di mana Bank Indonesia memproyeksikan pertumbuhan 2026 di angka 4,9%–5,7%, IMF memproyeksikan Indonesia di angka 5,0% untuk 2026, dan Bank Dunia melihat pertumbuhan tetap berada di sekitar 4,8% hingga tahun 2027. Melalui komparasi data tersebut, ekonomi Indonesia tampaknya masih cukup tahan banting, tetapi tetap bergerak dalam mode “tumbuh stabil”, bukan sebuah lonjakan besar.</p><p data-path-to-node=\"12\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><b data-path-to-node=\"12\" data-index-in-node=\"0\">2. Mengarungi Perlambatan Dunia dan Persaingan Global</b>&nbsp;Tantangan global terbesar saat ini adalah adanya perlambatan dunia serta persaingan yang makin keras. Data IMF memproyeksikan pertumbuhan global 2026 hanya berada di sekitar 3,3%. Di sisi lain, Bank Dunia menyoroti tekanan kuat yang bersumber dari ketidakpastian kebijakan global, fragmentasi perdagangan, hingga kondisi keuangan dunia yang jauh lebih ketat.</p><p data-path-to-node=\"13\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Dr. Teguh Utomo menganalisis bahwa kondisi ini mengartikan ekspor dan industri yang bergantung pada pasar luar negeri berisiko tertekan. Namun, Indonesia masih memiliki bantalan yang kuat dari konsumsi domestik serta tingkat permintaan dalam negeri. Faktor internal ini membuat ekonomi Indonesia relatif aman, namun harus digarisbawahi tetap rentan apabila terjadi pelemahan harga komoditas atau pasar global yang terus melambat.</p><p data-path-to-node=\"14\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><b data-path-to-node=\"14\" data-index-in-node=\"0\">3. Menata Aturan TKA: Soal Kontrol dan Kualitas Penyerapan</b>&nbsp;Merespons dinamika isu “serbuan orang asing” khususnya Tenaga Kerja Asing (TKA), Dr. Teguh Utomo menekankan bahwa tantangan utamanya bukan sekadar pada aspek jumlah, melainkan kontrol regulasi dan kualitas penyerapan tenaga kerja.</p><p data-path-to-node=\"15\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Secara aturan yuridis, TKA di Indonesia sebenarnya hanya diperbolehkan bekerja pada jabatan tertentu dan dalam batas waktu tertentu. Selain itu, pihak pemberi kerja wajib mengantongi izin tertulis dari Pemerintah Pusat serta pengesahan Rencana Penggunaan Tenaga Kerja Asing (RPTKA).</p><p data-path-to-node=\"16\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Oleh karena itu, persoalan utamanya terletak pada komitmen kepatuhan untuk memastikan TKA benar-benar masuk untuk posisi yang memang membutuhkan keahlian khusus (spesialis), bukan menggantikan tenaga kerja lokal secara tidak semestinya. Dari sisi kebijakan, tekanan sosial berpotensi muncul apabila publik melihat TKA mendapat akses lebih cepat ke sektor pekerjaan formal, sementara pekerja lokal masih harus berjuang keras di pasar kerja yang kompetitif dan didominasi sektor informal.</p><p data-path-to-node=\"17\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><b data-path-to-node=\"17\" data-index-in-node=\"0\">4. Titik Rawan Kualitas SDM dan Penciptaan Kerja Produktif</b>&nbsp;Titik rawan utama yang dihadapi Indonesia saat ini justru berakar pada kualitas SDM serta kemampuan penciptaan lapangan kerja yang produktif. Berdasarkan catatan resmi Badan Pusat Statistik (BPS) pada Februari 2026, angkatan kerja Indonesia telah mencapai angka 154,91 juta orang, dengan jumlah penduduk bekerja sebanyak 147,67 juta orang, dan Tingkat Pengangguran Terbuka (TPT) berada di angka 4,68%.</p><p data-path-to-node=\"18\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\">Data makro ketenagakerjaan ini menunjukkan bahwa pasar kerja di Indonesia pada dasarnya masih mampu menyerap tenaga kerja. Sisi tantangannya adalah bagaimana meningkatkan kualitas pekerjaan, mendongkrak produktivitas, serta mengatasi masalah ketidakcocokan keterampilan (<i data-path-to-node=\"18\" data-index-in-node=\"271\">skill mismatch</i>). Dengan kata lain, apabila TKA masuk ke sektor-sektor strategis, Indonesia wajib memastikan adanya proses alih ilmu (<i data-path-to-node=\"18\" data-index-in-node=\"404\">knowledge transfer</i>), pelatihan yang terukur, serta sertifikasi kompetensi agar kemanfaatan investasi tersebut juga dinikmati sepenuhnya oleh pekerja lokal.</p><p data-path-to-node=\"19\" style=\"text-align: justify; -webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><b data-path-to-node=\"19\" data-index-in-node=\"0\">Kesimpulan Eksekutif</b>&nbsp;Menutup analisisnya, Dr. Teguh Utomo memberikan kesimpulan optimis namun tetap waspada:</p><blockquote data-path-to-node=\"20\" style=\"-webkit-tap-highlight-color: rgba(26, 26, 26, 0.3); -webkit-text-size-adjust: auto;\"><p data-path-to-node=\"20,0\" style=\"text-align: justify;\">\"Indonesia kemungkinan tidak sedang menuju guncangan besar, melainkan fase pertumbuhan moderat yang sangat ditentukan oleh 3 hal: ketahanan konsumsi domestik, disiplin kebijakan, dan peningkatan kualitas tenaga kerja. Tantangan TKA sebaiknya dilihat sebagai soal pengaturan, pengawasan, dan transfer keterampilan, bukan semata-mata isu kedatangan orang asing.\"</p></blockquote>','Foto: halusinasi&nbsp;XNN | SURABAYA— Pakar Kebijakan Publik dan Ekonom, Dr. Teguh Utomo, merilis analisis komprehensif mengenai proyeksi arah perek',1,'Ekonomi, indonesia, Tka, surabaya, merahputih',8,8,'published','https://www.xyronnews.com/uploads/posts/post_6a30955d294ff.jpeg',48,'2026-06-16 17:47:45'),(80,'Adv DR TEGUH Suharto Utomo : MK perintahkan Ubah UU Advokat dalam batas 2 Tahun','adv-dr-teguh-suharto-utomo-mk-perintahkan-ubah-uu-advokat-dalam-batas-2-tahun','<p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\"><font color=\"#6badde\">Foto: halusinasi </font></span></p><p style=\"text-align: justify;\"><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent;\"><font color=\"#ce0000\">XNN | SURABAYA</font>,&nbsp;</span><span style=\"font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">Ketidakjelasan makna serta batas kewenangan dalam aturan pengawasan organisasi profesi advokat akhirnya mendapat sorotan serius dari Mahkamah Konstitusi (MK). Pasal 12 ayat (1) dan Pasal 28 ayat (1) Undang‑Undang Nomor 18 Tahun 2003 tentang Advokat dinilai multitafsir, berpotensi melahirkan praktik intervensi, serta menciptakan ketidakpastian hukum bagi penegak hukum yang seharusnya independen.</span></p><p style=\"text-align: justify;\">Pengujian kedua pasal tersebut dilakukan karena aturan yang berlaku saat ini kerap menjadi pemicu konflik internal di tubuh organisasi profesi. Perselisihan itu terjadi berulang kali dan terbukti sulit diselesaikan, bahkan melalui jalur pengadilan. Merespons kondisi tersebut, MK mengeluarkan putusan yang mewajibkan DPR dan Pemerintah selaku pembentuk undang‑undang melakukan revisi menyeluruh terhadap UU Advokat dalam waktu paling lama dua tahun sejak putusan dijatuhkan.</p><p style=\"text-align: justify;\">Menanggapi putusan ini, Dr.Teguh Suharto Utomo, S.Psi,S.H., M.H.M.M pengamat hukum dan praktisi yang mendalami regulasi profesi menilai langkah MK ini sangat tepat dan telah lama ditunggu oleh para advokat maupun pemangku kepentingan hukum. Menurutnya, masalah utama selama ini berakar dari rumusan aturan yang belum memisahkan secara tegas antara fungsi organisasi profesi dan fungsi pengaturan serta pengawasan.</p><p style=\"text-align: justify;\">Akar Masalah: Rumusan Pasal Menjadi Sumber Perselisihan</p><p style=\"text-align: justify;\">Dalam penjelasannya, Dr.Teguh Suharto Utomo menguraikan bahwa ketentuan dalam Pasal 12 ayat (1) mengenai kedudukan wadah tunggal advokat, serta Pasal 28 ayat (1) yang mengatur kewenangan pengawasan, memiliki ruang penafsiran yang terlalu luas. Hal ini kerap dimanfaatkan pihak‑pihak tertentu untuk menguasai kendali organisasi, bahkan mengintervensi kemandirian advokat dalam menjalankan tugas profesinya.</p><p style=\"text-align: justify;\">“Ketika rumusan pasal tidak tegas memisahkan batas antara organisasi sebagai wadah berkumpul dan lembaga yang berwenang mengawasi atau membuat standar, maka konflik kepentingan tidak bisa dihindari. Di satu sisi organisasi harus melayani anggotanya, di sisi lain ia juga berwenang menjatuhkan sanksi. Ini tumpang tindih dan sangat rawan disalahgunakan,” ujar Dr.Teguh S.Utomo,S.Psi,SH,MH,MM.</p><p style=\"text-align: justify;\">Ia menambahkan, berbagai konflik kepengurusan dan sengketa kewenangan yang terjadi belakangan ini membuktikan bahwa mekanisme penyelesaian sengketa dalam undang‑undang lama sudah tidak efektif. Perselisihan yang berlarut‑larut tidak hanya merusak citra profesi, tetapi juga menyulitkan advokat menjalankan hak dan kewajibannya di mata hukum.</p><p style=\"text-align: justify;\">Arahan MK: Revisi Harus Hilangkan Konflik Kepentingan</p><p style=\"text-align: justify;\">Melalui putusannya, MK secara tegas menggarisbawahi bahwa revisi UU Advokat wajib memuat pengaturan fungsi organisasi profesi yang jelas dan terstruktur. Tujuannya adalah meniadakan potensi konflik kepentingan yang selama ini menjadi masalah utama organisasi.</p><p style=\"text-align: justify;\">MK juga menegaskan perlunya pembaruan mendasar pada tata kelola organisasi. Dalam desain ideal yang disarankan, harus ada pemisahan tegas antara fungsi organisasi profesi sebagai wadah aspirasi dan tempat berkumpul para advokat, dengan fungsi regulator atau pengawas profesi yang bersifat netral dan independen.</p><p style=\"text-align: justify;\">“Inti desain yang diminta MK adalah pemisahan fungsi. Kita tidak boleh lagi menggabungkan dua hal yang bertolak belakang dalam satu badan yang sama. Contoh konkretnya adalah pembentukan dewan atau konsil profesi. Lembaga inilah yang nantinya berwenang menetapkan standar, mengawasi kode etik, hingga menjatuhkan sanksi. Sementara organisasi profesi fokus pada pembinaan, perlindungan, dan peningkatan kualitas anggotanya,” jelas Dr.Teguh S.Utomo</p><p style=\"text-align: justify;\">Selain pemisahan fungsi, arahan MK juga mewajibkan adanya penetapan standar nasional profesi advokat. Standar ini mencakup persyaratan kompetensi, kode etik, hingga kualifikasi yang seragam di seluruh Indonesia, agar mutu pelayanan hukum menjadi terjamin dan terukur.</p><p style=\"text-align: justify;\">Harapan dan Tantangan di Depan Mata</p><p style=\"text-align: justify;\">Dengan tenggat waktu dua tahun yang diberikan, Dr.Teguh Suharto Utomo berharap DPR khususnya Komisi III &nbsp;dan Pemerintah tidak menunda penyusunan naskah revisi. Menurutnya, keterlambatan hanya akan memperpanjang masa ketidakpastian hukum yang sudah terlalu lama dirasakan.</p><p style=\"text-align: justify;\">“Revisi ini bukan sekadar mengubah beberapa pasal, melainkan merombak pola pikir dan struktur tata kelola. Kuncinya ada pada pemisahan organisasi dan regulator, serta adanya standar nasional yang jelas. Jika ini diterapkan, maka intervensi terhadap kemandirian advokat bisa diminimalisir, dan konflik internal yang berulang bisa diakhiri selamanya,” tegasnya.</p><p style=\"text-align: justify;\">Ia juga mengingatkan agar proses penyusunan revisi ini melibatkan partisipasi luas dari berbagai elemen organisasi advokat, akademisi, dan masyarakat. Hal ini penting agar undang‑undang baru nanti benar‑benar menjamin kemandirian profesi sekaligus memberikan kepastian hukum dan perlindungan bagi masyarakat pencari keadilan.</p><p style=\"text-align: justify;\">Putusan MK ini menjadi titik balik penting bagi dunia hukum Indonesia, membawa harapan baru agar profesi advokat kembali tegak sebagai penegak hukum yang independen, berintegritas, dan bebas dari konflik kepentingan.</p>','Foto: halusinasi XNN | SURABAYA,&nbsp;Ketidakjelasan makna serta batas kewenangan dalam aturan pengawasan organisasi profesi advokat akhirnya mendapat',1,'',8,NULL,'published','https://www.xyronnews.com/uploads/posts/post_6a35229968f5c.jpeg',13,'2026-06-19 18:06:01'),(81,'DUGAAN RANGKAP JABATAN: WAMENKO OTTO HASIBUAN DIGUGAT DI 4 PN','dugaan-rangkap-jabatan-wamenko-otto-hasibuan-digugat-di-4-pn','<p><font color=\"#3984c6\"><span style=\"text-align: justify; font-size: 24px; -webkit-tap-highlight-color: transparent; text-size-adjust: 100%;\">Foto:&nbsp;</span><span style=\"text-align: justify; font-size: 24px; -webkit-tap-highlight-color: transparent; text-size-adjust: 100%;\">Dr Teguh Suharto Utomo</span><span style=\"text-align: justify; font-size: 24px; -webkit-tap-highlight-color: transparent; text-size-adjust: 100%;\">&nbsp;&nbsp;</span></font></p><p><span style=\"text-align: justify; font-size: var(--bs-body-font-size); -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><br></span><span style=\"font-size: 20px; text-align: justify; -webkit-tap-highlight-color: transparent; text-size-adjust: 100%; font-family: Arial;\">Langgar 3 Putusan MK, Jabat Wamenko Sekaligus Ketum PERADI 3 Periode</span></p><p style=\"text-align: justify;\"><font color=\"#e76363\"><span style=\"font-family: Arial; font-size: 20px;\">XNN | JAKARTA</span></font><span style=\"font-family: Arial; font-size: 20px;\">, Wakil Menteri Koordinator Bidang Hukum, HAM, Imigrasi, dan Pemasyarakatan Otto Hasibuan digugat ke 4 Pengadilan Negeri terkait dugaan rangkap jabatan. Otto saat ini masih aktif menjabat sebagai Ketua Umum DPN PERADI, meski sudah dilantik jadi pejabat negara sejak 21 Oktober 2024.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: Arial; font-size: 20px;\">Menurut pendapat Hukum Ahli Hukum dan Ekonomi Dr Teguh Suharto Utomo \"Gugatan diajukan ke PN Balikpapan 8 Juni 2026, PN Jakarta Pusat 9 Juni 2026 lewat citizen lawsuit, PN Medan 19 Mei 2026, dan *PN Jakarta Timur 17 Juni 2026. Seluruhnya mempersoalkan posisi Otto yang merangkap Wamenko dan Ketum PERADI.</span></p><p style=\"text-align: justify;\"><span style=\"font-family: Arial; font-size: 20px;\">1. LANGGAR 3 PUTUSAN MK SEKALIGUS</span><span style=\"font-family: Arial; font-size: 20px;\">﻿</span></p><p style=\"text-align: justify;\"><span style=\"font-family: Arial; font-size: 20px;\">Kuasa hukum penggugat menilai </span><span style=\"font-family: Arial; font-size: 20px;\">rangkap jabatan Otto melanggar 3 putusan Mahkamah Konstitusi yang bersifat final dan mengikat atau erga omnes:</span></p><p style=\"text-align: justify;\"><span style=\"font-family: Arial; font-size: 20px;\">1. Putusan MK 91/PUU-XX/2022 : Batasi masa jabatan pimpinan organisasi advokat maksimal 2 periode. Otto tercatat memimpin PERADI 3 periode: 2005-2010, 2010-2015, da</span><span style=\"font-size: 20px;\">n 2020-2025.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">2. Putusan MK 183/PUU-XXII/2024: Wajibkan pimpinan organisasi advokat nonaktif seketika jika diangkat jadi pejabat negara, termasuk menteri/wamen, untuk cegah konflik kepentingan.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">3. Putusan MK 128/PUU-XXIII/2025 jo UU 39/2008*: Larang menteri dan wamen rangkap jabatan sebagai pimpinan organisasi yang dibiayai APBN/APBD.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">“Ini bentuk pembangkangan nyata terhadap hukum. Putusan MK kedudukannya setara UU. Alasan putusan MK kabur adalah narasi menyesatkan demi pertahankan kekuasaan,” tegas sumber.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">2. JABATAN PUBLIK TUNDUK UU KEMENTERIAN NEGARA</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">Otto resmi ditetapkan sebagai Wamenko Bidang Hukum, HAM, Imigrasi, dan Pemasyarakatan dalam pengumuman Kabinet Merah Putih Oktober 2024. Sebagai wamen, jabatannya tunduk pada Pasal 23 UU Kementerian Negara.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">MK dalam Putusan 128/PUU-XXIII/2025 menegaskan wamen dilarang rangkap jabatan sebagai pejabat negara lain, komisaris/direksi BUMN/swasta, serta pimpinan organisasi yang dibiayai APBN/APBD. Larangan ini demi tata kelola pemerintahan yang bersih dan bebas konflik kepentingan. MK beri tenggang waktu penyesuaian 2 tahun sejak putusan diucapkan.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">3. KONFLIK KEPENTINGAN DI SOROT</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">Dari sisi hukum administrasi, pejabat publik wajib jalankan kewenangan berdasar UU dan Asas Umum Pemerintahan yang Baik (AUPB). Jika pejabat tetap pegang peran aktif di organisasi profesi yang punya kepentingan langsung terhadap kebijakan negara, muncul potensi konflik kepentingan.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">“Persoalannya bukan semata etika, tapi keraguan atas objektivitas penggunaan kewenangan, terutama soal Organisasi Advokat,” kata sumber hukum.</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 20px;\">Hingga berita ini turun, belum ada keterangan resmi dari Otto Hasibuan maupun DPN PERADI terkait gugatan rangkap jabatan tersebut.</span></p>','Foto:&nbsp;Dr Teguh Suharto Utomo&nbsp;&nbsp;Langgar 3 Putusan MK, Jabat Wamenko Sekaligus Ketum PERADI 3 PeriodeXNN | JAKARTA, Wakil Menteri Koordina',1,'',8,1,'published','https://www.xyronnews.com/uploads/posts/post_6a35654e977ef.jpeg',28,'2026-06-19 22:50:00');
